WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[1] = { title = "Kanrethad's Quest", description = "Welcome back from the world of death. \n\nIn an age long past you stood proud, a hero among your brethren. Now you stand fallen and broken - a relic of the past. Stand before me, as I awaken the legend that you once were. \n\n I shall restore the weapons and powers you have lost, making you whole once again.You will receive:", objectives = "Speak to Kanrethad to restore your talents, weapon and mount." }
WordHunterWoW_QuestEN[2] = { title = "Sharptalon's Claw", description = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.\n\nSenani Thunderheart at the Silverwind Refuge will no doubt be interested in seeing this trophy as proof of your deeds.", objectives = "Bring Sharptalon's Claw to Senani Thunderheart at Silverwind Refuge.", progress = "What have you there, <class>? Could it be....?", completion = "You have slain the beast?\n\nI owe you a great debt, friend. That beast terrorized many over the years, but its death holds special meaning to me.\n\nYou see, recently my brother fell victim to these very claws... I shall sleep well now, knowing that he has been avenged." }
WordHunterWoW_QuestEN[5] = { title = "Jitters' Growling Gut", description = "I've been stuck hiding in this ghost town for weeks, and I haven't eaten anything but grubs and weeds!  I need some decent food, and I'm willing to trade well for it.\n\nBring me a feast and I'll pay you handsomely.\n\nI heard Chef Grual at the Scarlet Raven Tavern in Darkshire makes very good Dusky Crab Cakes...", objectives = "Speak with Chef Grual.", completion = "You need some Crab Cakes, do you?  Well I might be able to cook some up for you..." }
WordHunterWoW_QuestEN[6] = { title = "Bounty on Garrick Padfoot", description = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!\n\nBut be wary, <name>.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", objectives = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", progress = "Did you find Garrick's shack?  Are we finally free of that villain?", completion = "Hah - you caught him!  You've done Elwynn a great service, and earned a nice bounty!" }
WordHunterWoW_QuestEN[7] = { title = "Kobold Camp Cleanup", description = "Your first task is one of cleansing, <name>.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", objectives = "Kill 6 Kobold Vermin, then return to Marshal McBride.", completion = "Well done, citizen.  Those kobolds are thieves and cowards, but in large numbers they pose a threat to us.  And the humans of Stormwind do not need another threat.\n\nFor defeating them, you have my gratitude." }
WordHunterWoW_QuestEN[8] = { title = "A Rogue's Deal", description = "Hey, mate! Do a favor for a young man who's been fighting more than his fair share of mindless zombies and spiders?\n\nI got this here letter that needs to go to Brill... to an innkeeper named Renee something-or-other. Don't really matter none what her last name is.\n\nAnyway, it's a nice cozy little place full of victims of the plague trying to make their way in the world. And it be a great spot for you to rest too if the need arises. You should check it out... you do and I'll pay you well.", objectives = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.", progress = "Yes? Yes? What is it?\n\nThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name's Renee if you need anything at all.", completion = "Oh? A letter? Wonderful news! I've been waiting on word from my dear old mother in Deathknell. Such a saint, she is. I wonder how she's holding up.\n\nWhat? Too cheery? Not buying it, are you?\n\nWell, get lost then... it's really no business who the letter's from anyway. Go on! Get lost!\n\nCome back when you've got some coin to spend... loafer.\n\nNext thing you know, you'll be coming back to rest after a long days adventure or some stupid thing like that." }
WordHunterWoW_QuestEN[9] = { title = "The Killing Fields", description = "Look at what has happened to this place!  These lands were once occupied by good farm folk.  But the damned thieves have driven them all off.  Not me, though!  But it seems some Harvest Watchers have taken over the fields.\n\nIf you're up for the work, I'd like you to go out and kill twenty of them.  Come back when you're done for your pay.  If you finish up with the ones in my field, clear them from the neighboring fields as well.", objectives = "Farmer Saldean wants you to kill 20 Harvest Watchers.", completion = "Good work, friend.  You have earned your pay well.  Who knows, perhaps Westfall will prosper once again." }
WordHunterWoW_QuestEN[10] = { title = "The Scrimshank Redemption", description = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?\n\nI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod.", objectives = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", progress = "Well, what news do you have?  You look like you've been in quite the fight... is Scrimshank alive?", completion = "He was a good goblin, young Scrimshank.  Let's hope that his demise was not in vain by what he was able to record with his surveying equipment.\n\nIt seems as though we have quite the situation on our hands here with these bugs.  They're way too cunning for their own good, and the research we've done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!" }
WordHunterWoW_QuestEN[11] = { title = "Riverpaw Gnoll Bounty", description = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east.\n\nThe Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.", objectives = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.", progress = "Hail, <name>.  Have you been killing Gnolls...?", completion = "I see you've been busy!  You have our thanks, <name>." }
WordHunterWoW_QuestEN[12] = { title = "The People's Militia", description = "The People's Militia has but one goal:  To defend the lands of Westfall and return peace to our surroundings.  Unfortunately, the price of peace is often blood. \n\nOne of my scouts has brought word of a band of Defias Trappers wreaking havoc nearby.  I have reports of Defias Trapper sightings near the Jangolode Mine to the Northwest as well as at the Molsen Farm and Furlbrow's Pumpkin Farm. If you seek to join our ranks, slay 15 Defias Trappers and 15 Defias Smugglers then return to me.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.", completion = "Well done, <name>.  My scout witnessed your valiant acts.  You are proving yourself quite well so far." }
WordHunterWoW_QuestEN[13] = { title = "The People's Militia", description = "A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, <name>, and make the Light's presence known in Westfall.\n\nThe Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.", completion = "Your worth to The People's Militia has been validated by your brave acts thus far." }
WordHunterWoW_QuestEN[14] = { title = "The People's Militia", description = "Some Defias have eluded us.  My most trusted scout reports that these Defias have been looting and pillaging the countryside, all the way into Southern Westfall.  We believe they are hiding out in the Dagger Hills, plotting their next move.   Slay the wretches in the name of The People's Militia.", objectives = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.", completion = "When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland.  But there is hope for Westfall yet.  As proven by your valor in battle, it is obvious to me that you serve our cause with honor.  It is with great pride that I induct thee into The People's Militia.  May the Light shine upon you." }
WordHunterWoW_QuestEN[15] = { title = "Investigate Echo Ridge", description = "<name>, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.\n\nGo to the mine and remove them.  We know there are at least 8.  Kill them, see if there are more, then report back to me.", objectives = "Kill 8 Kobold Workers, then report back to Marshal McBride.", completion = "I don't like hearing of all these kobolds in our mine.  No good can come of this.  Here, take this as payment, and when you're ready, speak to me again.  I would like you to go back to the mines one more time..." }
WordHunterWoW_QuestEN[16] = { title = "Give Gerard a Drink", description = "", objectives = "Farming is thirsty work, and I'm always looking for refreshing spring water.\n\nIf you have any, then I'm willing to make a trade.", progress = "Farming is thirsty work, and I'm always looking for refreshing spring water.\n\nIf you have any, then I'm willing to make a trade.", completion = "Thanks, <name>!  And come back if you want to trade again." }
WordHunterWoW_QuestEN[17] = { title = "Uldaman Reagent Run", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done <name>, you've proven your worth once again!  The caps will be an interesting study, yon verily!\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!" }
WordHunterWoW_QuestEN[18] = { title = "Brotherhood of Thieves", description = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.\n\nI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", objectives = "Bring 8 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", progress = "Have you gathered those bandanas for me yet?", completion = "Back with some bandanas, I see.  The Stormwind Army appreciates your help." }
WordHunterWoW_QuestEN[19] = { title = "Tharil'zun", description = "Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep.  The leader of the Outrunners is an orc named Tharil'zun--we want this orc.  Bring me the head of Tharil'zun!", objectives = "Bring Tharil'zun's Head to Marshal Marris in Redridge.", progress = "Orc pressure from Blackrock is still tense.  But have you at least rid us of Tharil'zun?", completion = "Tharil'zun was a vicious, crafty orc.  Well done--I'm sure he didn't go down easy.  Here is your reward, <name>." }
WordHunterWoW_QuestEN[20] = { title = "Blackrock Menace", description = "The Blackrock orcs have travelled from the Burning Steppes and claimed Stonewatch Keep to the north.  From there they maraud the areas north of Lakeshire and keep its citizens in town, penned like cattle.\n\nHelp rid Lakeshire of this menace.  Kill these Blackrock orcs and bring me ten of their Battleworn Axes as proof.\n\nAnd although Blackrocks threaten us from the north, we've received reports of more in the southeastern pocket of Redridge.  If you find any there, then they too should be hunted.", objectives = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", progress = "Have you been slaying orcs, <name>?  If so, then show me...", completion = "That makes for a lot fewer orcs to worry about, thanks." }
WordHunterWoW_QuestEN[21] = { title = "Skirmish at Echo Ridge", description = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, <name>.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", objectives = "Kill 8 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", completion = "Once again, you have earned my respect, and the gratitude of the Stormwind Army.  There may yet be kobolds in the mine, but I will marshal others against them.  We have further tasks for you." }
WordHunterWoW_QuestEN[22] = { title = "Goretusk Liver Pie", description = "The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!", objectives = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.", progress = "All I need for my famous meat pie are 8 Goretusk Livers!", completion = "These are just perfect, <name>!  Thank you so much.  Farmer Saldean and I are going to feast tonight.  And here is a little something for you, for the hard work.  You didn't think I was going to let a <class> like you go hungry, did you?" }
WordHunterWoW_QuestEN[23] = { title = "Ursangous' Paw", description = "The mighty bear Ursangous is no more!\n\nThe small quarter-crescent emblem on its paw indicates that this beast was trained by the night elves to prowl the forest in search of their enemies. There is no telling how many of your Horde allies fell to this creature.\n\nThe paw should be brought to Tarkan at Silverwind Refuge. He will be pleased that such a weapon has been removed from the enemy's arsenal.", objectives = "Bring Ursangous' Paw to Captain Tarkan at Silverwind Refuge.", progress = "What is it, <race>?", completion = "The paw of Ursangous!\n\nHave you any idea what trouble this beast has caused us over the years? Those days are over now, thanks to you.\n\nI shall forward this trophy on to Orgrimmar to be put on display, along with your account of its death.\n\nCongratulations!" }
WordHunterWoW_QuestEN[24] = { title = "Shadumbra's Head", description = "The once swift Shadumbra now lies still as you claim victory over it.\n\nThis legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale.\n\nCaptain Goggath at Hellscream's Watch will no doubt be delighted to receive the head of the slain nightsaber.", objectives = "Bring Shadumbra's Head to Captain Goggath at Hellscream's Watch.", progress = "Yes, <class>?", completion = "Shadumbra's Head?\n\nNone can say how many of our Horde brethren have fallen to this beast over the years. Your prowess has ensured that no more shall suffer this fate.\n\nWarchief Hellscream shall hear of your deeds, <class>." }
WordHunterWoW_QuestEN[25] = { title = "Simmer Down Now", description = "You should've seen it, {class}!\n\nThe elves thought Silverwind to be impenetrable. With its heavy defenses and their army of water elementals, they were almost right.\n\nAlmost.\n\nOne of our mages was able to summon a twisted elemental designed to send the others into a chaotic rage.\n\nAhh, the looks on their faces!\n\n<Tarkan laughs.>\n\nUnfortunately, the mage who summoned it fell in battle. Now I need someone to bring down our creation.", objectives = "Captain Tarkan at Silverwind Refuge wants you to defeat Tideress and 12 Befouled Water Elementals at Mystral Lake.", completion = "Well done, <class>.\n\nA fitting end to a textbook assault." }
WordHunterWoW_QuestEN[26] = { title = "A Lesson to Learn", description = "<name>, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", completion = "Salutations, young <class>; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us." }
WordHunterWoW_QuestEN[27] = { title = "A Lesson to Learn", description = "<name>, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", objectives = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", completion = "Salutations, young <class>; the time has come for you to know our aquatic form. It is one that lets you move freely and indefinitely through water. You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome. The first will test your ability to work in water under pressure. The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us." }
WordHunterWoW_QuestEN[28] = { title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, <name>.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", completion = "Well now, it looks like yet another <class> has successfully completed the Trial of the Lake! Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such. By using the bauble here, it serves as a nod to the importance of this place within the Circle." }
WordHunterWoW_QuestEN[29] = { title = "Trial of the Lake", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, <name>.", objectives = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", completion = "Well now, it looks like yet another <class> has successfully completed the Trial of the Lake! Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri. It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine. Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such. By using the bauble here, it serves as a nod to the importance of this place within the Circle." }
WordHunterWoW_QuestEN[30] = { title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", progress = "Have you formed your pendant for me to inspect, <name>? If you need help in locating the parts, try asking the local populace for information. Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, <name> - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form." }
WordHunterWoW_QuestEN[31] = { title = "Aquatic Form", description = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.You will receive:", objectives = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion." }
WordHunterWoW_QuestEN[32] = { title = "Rise of the Silithid", description = "Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.\n\nI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.\n\nZil lives in a house on the second tier of the Drag in Orgrimmar.", objectives = "Take the report to Zilzibin Drumlore in Orgrimmar.", progress = "I'm sorry, I don't know you... but from the look of things you have at least heard something of me.  Now, what can I help you with?  Do you have something for me?", completion = "This report... I've dealt with these beasts before.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, <name>: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before." }
WordHunterWoW_QuestEN[33] = { title = "Wolves Across the Border", description = "Whatever is affecting these wolves isn't going away. Each day that passes brings forth more sick wolves. It pains me to ask anyone to kill nature's beasts, but we must destroy the diseased young wolves before this little outbreak turns into an epidemic.\n\nKill diseased young wolves in the valley and bring me their diseased wolf pelts as proof of your deed.", objectives = "Bring 8 Diseased Wolf Pelts to Eagan Peltskinner outside Northshire Abbey.", progress = "Hey <name>. How goes the hunt for diseased young wolves?", completion = "'Twas a grim task, friend, but you held up your part of the bargain.\n\nI have some things here you might want - take your pick!" }
WordHunterWoW_QuestEN[34] = { title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", objectives = "Martie Jainrose of Lakeshire wants you to kill Bellygrub. Bring her his tusk as proof.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, <name>, you have done me a great service.  The garden shall be in full bloom this season!" }
WordHunterWoW_QuestEN[35] = { title = "Further Concerns", description = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nI have here a Stormwind charger that will take you to Guard Thomas. Let me know if you wish to make use of the horse.", objectives = "Marshal Dughan wants you to speak with Guard Thomas.", completion = "Yes, murlocs have settled in and around the streams of eastern Elwynn.  We don't know why they are here, but they are aggressive and at least semi-intelligent." }
WordHunterWoW_QuestEN[36] = { title = "Westfall Stew", description = "I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.  \n\nMaybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.", objectives = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.", progress = "I'm going to miss that Verna Furlbrow so much.  I don't suppose you happened to see her on your way here?", completion = "That Verna was always such a sweet lass.  We'll miss her here in Westfall but between you and me, she's a city girl at heart and Stormwind will suit her just fine.  But enough gossip!  Now we can make Westfall Stew!" }
WordHunterWoW_QuestEN[37] = { title = "Find the Lost Guards", description = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.", objectives = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.", completion = "Although much has been stripped from the corpse, strewn nearby is a medallion with the words: \"Footman Malakai Stone\" etched upon it." }
WordHunterWoW_QuestEN[38] = { title = "Westfall Stew", description = "Help me make some Westfall Stew!  Come back with the following ingredients: \n\n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra", objectives = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.", progress = "Come back with the following ingredients: \n\n 3 Stringy Vulture Meat \n 3 Goretusk Snouts \n 3 Murloc Eyes \n 3 Okra", completion = "That Okra will thicken up this broth nicely!  Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts.  And we're done!  For all your help, <name>, I want you to take today's first batch of Westfall Stew!" }
WordHunterWoW_QuestEN[39] = { title = "Deliver Thomas' Report", description = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.\n\nI know we don't have many troops to spare, but hopefully Dughan can find someone.", objectives = "Report to Marshal Dughan in Goldshire.", completion = "Hmm, this news is troubling.  Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.\n\nIf things don't improve, there will be fighting in Goldshire by the week's end!" }
WordHunterWoW_QuestEN[40] = { title = "A Fishy Peril", description = "{name}, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, {name}, speak to Dughan and persuade him to send more troops to the east!", objectives = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.", completion = "Yes, I spoke with Remy.  I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.\n\nYour concerns are noted, but unless I receive a military report of a murloc threat, we can't afford to send more troops east." }
WordHunterWoW_QuestEN[45] = { title = "Discover Rolf's Fate", description = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...", objectives = "Search the murloc village for Rolf, or signs of his death.", completion = "You find around the neck of the corpse a metal medallion inscribed with the words: \"Footman Rolf Hartford.\"" }
WordHunterWoW_QuestEN[46] = { title = "Bounty on Murlocs", description = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring Guard Thomas their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.", objectives = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.", progress = "How goes the hunting, <name>?", completion = "You have the fins?  Great!  Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I'd like to tell him that it's becoming under control.\n\nYour actions have helped realize that." }
WordHunterWoW_QuestEN[47] = { title = "Gold Dust Exchange", description = "The kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.", objectives = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire. Gold Dust is gathered from Kobolds in Elwynn Forest.", progress = "Psst!  You have that Gold Dust for me...for me?", completion = "Thanks for the dust, <name>.  Here's your cash, and...here is a token from associates of mine.  You might find it useful...useful." }
WordHunterWoW_QuestEN[48] = { title = "Sweet Amber", description = "In the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", objectives = "Bring Holy Spring Water to Grimbooze Thunderbrew.", progress = "Hiccup! Ho ho!  You want an encore?\n\nIn the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", completion = "Hiccup! Ho Ho!" }
WordHunterWoW_QuestEN[49] = { title = "Sweet Amber", description = "Amber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", objectives = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.", progress = "Encore? Well, sure!\n\nAmber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", completion = "Hiccup! Ho ho!" }
WordHunterWoW_QuestEN[50] = { title = "Sweet Amber", description = "I'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", objectives = "Grimbooze Thunderbrew wants Truesilver.", progress = "An encore for you?  Well sure friend!\n\nI'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", completion = "Hiccup! Ho ho!" }
WordHunterWoW_QuestEN[51] = { title = "Sweet Amber", description = "Not yet filtered but freshly distilled\nLike unseeded land waiting there tilled.\nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", objectives = "Bring a Sycamore Branch to Grimbooze Thunderbrew.", progress = "An encore?  Why for you, anything!\n\nNot yet filtered but freshly distilled\nLike unseeded land waiting there tilled. \nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", completion = "Hiccup! Ho ho!" }
WordHunterWoW_QuestEN[52] = { title = "Protect the Frontier", description = "Hail, {name}.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.", objectives = "Kill 8 Prowlers or Gray Forest Wolves and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.", progress = "Have you killed those wolves and bears?", completion = "Thanks a lot for the help, <name>.  Something in the forest must be making these animals so bold.\n\nWhatever it is, I hope it stays there." }
WordHunterWoW_QuestEN[53] = { title = "Sweet Amber", description = "Mellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", objectives = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.", progress = "Sure, I'll sing it again for you, friend!\n\nMellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", completion = "Aged in the barrel, filtered through coal\nIt passes your lips and right through your soul.\nSo lets us drink now, a toast to you\nAnd me while we're at it, Grimbooze Thunderbrew!" }
WordHunterWoW_QuestEN[54] = { title = "Report to Goldshire", description = "{name}, you are a {class} with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire. Goldshire lies along the southern road, past the border gates.", objectives = "Take Marshal McBride's Documents to Marshal Dughan at Goldshire in Elwynn Forest.", progress = "You have word from McBride?  Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.\n\nHere, let me have his papers...", completion = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals.  Congratulations.\n\nAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!\n\nIt's hard to keep track of politics in these dark days..." }
WordHunterWoW_QuestEN[55] = { title = "Morbent Fel", description = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...\n\nUse Morbent's Bane against him.  It will render his protective magics powerless.\n\nSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!", objectives = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", progress = "Is Morbent Fel defeated?!", completion = "Morbent Fel has been defeated.  The dark riders are still at large, but a small piece of that which I had hoped beyond hope has come to pass.\n\nYou have done the impossible, and your deeds will forever live in the legends of Duskwood.\n\nGo, <name>.  And perhaps, one day, fate may bring you back to me..." }
WordHunterWoW_QuestEN[56] = { title = "The Night Watch", description = "As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.\n\nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.", completion = "Splendid, <name>.  For your service to the people of Darkshire you shall be rewarded." }
WordHunterWoW_QuestEN[57] = { title = "The Night Watch", description = "<name>, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.", completion = "The people of Darkshire thank you, <name>.  You have proven yourself to be a great ally of The Night Watch." }
WordHunterWoW_QuestEN[58] = { title = "The Night Watch", description = "The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, <name>.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!", objectives = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.", completion = "On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, <name>, for your bravery and dedication.  May the Light shine upon your ways." }
WordHunterWoW_QuestEN[59] = { title = "Cloth and Leather Armor", description = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, {name}, use it in the defense of Elwynn.\n\nEastvale is just east of this post across the bridge.", objectives = "Give Sara Timberlain the Stormwind Armor Marker.", progress = "I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.\n\nIf you have a marker for me, then I'd be happy to make you something.", completion = "Ah, thank you for the marker.  Please feel free to pick your choice of armor.\n\nLuck to you, brave <class>.  And may this armor serve you well." }
WordHunterWoW_QuestEN[60] = { title = "Kobold Candles", description = "Hello, good sir!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines... the Fargodeep Mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.", objectives = "Bring 8 Large Candles to William Pestle in Goldshire.", progress = "Did you gather those candles yet?", completion = "You were busy hunting kobolds, were you?  Thanks for the candles, <name>, and here's your reward..." }
WordHunterWoW_QuestEN[61] = { title = "Shipment to Stormwind", description = "My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.\n\nI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.", objectives = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.", progress = "Oh, a shipment from my brother?  Splendid!  Fortune truly shines on me today!", completion = "Here is your payment ... and while you're here, take a look around!  I'm sure we have a potion or other trinket you'd find useful." }
WordHunterWoW_QuestEN[62] = { title = "The Fargodeep Mine", description = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.", objectives = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.", completion = "This is bad news.  What's next, dragons?!?  We'll have to increase our patrols near that mine.  Thanks for your efforts, <name>.  And hold a moment... I might have another task for you." }
WordHunterWoW_QuestEN[63] = { title = "Call of Water", description = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.\n\nTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.\n\nBring me proof the task is done, and I will reward you with your totem.Upon completion of this quest you will gain:", objectives = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest." }
WordHunterWoW_QuestEN[64] = { title = "The Forgotten Heirloom", description = "It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!", objectives = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.", progress = "Don't suppose you were able to get my watch?", completion = "My watch!  Thank you so much, kind sir! \n\nWe are but poor farmers and we have lost our land but please accept this reward as a token of our appreciation." }
WordHunterWoW_QuestEN[65] = { title = "The Defias Brotherhood", description = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.", objectives = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", completion = "So, Stoutmantle sent you?  Well, I owe him." }
WordHunterWoW_QuestEN[66] = { title = "The Legend of Stalvan", description = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.\n\nAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.\n\nSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.", objectives = "Seek out the Clerk Daltry in the Darkshire Town Hall.", completion = "Ah so Madame Eva sent you. . . ." }
WordHunterWoW_QuestEN[67] = { title = "he Legend of Stalvan", description = "Stalvan, eh?  Let me check the town registry.\n\nStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!\n\nDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.", objectives = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.", completion = "The old footlocker creaks open. . . ." }
WordHunterWoW_QuestEN[68] = { title = "The Legend of Stalvan", description = "You find a Dusty Unsent Letter in the old footlocker.", objectives = "Take the Dusty Unsent Letter to Clerk Daltry.", progress = "Ah, I remember you.  You're the one who was asking about that Stalvan fellow.  Did you ever find what you were looking for?", completion = "Interesting.  So the chap did spend some time in Moonbrook after all.  It is rather odd the letter never got delivered.  Nonetheless, I shall update the registry." }
WordHunterWoW_QuestEN[69] = { title = "he Legend of Stalvan", description = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, <name>.", objectives = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.", completion = "Stalvan?  Sure sounds familiar." }
WordHunterWoW_QuestEN[70] = { title = "The Legend of Stalvan", description = "The name Stalvan rings a bell.  I remember now.\n\nMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.\n\nIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.", objectives = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.", progress = "What have ya got there?  Let me take a look at that. . .", completion = "You've got some nerve bringing this here." }
WordHunterWoW_QuestEN[71] = { title = "Report to Thomas", description = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.", objectives = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.", progress = "Hello, <name>.  Have you discovered the fates of Rolf and Malakai?", completion = "You have confirmed my fears, <name>.  The murlocs are a threat we cannot ignore." }
WordHunterWoW_QuestEN[72] = { title = "The Legend of Stalvan", description = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.", objectives = "Search through the packed up possessions for a clue.My father was the caretaker of the estate long before I was. He had to mop the blood up after the massacre. But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up. Now the last of the family possessions are headed for auction. Blame the tax vultures. I guess if you're really itching to learn more you're free to look through this junk. Who knows what you might find.", completion = "You slowly slide the lid of the crate off. . . ." }
WordHunterWoW_QuestEN[74] = { title = "The Legend of Stalvan", description = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.", objectives = "The Torn Journal page you discovered provides your next clue.", progress = "What have you got there?  I cannot see.  My eyesight is very bad.  Put it in my hands.", completion = "I can barely make out those letters.  But that writing style reminds me of something I once saw before my vision became so poor." }
WordHunterWoW_QuestEN[75] = { title = "The Legend of Stalvan", description = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. \n\nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.", objectives = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.", progress = "Did you find that page I mentioned, <name>?", completion = "You found it!" }
WordHunterWoW_QuestEN[76] = { title = "The Jasperlode Mine", description = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.", objectives = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.", progress = "Hail, <name>.  What do you have to report? Have you scouted the Jasperlode Mine?", completion = "Kobolds at the Jasperlode Mine, you say?  Curses!  The situation is worsening by the minute!\n\nThank you for the report, <name>.  But I wish that the news you brought was good news." }
WordHunterWoW_QuestEN[77] = { title = "A Sticky Situation", description = "I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.\n\nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.", objectives = "Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.", progress = "I trust that your arrival here at our camp is to deliver the bottles of ripple that are integral to the task at hand, yes?", completion = "Finely executed, <name>.  I am glad you had enough foresight not to bruise the delicacy of the ripple.  There is nothing worse than the bouquet of ripple that has been jostled about needlessly.\n\nIt will take a moment for the magic to be wrought over this precious cargo.  Actually, no magic is involved; I merely have some empty packaging for Hinterlands Honey Ripple.  Our chicanery shall turn these bottles into an alcoholic treasure of the ages.\n\nOnward - for great booze!" }
WordHunterWoW_QuestEN[78] = { title = "The Legend of Stalvan", description = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.", objectives = "Take the Faded Journal Page to Tavernkeep Smitts at Darkshire in Duskwood.", progress = "Marshal Haggard sent you?  Why didn't you say so? \n\nAh, good ol' Haggard.  Poor chap is going to be completely blind before long.  Anyway, let me see what you've got there.", completion = "By the Light!  You bet I recognize that handwriting." }
WordHunterWoW_QuestEN[79] = { title = "The Legend of Stalvan", description = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!", objectives = "Take the muddy page to Commander Ebonlocke.", progress = "This better be good, <class>.  Let me see what you have and tell me your tale.  But by the Light, be quick about it.  Darkshire's defense is my number one priority.  I have not the time to squander on dead-end leads.", completion = "My, you have proved yourself to be quite a detective, <class>." }
WordHunterWoW_QuestEN[80] = { title = "The Legend of Stalvan", description = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.\n\nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.", objectives = "Show Clerk Daltry the Bloodstained Journal Page.", progress = "Back again, <name>?  What do you have this time?", completion = "Why yes!  The writing on this page does in fact match that of the registry signatures." }
WordHunterWoW_QuestEN[81] = { title = "Ripple Delivery", description = "I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome.\n\nNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.", objectives = "Deliver the barrel to Dran Droffers in Orgrimmar.", progress = "If you're not here to buy anything, and you're not here to deliver anything, then you're wasting my time!  You better have that ripple!", completion = "Well, let's see what's in this barrel!\n\nYes, yes, it looks as though it is all here.  Here's your fee for the package, good job on that.  I stand to make five times that fee when I sell it to the tavern!  Har har!\n\nThese extra bottles of Hinterlands Honey Ripple are going to be set for a special occasion.  I think I'll drink some with champagne.  I'll call it... champipple." }
WordHunterWoW_QuestEN[82] = { title = "Noxious Lair Investigation", description = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!", objectives = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", progress = "You're Junior Surveyor <name>, yes?  Quickly now, there is a dire situation at hand!  Do you have the insect parts that Fizzledowser said you would?!", completion = "Good work - I'll start my analysis on these now!  I can tell you right from the start though... these are nothing like any insect form I have ever seen.  It's almost as if these bugs are being controlled by an outside force or something.\n\nYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double!  I'm not sure, but I think it involves more of the bugs in the Tanaris desert!" }
WordHunterWoW_QuestEN[83] = { title = "Fine Linen Goods", description = "The thugs in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me linen scraps and I'll use them to fashion something for you.\n\nYou'll find those lawless criminals in pockets across Elwynn Forest.", objectives = "Bring 6 Linen Scraps to Sara Timberlain at the Eastvale Logging Camp.", progress = "I'm running low on linen, <name>.  Do you have any for me?", completion = "Ah, these are nice scraps, if a little rough...\n\nHere you are!" }
WordHunterWoW_QuestEN[84] = { title = "Back to Billy", description = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!", objectives = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.", progress = "Ugh... I'm starving!  Do you have that pie for me, <name>?", completion = "Mm, yum!  This pie is the best!\n\nI think my memory is coming back to me..." }
WordHunterWoW_QuestEN[85] = { title = "Lost Necklace", description = "I lost my necklace and I think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure Vineyards east of here. \n\nGet my necklace back for me and you'll warm an old widow's heart.", objectives = "Speak with Billy Maclure.", completion = "You lost a what?  Well I didn't take no necklace, because I ain't no thief!\n\nI might know who did but...<grin>...I'm too hungry to remember." }
WordHunterWoW_QuestEN[86] = { title = "Pie for Billy", description = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some tender boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.", objectives = "Bring 4 Tender Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.", progress = "I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it!\n\nDo you have that boar meat?", completion = "Though this wild boar meat is bland, simmer it enough in the right spices and it sure does make for some tasty pie!" }
WordHunterWoW_QuestEN[87] = { title = "Goldtooth", description = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run back to his den above the mine.  Go find that kobold and you'll find the necklace, I swear!", objectives = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.", progress = "Hello, <name>.  Have you found my necklace?", completion = "Oh, you found it!  Thank you, thank you dear!\n\nHere, take this.  It was my husband's and he always said it was lucky.  If only he didn't forget it on his last campaign! *sniff*" }
WordHunterWoW_QuestEN[88] = { title = "Princess Must Die!", description = "The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nIt just so happens that she's here now! Princess must die! Bring me her collar as proof of the deed and I'll give you something for your time!\n\nYou'll find Princess smack dab in the middle of our watermelon patch. Get her!", objectives = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.", progress = "Did you see her yet?  Did you get her?", completion = "Thank goodness!  That pig was getting so big she'd have eaten our whole crop!  Thank you, <name>.\n\nNow, do any of these suit you?" }
WordHunterWoW_QuestEN[89] = { title = "The Everstill Bridge", description = "During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire.\n\nNow we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, <name>, I'll make sure you're rewarded. \n\nNow let's get to work!", objectives = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.", progress = "This bridge isn't going to build itself!  Now where are those iron pikes and iron rivets?", completion = "Great work, <name>.  These supplies will help the bridge effort immensely.  We'll get this beauty shored up in no time." }
WordHunterWoW_QuestEN[90] = { title = "Seasoned Wolf Kabobs", description = "Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.", objectives = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.", progress = "Were you able to find 10 Lean Wolf Flanks yet?  How about the herbs from Felicia in Stormwind?", completion = "Very nice work, <name>!  Enjoy the delicacy known as Seasoned Wolf Kabob!" }
WordHunterWoW_QuestEN[91] = { title = "Solomon's Law", description = "An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business.\n\nMorganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death.\n\nThese vile gnolls must be killed!\n\nTurn in 10 Shadowhide Pendants to me, and you shall be rewarded.", objectives = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.", progress = "Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.", completion = "The Court of Lakeshire recognizes your commitment to justice, <name>.  By enforcing the laws of the Kingdom you have helped uphold the justice of the land." }
WordHunterWoW_QuestEN[92] = { title = "Redridge Goulash", description = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", objectives = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", progress = "I still need five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", completion = "Well done, <name>. Such fine specimens too! And here is your delicious delicacy known as Redridge Goulash!" }
WordHunterWoW_QuestEN[93] = { title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them.\n\nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river.", objectives = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.", progress = "Hail, <name>.  Did you get those Gooey Spider Legs yet?", completion = "Ah yes, a nice clutch of legs you have there!  Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good." }
WordHunterWoW_QuestEN[94] = { title = "A Watchful Eye", description = "My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.\n\nBut to study his thoughts ... I require further aid.\n\nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower.\n\nWhen this is done, the power of Azora will grant visions of Morganth's future plans.", objectives = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.", progress = "This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.\n\nThere is a depression at the base of the statue, where a gem or glyph might be set...", completion = "You place the Glyph of Azora on the stone.  It adheres itself ... and you hear from it Theocritus' disembodied voice:\n\nYou have my gratitude, young <name>.  You may now speak with me through this Glyph, and I might have future tasks for you ... after I have probed the thoughts of my rival." }
WordHunterWoW_QuestEN[95] = { title = "Sven's Revenge", description = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn.", objectives = "Go to Sven's Farm and find what was buried behind the old stump.I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something. He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders. So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful. The hiding spot is behind the old stump near my barn.", completion = "A mound of dirt is here, hastily piled up as if someone had need of hiding something...without much time to do it." }
WordHunterWoW_QuestEN[96] = { title = "Call of Water", description = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.You will learn:", objectives = "Bring the Shard of Water to Islen Waterseer at the Tidus Stair in the Barrens." }
WordHunterWoW_QuestEN[97] = { title = "he Legend of Stalvan", description = "Let Commander Ebonlocke know immediately that the handwriting matched, <name>!  Her suspicions were correct!", objectives = "Report the news to Commander Ebonlocke.Let Commander Ebonlocke know immediately that the handwriting matched, <name>!  Her suspicions were correct!", completion = "I knew it!  Fine work, <name>." }
WordHunterWoW_QuestEN[98] = { title = "The Legend of Stalvan", description = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, <class>, and execute Stalvan, once and for all.\n\nWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.", objectives = "Kill Stalvan Mistmantle and show Madame Eva his family ring.", progress = "Yes, <name>?", completion = "I know, <name>: Stalvan is dead.  I sensed a wave of hope ripple through the tainted forest.  Once and for all, Duskwood is free from his blood thirst.  My joy is hampered by thoughts of those who fell prey to the horrible beast.  Nonetheless, you are a brave and cunning <class>." }
WordHunterWoW_QuestEN[99] = { title = "Arugal's Folly", description = "As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy.\n\nMy knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen.\n\nI need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, <name>.", objectives = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.", progress = "Have you secured the Pyrewood Shackles yet, <name>?", completion = "Your persistence is commendable.  With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone.  Cheers to you, <name>." }
WordHunterWoW_QuestEN[100] = { title = "Call of Water", description = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.", objectives = "Speak to the Minor Manifestation of Water at North Tide's Run in Silverpine Forest.Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed." }
WordHunterWoW_QuestEN[101] = { title = "The Totem of Infliction", description = "As the mystical taint creeps through the forest, the need for self-protection is undeniable, <name>.  The winds whisper to me and they speak of a great danger which waits patiently for you in the near future.\n\nIf you wish to protect yourself, noble <class>, bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", objectives = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.", progress = "Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", completion = "Very wise of you, <name>.  This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond.  When you feel threatened, hold this totem and take comfort in its magical aura.  Be brave, fair <class>.  You will need all the courage you can muster for I see much bloodshed in your future." }
WordHunterWoW_QuestEN[102] = { title = "Patrolling Westfall", description = "Stormwind has abandoned us.  A foul wind of depravity rustles through the plains of Westfall.  This was my homeland and I will not turn my back on the citizens who choose to remain here.  We, the former farmers, shall make our stand.\n\nYour task, should you choose to accept, is to patrol the grasslands of Westfall.  Track down and slay the vile Gnolls that seem to be working in conjunction with the Deadmines thieves. Bring me eight Gnoll Paws and I will reward your bravery.", objectives = "Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.", progress = "Have you collected 8 paws from those treacherous Gnolls yet?", completion = "Well done, <name>.  With valiant adventurers such as yourself fighting alongside The People's Militia, Westfall just might return to the prosperous breadbasket it once was.  Please accept this in recognition of your tireless efforts." }
WordHunterWoW_QuestEN[103] = { title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me 5 flasks of oil from the Harvest Monsters.", objectives = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.", progress = "The flame will not burn for long without oil, <name>.", completion = "Praise you, brave <class>.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny." }
WordHunterWoW_QuestEN[104] = { title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", objectives = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, <name>.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics." }
WordHunterWoW_QuestEN[105] = { title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, <name>, and bring me a shard from his phylactery as proof!", objectives = "Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.", progress = "Your task has been given to you, <name>.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Horde on this day, <name>.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Horde a victory for the ages!" }
WordHunterWoW_QuestEN[106] = { title = "Young Lovers", description = "Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face!\n\nPlease, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.", objectives = "Give Maybell's Love Letter to Tommy Joe Stonefield.", progress = "You have what??  Maybell is the light of my dull life.  Hurry, let me see her letter!", completion = "Ah!  I can't stand us being apart.  I have to see her!!" }
WordHunterWoW_QuestEN[107] = { title = "Note to William", description = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.", objectives = "Take Gramma Stonefield's Note to William Pestle.", progress = "You have a note from \"Gramma\" Stonefield, eh?  I haven't seen Mildred in years!  I wonder what she has to say...", completion = "My heart goes out to those two poor souls, Maybell and Tommy Joe.  I remember being young and in love, once.\n\nThere must be something I can do to help them!  Let me think..." }
WordHunterWoW_QuestEN[109] = { title = "Report to Gryan Stoutmantle", description = "Looks to me you've seen quite a bit of combat in your time, <class>.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.", objectives = "Talk to Gryan Stoutmantle. He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.", completion = "Ah, so my friend sent you here?  How kind.  \n\nWell the Stormwind Monarchy has abandoned our cause.  Now it is up to the People's Militia to keep the land free from corruption.  If our cause interests you, I can put your combat skills to use in the name of freedom." }
WordHunterWoW_QuestEN[110] = { title = "Insect Part Analysis", description = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.", objectives = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", completion = "Yes, I have the results right here.  They are... unsettling, to say the least\n\nOur initial suspicion that the bugs are being controlled by an outside force, we believe, is correct.  If this is the case, then we are dealing with not only a very powerful unknown force, but also a malignant one.  These bugs have been changed to be pure ravagers.  I've never seen anything quite like it." }
WordHunterWoW_QuestEN[111] = { title = "Speak with Gramma", description = "Please, {name}, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.", objectives = "Speak with Gramma Stonefield.", completion = "While our families are feuding, Tommy Joe and Maybell don't have much of a future, but... maybe we can get them together for just a little while.\n\nHm, what can we do..." }
WordHunterWoW_QuestEN[112] = { title = "Collecting Kelp", description = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.", objectives = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.", progress = "Do you have that crystal kelp?  I'm sure Maybell is anxious to see her beau...", completion = "You got them.  Good show!  Now, just one moment while I concoct the potion..." }
WordHunterWoW_QuestEN[113] = { title = "Insect Part Analysis", description = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!", objectives = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", progress = "Well Junior Surveyor <name>, has ol' Pestlezugg got that report ready yet?", completion = "Thank you for delivering the report, Junior Surveyor <name>; here is your pay for your diligent service to the Gadgetzan Water Company.\n\nWhile I am usually not thrilled about handing out our valuable information carte blanche to those who would otherwise pay good coin for it, I've known Pestlezugg for a number of years now.  If he recommends letting everyone know about it, then so be it.  Give me a moment and I'll make you a copy." }
WordHunterWoW_QuestEN[114] = { title = "The Escape", description = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.", objectives = "Take the Invisibility Liquor to Maybell Maclure.", progress = "Did you deliver my letter to Tommy Joe?  What did he say??", completion = "Oh...my!  I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.\n\nThank you, <name>.  I'll drink this liquor as soon as I have the chance and sneak away to my love.\n\nAnd for you... please take this." }
WordHunterWoW_QuestEN[115] = { title = "Shadow Magic", description = "The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict.\n\nFind and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!", objectives = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.", progress = "How goes your conflict with the shadowcasters?  Did you find the midnight orbs?", completion = "Thank you, <name>.  I'll send these to be destroyed immediately." }
WordHunterWoW_QuestEN[116] = { title = "Dry Times", description = "I find myself in quite a pinch here, <name>.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", objectives = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.", progress = "I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", completion = "A job well done, <name>!  I know well the roads you had to journey to procure this fine array of liquor.  But my patrons will be happy once again! \n\nMy wife is quite a seamstress.  Please accept this cloak she made in return for your services." }
WordHunterWoW_QuestEN[117] = { title = "Thunderbrew Lager", description = "Hurry, my friend, move with haste \nIn order for our rich lager to taste \nMore like beer and less like stew, \nHops are needed to make the brew.", objectives = "Bring Grimbooze Thunderbrew 5 hops to complete his special brew.", progress = "Hurry, my friend, move with haste \nIn order for our rich lager to taste\nMore like beer and less like stew,\nHops are needed to make the brew.", completion = "Hops and Barley, yeast and malt \nThe taste-buds feel a virtual assault, \nNo need to plead, no need to beg \nFor Thunderbrew Lager comes in a keg!" }
WordHunterWoW_QuestEN[118] = { title = "The Price of Shoes", description = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.", objectives = "Take Verner's Note to Smith Argus at Goldshire in Elwynn Forest.", progress = "What's that?  Verner sent you, you say?  Well give me his note.  And SPEAK UP!", completion = "Heh, so old Verner needs some shoes, does he!?!" }
WordHunterWoW_QuestEN[119] = { title = "Return to Verner", description = "Ok, I'll give him his 50 horseshoes...\n\nHere they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!", objectives = "Return to Verner Osgood at Lakeshire in Redridge. Give him the Crate of Horseshoes.", progress = "Great, you're back!  Did you get the shoes?", completion = "Thank you, this really helps me out.\n\nBut what's this?  Argus sent a note with the crate...What??  Argus wants me to PAY him?  Bah!\n\nWell, <name>, thank you for your help." }
WordHunterWoW_QuestEN[120] = { title = "Messenger to Stormwind", description = "These are trying times, <class>.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. \n\nNow make haste!", objectives = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind. The judge wants you to return to him as soon as the delivery has been made.", progress = "What have you there?", completion = "At ease, <class>.\n\nMagistrate Solomon is a noble leader.  His words carry great weight with me.  I shall seek the counsel of the King and make the situation clear to him.  Assure the good judge that he has the Stormwind Army's support.  Reinforcements will be sent as soon as word is given from His Majesty." }
WordHunterWoW_QuestEN[121] = { title = "Messenger to Stormwind", description = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, <class>!", objectives = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", progress = "Did the General send news?  Are reinforcements on the way?", completion = "Thank you for your time, <class>.  For your service to Lakeshire and Stormwind I reward you with these coins.\n\nNow if you'll excuse me, I find this correspondence somewhat of a mystery.  Something is amiss in our Kingdom.  I fear this is the beginning of conflict, not the end." }
WordHunterWoW_QuestEN[122] = { title = "Underbelly Scales", description = "I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you.\n\nBlack dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.", objectives = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.", progress = "I know that greedy Argus will send someone to collect his scales if I don't give them to him soon.  Have you found those scales yet?", completion = "Thanks!  These will get me out of debt to Argus..." }
WordHunterWoW_QuestEN[123] = { title = "The Collector", description = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Patterson at Eastvale Logging Camp.", objectives = "Go to Marshal Patterson at the Eastvale Logging Camp in Elwynn Forest and give him The Collector's Schedule.", progress = "What?!?  We haven't had our people working the Elwynn mines for months!\n\nLet me see that note you have...", completion = "Hm... I have heard of this \"Collector\" but I don't know whom he's working for.  Thank you for the schedule.  It will help us solve this mystery." }
WordHunterWoW_QuestEN[124] = { title = "A Baying of Gnolls", description = "As if the attacking orcs weren't enough!  Now I have gnoll brutes and mystics prowling along the ridge north of my stable, taking my horses when they stray...\n\nIf you can get rid of those gnolls, my horses and I would be very grateful.", objectives = "Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.", completion = "Thank you for all your help, <name>." }
WordHunterWoW_QuestEN[125] = { title = "The Lost Tools", description = "I could really use a hand here, <name>.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, <name>, and I'll make it worth your while.", objectives = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.", progress = "Were you able to find my tools?", completion = "Excellent recovery, <name>!  I never thought I'd see these tools again." }
WordHunterWoW_QuestEN[126] = { title = "Howling in the Hills", description = "<name>, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader.\n\nKill Yowler and send his pack scattering!  Bring me his paw as proof.\n\nAnd be careful, this gnoll is their leader for a reason.  He is no Mongrel...", objectives = "Bring Yowler's Paw to Verner Osgood in Lakeshire.", progress = "Yowler is a dangerous creature, <name>.  If you're not ready for him, I understand.", completion = "Again, thank you for your help.  The Stormwind army is so busy dealing with the orcs, they don't have the troops to protect Redridge from local threats like the gnolls." }
WordHunterWoW_QuestEN[127] = { title = "Selling Fish", description = "Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low!\n\nBring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!", objectives = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.", progress = "You have some sunfish for me, eh?", completion = "Pleasure doin' business with you, matey!" }
WordHunterWoW_QuestEN[128] = { title = "Blackrock Bounty", description = "The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes.\n\nMagistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.", objectives = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.", completion = "I see you have fought valiantly against the Blackrock Clan, <class>.  Your service to our township is great indeed." }
WordHunterWoW_QuestEN[129] = { title = "A Free Lunch", description = "Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me.\n\nSo if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.", objectives = "Bring Parker's lunch to Guard Parker. He patrols the road leading to Darkshire.", progress = "Darcy sent me a lunch, did she?  Such a kind heart she has.  Well...let's have it!", completion = "Thanks, I could really use the meal.  Guarding Lakeshire from the orcs and gnolls is tough work!" }
WordHunterWoW_QuestEN[130] = { title = "Visit the Herbalist", description = "Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town.\n\nBut when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...", objectives = "Speak with the Redridge Herbalist, Martie Jainrose.", completion = "You need a bouquet of flowers?  You haven't been in town very long...have you already found for yourself a sweetheart here?\n\nI know I shouldn't pry, but it's nice to see that love is in the air... especially in dangerous times like these." }
WordHunterWoW_QuestEN[131] = { title = "Delivering Daffodils", description = "Here is your bouquet.  I chose Daffodils for you.  They're my favorite!", objectives = "Give Darcy the Daffodil Bouquet.", progress = "Hello again, <name>.  Did Parker like the lunch I sent him?", completion = "Oh, those are lovely!  I can't wait to put them in some water!\n\nBut...these are Martie's favorite flowers.  Parker didn't have you go to that jealous vixen for this bouquet, did he?  You didn't tell her who they were for, did you?  If you did, then it wouldn't surprise me if she poisoned them.\n\nOh, but it's not your fault.  Thank you, and here's your meal." }
WordHunterWoW_QuestEN[132] = { title = "The Defias Brotherhood", description = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle.  It explains as much as I know on the subject.", objectives = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", progress = "Good to see you back, <name>.  What did Wiley have to say for himself?", completion = "Bah!  I should have let that scoundrel rot when I had the chance.  But this information is crucial.  Good work." }
WordHunterWoW_QuestEN[133] = { title = "Ghoulish Effigy", description = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!\n\nI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.\n\nGet the ribs for me, and I will repay you with some coin.", objectives = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.", progress = "I think I hear a pack of Ghouls scurrying around the back of the house - I better put that effigy up quick!  Did you get those Ghoul Ribs for me?", completion = "Ah, thanks.  These will do just the trick!" }
WordHunterWoW_QuestEN[134] = { title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, <name>, retrieve this crate for me for I miss it sorely.", objectives = "Return Abercrombie's Crate to Abercrombie.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, <name>!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!" }
WordHunterWoW_QuestEN[135] = { title = "The Defias Brotherhood", description = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.", objectives = "Take Wiley's Note to Mathias Shaw in Stormwind.", progress = "What business do you have with me?  I am a very busy man. . .", completion = "This matter might be more complex than Stoutmantle realizes." }
WordHunterWoW_QuestEN[136] = { title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", objectives = "Find Captain Sanders' footlocker and search it for the next clue.If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave. So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker. It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck. There be lots of shipwrecks but only one rusty anchor on the coast. Find that anchor and you'll find me locker!  Look in there for the next clue.", completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!" }
WordHunterWoW_QuestEN[138] = { title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", objectives = "Find the old barrel near the ruined chimney and search it for your next clue.\n\nProvided item:", completion = "Good work, treasure hunter!" }
WordHunterWoW_QuestEN[139] = { title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", objectives = "Search the empty jug next to the windmill for the next clue.\n\nProvided item:", completion = "You're on your way to the jackpot, treasure seeker!" }
WordHunterWoW_QuestEN[140] = { title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", objectives = "Locate Captain Sanders' chest and open it for your reward.\n\nProvided item:", completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!" }
WordHunterWoW_QuestEN[141] = { title = "The Defias Brotherhood", description = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!", objectives = "Take Shaw's report to Gryan Stoutmantle in Westfall.", progress = "Did Master Shaw shed any light on things?", completion = "Edwin VanCleef. . .I know the name well.  To think that a man so industrious and talented could turn into such a scoundrel unnerves me.  I'll need further proof before I believe this." }
WordHunterWoW_QuestEN[142] = { title = "The Defias Brotherhood", description = "We need to discover the location of the Defias hideout.  <name>, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.", objectives = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", progress = "<name>, were you able to gather any information?  Did you locate the messenger?", completion = "This is indeed firm proof that VanCleef is in charge.  Now all we need to know is where the Defias gang is hiding out.\n\nWe've had a stroke of luck while you were gone.  We captured a thief trying to steal Saldean's wagon.  He has promised to lead us to the hideout in exchange for his life.  I want you to defend the traitor so he can reveal the hideout.  Return to me once you have uncovered the location." }
WordHunterWoW_QuestEN[143] = { title = "Messenger to Westfall", description = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.\n\nTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.", objectives = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.", progress = "Hail, <class>.  What business do you have with The People's Militia?", completion = "Good Messenger, you have served your master well." }
WordHunterWoW_QuestEN[144] = { title = "Messenger to Westfall", description = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.\n\nTake this response to your master in Redridge, <class>.  And let him know that my heart is heavy with the loss of good men.", objectives = "Return to Magistrate Solomon with Gryan Stoutmantle's response.", progress = "Shall we expect the People's Militia soon?  Does Lord Stoutmantle's news bode well?", completion = "I do say, this is not good at all.  I did not realize that Stoutmantle's situation was not unlike ours here in Lakeshire.  What action is so important that it calls the Stormwind Army away from its people?  Bah, I should not ponder aloud.\n\nHere, messenger.  Accept these coins in exchange for your service to the Township.  I might call upon you again." }
WordHunterWoW_QuestEN[145] = { title = "Messenger to Darkshire", description = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.", objectives = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.", progress = "You appear to have traveled from afar, <class>.  What business do you have here in Darkshire?", completion = "Thank you for making the long journey here.  This is indeed important information." }
WordHunterWoW_QuestEN[146] = { title = "Messenger to Darkshire", description = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.\n\nTake this letter of response to your Master in Lakeshire.", objectives = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.", progress = "Ah, good to see you back, messenger.  Shall I inform the Marshal that the Night Watch is on its way from Darkshire?", completion = "By the Light!  The Stormwind Army retreated from Westfall.  And the Guard no longer protects Darkshire?  There is some treachery abound.  How could this be so? \n\nOh I forgot to reward your service, <class>.  Here are some coins.  Now excuse me.  Something is amiss in Stormwind and I must get to the bottom of it." }
WordHunterWoW_QuestEN[147] = { title = "Manhunt", description = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.", objectives = "Find and kill \"the Collector\"  then return to Marshal Patterson with The Collector's Ring.", progress = "Did you find the Collector?  Did you discover whom he's working for?", completion = "You found him?  Well done, <name>.  He won't be \"collecting\" from the Elwynn Mines again!\n\nAnd this ring you found is interesting... it's a membership ring for the old Stonemason's Guild in Stormwind. I haven't seen one of these in years, since back in the days when the Defias Brotherhood used to infest this land." }
WordHunterWoW_QuestEN[148] = { title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.", objectives = "Speak with Madame Eva.Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.", completion = "Ah, Ghost Hair Thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair." }
WordHunterWoW_QuestEN[149] = { title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", objectives = "Bring the Spectral Comb to Blind Mary.", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror..." }
WordHunterWoW_QuestEN[150] = { title = "Murloc Poachers", description = "Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake!\n\nHunt murlocs!  Bring me eight of their fins and I might have something for you...", objectives = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.", progress = "Do you have those fins?  Hurry, we need those murlocs driven from the lake!", completion = "Well done, <name>.  I hope you didn't have too much trouble with those murlocs.\n\nIt's strange seeing them so far from the sea.  I wonder if they're here because they're running from something..." }
WordHunterWoW_QuestEN[151] = { title = "Poor Old Blanchy", description = "Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.\n\nI bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.", objectives = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.", progress = "Old Blanchy is on her last leg.  Did you happen to find any oats for her?", completion = "Thank you so much, <name>!  Poor Old Blanchy will be so happy!" }
WordHunterWoW_QuestEN[152] = { title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", objectives = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.", completion = "Well done, <name>.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place." }
WordHunterWoW_QuestEN[153] = { title = "Red Leather Bandanas", description = "The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear.\n\nBring me 15 of these Bandanas and I'll see to it you are rewarded.", objectives = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.", progress = "Bring me 15 red leather bandanas and I'll pay you well.", completion = "Nice work, <race>.  Please accept one of these items as payment for all your hard work." }
WordHunterWoW_QuestEN[154] = { title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", objectives = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", progress = "I sense that you have seen Blind Mary.  You have my Comb...?", completion = "I can make a spool of Ghost Hair Thread with this, and have a few strands to spare.  Here are some coins for those extra strands." }
WordHunterWoW_QuestEN[155] = { title = "The Defias Brotherhood", description = "So Stoutmantle sends a scrawny <race> like you to protect me?  Guess you'll have to do.  Better bring some friends too. \n\nYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.", objectives = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", completion = "Most excellent, <name>!  VanCleef is as good as ours now that we know where he is hiding." }
WordHunterWoW_QuestEN[156] = { title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nrot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!\n\nThe Raven Hill Cemetery is lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.", objectives = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.", progress = "Hi, <name>.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.  And I'll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.\n\nKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed." }
WordHunterWoW_QuestEN[157] = { title = "Deliver the Thread", description = "Here is your thread, <name>.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", objectives = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.", progress = "I need to string the Ghost Hair Thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good <name>, take this as payment for your honorable deed." }
WordHunterWoW_QuestEN[158] = { title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, <name>.  These nights get cold, and I need that drink to put fire in my veins again!", objectives = "Speak with Tavernkeep Smitts.I need a bottle of a certain liquor - Zombie Juice. Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, <name>. These nights get cold, and I need that drink to put fire in my veins again!", completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it." }
WordHunterWoW_QuestEN[159] = { title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", objectives = "Bring the Zombie Juice to Abercrombie at his shack.", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, <name>.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude." }
WordHunterWoW_QuestEN[160] = { title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", objectives = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", progress = "Abercrombie...?  I don't know a person of that name.  You say you have a letter for me from this Abercrombie fellow?\n\nWell let's have it then...", completion = "<Ello looks at the letter...>\n\nWhat language is this?  It looks ancient...I can't read it." }
WordHunterWoW_QuestEN[161] = { title = "A Dark Threat Looms", description = "If my suspicions are correct, this is some type of explosive powder. This must be analyzed by an explosives expert so we know just what we're dealing with here.\n\nThere's only one man for the job. Ashlan Stonesmirk was assigned to monitoring the ogres at the Mo'grosh Stronghold to the east. Head that direction and locate him so that he can shed some light on what this substance is.", objectives = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert at the Mo'grosh Camp.", progress = "You say somethin', sonny?  Can't hear a bloody thing besides the ringin' in me ears.  Say, what's that you got there?", completion = "Ah, well Ol' Hinderweir is wise to be worried." }
WordHunterWoW_QuestEN[162] = { title = "Rise of the Silithid", description = "I urge you to take this report to someone who has working knowledge in this kind of thing.\n\nI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.\n\nLast I heard, she was residing in the Temple of the Moon, located in Darnassus.", objectives = "Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.", progress = "Peace and tranquility be upon you, stranger.  Why have you sought me out this day?", completion = "This report... we night elves know of the terror mentioned here.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, <name>: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before." }
WordHunterWoW_QuestEN[163] = { title = "Raven Hill", description = "Something's amiss at Raven Hill, <name>. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows.\n\nIf, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.", objectives = "Find out what is haunting Raven Hill.", completion = "No! Please don't kill me! It's just me... Jitters!! They're everywhere... I can't escape them! Monsters in Raven Hill? N-n-n-o... couldn't be. Only harmless Jitters." }
WordHunterWoW_QuestEN[164] = { title = "Deliveries to Sven", description = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.\n\nUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?", objectives = "Deliver the supplies to Sven.", progress = "You look a sturdy type, <class>. Have you come to join our fight?", completion = "These supplies will be most useful. The aid of the Carevin family is always appreciated. Here is a little something for your trouble." }
WordHunterWoW_QuestEN[165] = { title = "The Hermit", description = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.", objectives = "Check on the old man in the shack near Raven Hill cemetery.", completion = "Elaine Carevin? Hehe, oh yes... of course, the Carevins.\n\nNo, nothing's wrong but it is hard for me to go into town now. The roads are dangerous and I'm not getting any younger. Maybe you can do an old man some favors?" }
WordHunterWoW_QuestEN[166] = { title = "The Defias Brotherhood", description = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.", objectives = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", progress = "How goes the hunt for Edwin VanCleef?", completion = "<name>, your bravery is remarkable.  The People's Militia thanks you for your service to the people of Westfall.  With VanCleef dead, this marks the beginning of the end for the Defias Brotherhood.  Hopefully some day soon peace will once again grace the plains of this fair land.\n\nI salute you, Sir!" }
WordHunterWoW_QuestEN[167] = { title = "Oh Brother. . .", description = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.", objectives = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.", progress = "Did you find any sign of my brother?  Is there any hope after all this time?", completion = "My suspicions were correct.  My poor brother.... Well, thank you for bringing some conclusion to this mystery, even if the conclusion was grim." }
WordHunterWoW_QuestEN[168] = { title = "Collecting Memories", description = "Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.", objectives = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.", progress = "Were you able to retrieve any of my old co-worker's Miners' Union Cards?", completion = "Thank you for collecting these, <name>.  Your efforts will help bring peace to the dead in the wake of this tragedy.  I will see to it that the families are notified." }
WordHunterWoW_QuestEN[169] = { title = "Wanted: Gath'Ilzogg", description = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.", objectives = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", progress = "What do you have there, <race>?", completion = "Fantastic work, <name>!  Gath'Ilzogg led those brutes into battle, killing many innocent humans.  Vindication is ours.  This is the first step in reclaiming the keep for the kingdom of Stormwind!" }
WordHunterWoW_QuestEN[170] = { title = "A New Threat", description = "I hope you're here to lend us a hand, <class>. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, <lad/lass>, and we need strong arms to help drive the troggs back.", objectives = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.", completion = "If the problems we've had here are indicative of what is happening elsewhere in our lands, by Magni's beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose." }
WordHunterWoW_QuestEN[171] = { title = "A Warden of the Alliance", description = "You have been so very kind to me, {name}.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.\n\nI wish all the orphans were lucky enough to get to do the stuff we did. Do you think we could find Craggle Wobbletop again and get a foam sword rack from him? I think he's still pushing that cart in the Canals outside the Trade District. That way, everyone else at the orphanage could do something fun too!\n\nAfter that, it'll be time for me to go home.", objectives = "Purchase a Foam Sword Rack from Craggle Wobbletop and then return your ward to the Stormwind orphanage by speaking to Orphan Matron Nightingale in the Cathedral District.", progress = "It is a pleasure to see you again, <name>.  Have you attended to the duties you've volunteered for during Children's Week?", completion = "What's this? A gift for all the orphans!\n\nMay the heavens bless you, <name>.  You've done more for Randis than most would ever think of doing for him.  Thank you - you're a shining star in the skies of the Alliance.\n\nRandis had so much fun with you, <name>.  He wanted to give you one of his favorite pets to remember him by." }
WordHunterWoW_QuestEN[172] = { title = "Children's Week", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means {name} - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", objectives = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item:", completion = "Zug zug!  My name is Grunth, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  My matron says that they died with honor in battle.  I'm happy to meet you.\n\nI hope we'll do plenty of things together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch." }
WordHunterWoW_QuestEN[173] = { title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.", objectives = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.", completion = "Impressive, <name>. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.\n\nIt is curious though... The worgen seemed to just appear out of thin air. But then, with all the other strange creatures that have moved across our borders, I suppose it's only one of many concerns." }
WordHunterWoW_QuestEN[174] = { title = "ook To The Stars", description = "My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest.\n\nBring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.", objectives = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.", progress = "Have you found a skilled engineer to create a bronze tube yet?", completion = "This is perfect, <name>.  The first step is complete!" }
WordHunterWoW_QuestEN[175] = { title = "ook To The Stars", description = "According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", objectives = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", completion = "Why yes, I used to own a looking glass." }
WordHunterWoW_QuestEN[176] = { title = "WANTED:  \"Hogger\"", description = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should venture into the woods and deal with the beast.", objectives = "Deal with \"The Hogger Situation\" and return to Marshal Dughan.", completion = "He did WHAT?\n\n Great, now we have a bloodthirsty beast right beneath the streets of Stormwind, with a whole army of gnolls at his command.  Definitely an improvement, I feel safer already. \n\n Here's your reward, <name>.  But promise me you'll check in with the Stockades guards in Stormwind at some point, just to ensure that things are going smoothly." }
WordHunterWoW_QuestEN[177] = { title = "ook To The Stars", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", objectives = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!" }
WordHunterWoW_QuestEN[178] = { title = "Theocritus' Retrieval", description = "<You hear a disembodied voice...>\n\nDo not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth.\n\nThrough months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success.\n\nBring me this pendant and I will reward you for the service.", objectives = "Bring the Faded Shadowhide Pendant to Theocritus the Mage at the Tower of Azora in Elwynn Forest.", progress = "I spoke to you through a pendant, you say?  Hmm...give it to me, so that I might study it.", completion = "You have my gratitude, <name>.  I sent that message to the Shadowhide Pendants weeks ago and had believed it a failure.  But it seems the spell did reach at least some pendants, after a significant delay.\n\nIn time I hope to learn how to send an attack through the pendants, to immobilize any Shadowhide Gnolls who wear them.\n\nBut before that is possible, I'm afraid that much more research is required." }
WordHunterWoW_QuestEN[179] = { title = "Dwarven Outfitters", description = "What do we have here? You look as though you might need something to keep your hands warm, hm?\n\nI'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however.\n\nI need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?", objectives = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.", progress = "Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?", completion = "Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, <name>, I wouldn't forget my part of the bargain. Here, one of these should fit you." }
WordHunterWoW_QuestEN[180] = { title = "Wanted: Lieutenant Fangore", description = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.", objectives = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", progress = "What news do you bring before the Court?", completion = "So the evil Lieutenant Fangore is dead?  Good riddance to that foul creature.  You are very brave, <class>.  The Township of Lakeshire thanks you for your aid." }
WordHunterWoW_QuestEN[181] = { title = "ook To The Stars", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", objectives = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, <name>.  Now I can continue my research. . ." }
WordHunterWoW_QuestEN[182] = { title = "The Troll Menace", description = "The trolls're acting up.  More than usual, I'd say.  We've seen them put together war parties before, but this time it's... different.\n\nWhat matters most, however, is the continued protection of Anvilmar.  I've no intention to let these trolls flank Anvilmar while its attention is turned towards troggs.  Go thin their ranks a bit.  They need to know that we're still not without defenses.", objectives = "Kill 10 Frostmane Troll Whelps.", completion = "Hopefully that did the trick.  Anvilmar will be safe from trolls for the time being.  Now, to find out what it is that has the trolls so agitated." }
WordHunterWoW_QuestEN[183] = { title = "The Boar Hunter", description = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.", objectives = "Talin Keeneye would like you to kill 12 Small Crag Boars.", completion = "Excellent! I can go back to my... leisurely... hunting now. Thank you, <name>." }
WordHunterWoW_QuestEN[184] = { title = "Furlbrow's Deed", description = "This is an old deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...", objectives = "Bring Furlbrow's Deed to the Jansen Stead in Westfall.", progress = "We don't need any civilian vigilante types getting involved, kid. Leave this one to the professionals.", completion = "This is useless. Look at the date on this letter. The Furlbrows have been squatting on the Jansen Stead for five years.\n\nThey never could quite get their wagon... fixed." }
WordHunterWoW_QuestEN[185] = { title = "Tiger Hunting", description = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.  Start your hunt near our camp, to the south.", objectives = "Hunt 10 Young Stranglethorn Tigers.", completion = "You have finished with the young tigers... but the thrill of the hunt still holds you captive." }
WordHunterWoW_QuestEN[186] = { title = "Tiger Stalking", description = "Young tigers are one thing.  Fully-grown cats are another.  Hunting the grown Stranglethorn tigers will prove an even greater challenge.\n\nThe adult cats normally spend their days south of Kurzen's Compound, east of the river.", objectives = "Hunt 10 Stranglethorn Tigers.", completion = "Tiger blood coats your hands, your weapons, and your <class> garb.  Yet still you crave more." }
WordHunterWoW_QuestEN[187] = { title = "Tiger Prowess", description = "Elder Stranglethorn tigers are the strongest of the bunch.  More than one {race} {class} has seen his own demise at the tip of those razor-sharp teeth and heavy claws.\n\nAjeck will be thrilled to know that you have bested them.  The largest pack of these elders can be found to the south, near the Sundering, on the border of the Cape of Stranglethorn.", objectives = "Hunt 5 Elder Stranglethorn Tigers.", completion = "You have defeated the strongest tigers in Stranglethorn.  You have become a great tiger hunter, and have every right to stop your hunt right here and now.\n\nSomething tells you, however, that a stronger cat still waits for you within that jungle..." }
WordHunterWoW_QuestEN[188] = { title = "Tiger Mastery", description = "Legends speak of an elusive tigress... a feline so powerful that she dwarfs even the elder males.  The hunters at Nesingwary's Expedition have hunted for her without success.  Many of them have fallen prey to her raking claws, their bodies now decaying at the foot of her hill, north of Grom'gol.\n\nThey call the beast Sin'Dall.\n\nYou resolve to do what no {race} has done before: hunt, kill, and claim the paw of Sin'Dall.", objectives = "Hunt Sin'Dall and return with her paw.", progress = "How goes the hunt?", completion = "Most impressive, I do say!  I send you out to defeat the kittens, and you return with a paw the size of a gnome!  You are a true Master Tiger Hunter, <name>!" }
WordHunterWoW_QuestEN[189] = { title = "Bloodscalp Ears", description = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... <name>, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.", objectives = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.", progress = "You've had success I hope? All over the place, those trolls. Filthy devils.\n\nOh yes, that reminds me! Be sure to tell your friends, yes? We could use much assistance!", completion = "Oh excellent, excellent. That'll help a little, for the present...\n\n<He trails off, grumbling about profit margins and costs...>\n\nWhat? You're still here? Reward? Oh, right... of course, here, take this... it should be more than enough." }
WordHunterWoW_QuestEN[190] = { title = "Panther Hunting", description = "If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter.  You should start out easy: just focus on the young panthers for now.  As you improve and gain experience as a hunter, you will undoubtedly find increasingly dangerous quarry.\n\nStart by heading east.  Return to me when you are a master panther hunter.", objectives = "Hunt 10 Young Panthers.", completion = "You feel more experienced already.  Perhaps it's time to move on to bigger prey." }
WordHunterWoW_QuestEN[191] = { title = "Panther Stalking", description = "The youngest panthers fell easily before you.  Panthers that have come of age will naturally be stronger, and quicker, and more difficult to defeat.\n\nLarger panther tracks lead to the west.", objectives = "Hunt 10 Panthers.", completion = "You take a moment to silently congratulate yourself on your panther hunting so far." }
WordHunterWoW_QuestEN[192] = { title = "Panther Prowess", description = "Now the hard part.  As panthers grow older, they become more wily, blending in with their environment and becoming difficult to spot.  These cunning panthers are known by the name \"shadowmaw\", for their tendency to suddenly appear out of the darkness... with a waiting mouth full of teeth.\n\nIf you want to prove yourself as a true panther hunter, shadowmaws are the only way to do so.  They prowl to the southeast, across the river.", objectives = "Hunt 5 Shadowmaw Panthers.", completion = "The shadowmaw panthers proved no match for your skills as a hunter.  Only one task remains." }
WordHunterWoW_QuestEN[193] = { title = "Panther Mastery", description = "You've almost proven yourself to be a master hunter of panthers.  Yet there is one panther which has eluded your grasp.\n\nSongs are sung about a mighty panther by the name of Bhag'thera.  You will see if you can use your skills to kill the great beast.\n\nBringing the Fang of Bhag'thera to Erlgadin should be proof enough that you are a master panther hunter.", objectives = "Obtain the Fang of Bhag'thera.", progress = "You're still alive!  Excellent!  How fares the hunt?", completion = "So the great Bhag'thera is dead!  Cheers to you, <name>.  You are a mighty <class> indeed!" }
WordHunterWoW_QuestEN[194] = { title = "Raptor Hunting", description = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill ten Stranglethorn raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.\n\nOkay, go west.", objectives = "Hunt 10 Stranglethorn Raptors.", completion = "Stranglethorn raptors were not a problem for a wily <class> like you." }
WordHunterWoW_QuestEN[195] = { title = "Raptor Stalking", description = "It is time to step up the challenge.  Venturing into the jungle and bagging 10 lashtail raptors should be sufficient.  They will certainly be stronger than the raptors you have already disposed of.\n\nThe lashtail raptors mainly stay southeast of here, near the Kal'ai Ruins.", objectives = "Hunt 10 Lashtail Raptors.", completion = "Hemet Nesingwary Jr. doubted you, but his doubts were unfounded.  You are absolutely destroying these raptors." }
WordHunterWoW_QuestEN[196] = { title = "Raptor Prowess", description = "A particularly cagey brand of raptor, known by locals as the \"Jungle Stalker\", prowls the forests to the south, across the river.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.\n\nKilling these Jungle Stalkers will undoubtedly make for a good tale around the fire.", objectives = "Hunt 10 Jungle Stalkers.", completion = "You are no longer just a raptor hunter.  You are an honest-to-goodness raptor SLAYER.\n\nThough one fabled raptor still eludes you..." }
WordHunterWoW_QuestEN[197] = { title = "Raptor Mastery", description = "Before returning to Nesingwary's Expedition, you will have to complete the impossible: hunt the raptor that no other hunter has been able to capture.  That beast goes by the name of Tethis, and he's been known to terrorize the southeastern corner of Northern Stranglethorn.\n\nBringing Tethis' talon back to that dwarf hunter should be proof that you are no ordinary {race}.", objectives = "Hunt Tethis.", progress = "Ah, so you're hunting Tethis?  Tracked her all the way back to camp, did you?", completion = "Master <name>, the raptor slayer!\n\nHas a nice ring to it, eh?" }
WordHunterWoW_QuestEN[198] = { title = "Supplies to Private Thorsen", description = "Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution.", objectives = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.", progress = "Yes? What do you want? Oh, supplies from the goblins. Strange seeing a <race> delivering them, usually they send their own. No matter... you didn't touch them did you? Good good... we wouldn't want anything to happen to our mines, oh no.", completion = "These land mines will help us defend ourselves from that animal Kurzen and his men. Thank you for bringing them. If you need further work, I can probably find something for you to do. And you won't have to deal with those goblins, hm?" }
WordHunterWoW_QuestEN[199] = { title = "A Dark Threat Looms", description = "You take a sample of the strange smelling powder.", objectives = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.", progress = "Did you happen to discover any clues, <name>?", completion = "This is an alarming discovery, to say the least!" }
WordHunterWoW_QuestEN[200] = { title = "Bookie Herod", description = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there.", objectives = "Find Bookie Herod's Records.", completion = "These are Bookie Herod's notes and records.\n\nAmong them are: a list of supplies within the camp, material requests from Colonel Kurzen, and various letters and correspondences." }
WordHunterWoW_QuestEN[201] = { title = "Investigate the Camp", description = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti.  Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary Jr. was one of the hunters there.  He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, <name>, see what they're about?", objectives = "Find the hunters' camp and report its location to Krazek in Booty Bay.", completion = "Hmmm, so my information was correct, as usual.  Interesting.  Well, I don't suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products.  Hmmm..." }
WordHunterWoW_QuestEN[202] = { title = "Colonel Kurzen", description = "You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, <name>.  My hope, and the fate of my men, go with you.", objectives = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.", progress = "Dare I hope that Kurzen and his defenders are dead, <name>?", completion = "I dared not believe the reports, but you bring us proof that...Kurzen and his leaders are defeated.  You have saved us!\n\nThese jungles are filled with menaces of all types, but none had the cruel intellect of Kurzen.  We may all breathe easier now that he is gone." }
WordHunterWoW_QuestEN[203] = { title = "The Second Rebellion", description = "We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.", objectives = "Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.", completion = "Well done.  The loss of those Jungle Fighters will relieve some of the pressure on our camp.\n\nBut now that you've had a taste of the forces we're up against, do you still want to throw your lot in with us??" }
WordHunterWoW_QuestEN[204] = { title = "Bad Medicine", description = "To have a chance against Kurzen, we need his healing support neutralized.  He has gathered a large number of medicine men who heal his forces with jungle remedies and poison our fighters with venom fern extracts.\n\nWe need those remedies and extracts for our own.  Search the Kurzen Compound - his medicine men and jungle fighters will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.", objectives = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.", progress = "I'm waiting on those remedies and that extract, <name>.", completion = "Well done, <name>.  These remedies will keep more of us alive and in fighting shape.  And the extracts will help us create our own remedies." }
WordHunterWoW_QuestEN[205] = { title = "Troll Witchery", description = "While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.", objectives = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.", progress = "Do you have those fetishes, <name>?  They might hold the secret to Kurzen's degradation...I must know!", completion = "Thank you.  I will study these fetishes and see if they hold the secret of Kurzen's fall into evil." }
WordHunterWoW_QuestEN[206] = { title = "Mai'Zoth", description = "Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.", objectives = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.", progress = "I give you my blessing.  Mai'Zoth's strength is matched only by his evil.", completion = "Aha!  You've done it!  You are a great force for good, <name>, and may your strength never fade!\n\nI will study this Mind's Eye and determine if it may be used for good.  If not...then it must be destroyed." }
WordHunterWoW_QuestEN[207] = { title = "Kurzen's Mystery", description = "Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda.", objectives = "Find the 4 tablets and bring their legends back to Brother Nimetz.", progress = "<name>!  Do you have the troll legends?  I must know their secrets!", completion = "Thank you, <name>.  I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen." }
WordHunterWoW_QuestEN[208] = { title = "Big Game Hunter", description = "{name}, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bhag'thera, and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here... yet still, he taunts me from his roost to the south.  Kill King Bangalash and your hunting prowess is proven to be second to none.", objectives = "Hunt for the head of King Bangalash, the great white tiger.", progress = "I see you're back, old bloke.  King Bangalash has caused me to come crawling back to camp many times.  Hang in there.", completion = "Bloody well done!  Right-o!  Congratulations, <name>, for succeeding where others have failed.\n\nI am honored to count you as a comrade of our great hunting party here.  No one will ever doubt your expertise in hunting and tracking!\n\nCheers to you, I say!  Cheers!" }
WordHunterWoW_QuestEN[209] = { title = "Skullsplitter Tusks", description = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!", objectives = "Acquire 18 Skullsplitter Tusks and return them to Kebok.", progress = "Tough buggers, aren't they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?", completion = "Ah, good work, good work! Ugh, though you could have done a better job cleaning off the-- Well, no matter, no matter! My thanks to you, <name>, our operation will no doubt see increased output and productivity thanks to your help! Good good, now, onto other matters..." }
WordHunterWoW_QuestEN[210] = { title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.", objectives = "Bring Krazek's Crock Pot to Krazek the goblin.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price..." }
WordHunterWoW_QuestEN[211] = { title = "Alas, Andorhal", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, <name>, and bring me a shard from his phylactery as proof!", objectives = "Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", progress = "Your task has been given to you, <name>.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Alliance on this day, <name>.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Alliance a victory for the ages!" }
WordHunterWoW_QuestEN[212] = { title = "A Meal Served Cold", description = "One of my most famous dishes is Chilled Basilisk in Lime Vinaigrette.  But the problem is... the meat is impossible to keep fresh, and I must serve the dish tonight for a noble's birthday!\n\nSo if you can bring me a Chilled Basilisk Haunch from a freshly-killed Cold Eye Basilisk, quickly, then I will owe you a king's feast!\n\nCold Eye Basilisks are known to roam along the beach dunes of northwestern Stranglethorn, so you have much traveling to do.  And be swift!", objectives = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.", progress = "<name>!  Do you have that haunch?  I must begin preparing it soon, or the banquet will be ruined!", completion = "Ah, this will do nicely!  Many, many thanks!\n\nNow if you'll excuse me, I must get the haunch chopped, marinated and garnished for the banquet." }
WordHunterWoW_QuestEN[213] = { title = "Hostile Takeover", description = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.", objectives = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.", progress = "I need those stones, <name>. By whatever means necessary! Just do it, don't give me the details!\n\nIt's about results, <name>, nothing more, nothing less.", completion = "Fascinating. That the crystals have been tumbled using this process can only indicate that they are planning to use them as some sort of fuel or other catalyst. I don't know much more than that. Samples will have to be dispatched to Head Chemist Gigglefont." }
WordHunterWoW_QuestEN[214] = { title = "Red Silk Bandanas", description = "It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, <name>.", objectives = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.", progress = "Have you been reclaiming our land from the Defias gang?  If so show me 10 Red Silk Bandanas as proof.", completion = "Well done, <name>!  On behalf of The People's Militia I salute you for your efforts.  Soon we will return this land to the people with help from brave souls like you." }
WordHunterWoW_QuestEN[215] = { title = "Jungle Secrets", description = "Thank you for saving me, <name>.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.", objectives = "Speak with Lieutenant Doren at the Rebel Camp.", completion = "Yes, what Thorsen told you is true.  You must be discrete with this.  At one time, we rebels were fiercely loyal to Colonel Kurzen.  But such was Kurzen's corruption, our passion twisted into rage.   If it was made known that Private Thorsen has had recent dealings with Kurzen's men, then one night he would find himself with a slit throat.\n\nTo my knowledge, only Sergeant Yohwa, Thorsen and I were privy to Thorsen's mission.  But there must be another.  A traitor." }
WordHunterWoW_QuestEN[216] = { title = "Between a Rock and a Thistlefur", description = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our west blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n{name}, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", objectives = "Karang Amakkar at Hellscream's Watch wants you to take down any 15 Thistlefur furbolg in Thistlefur Village.", completion = "Well done <class>, well done!  I will continue to send forces to thin out the furbolg, but I can at least count on a different path that will be free of Alliance entanglements.  The Horde conquest of Ashenvale is now in full swing!\n\nYou've earned your pay this day, hero.  I salute you!" }
WordHunterWoW_QuestEN[217] = { title = "A Decisive Strike", description = "My ploy worked. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. Grawmug is heavily guarded, however. Two of his most elite guards, Gnasher and Brawler, never leave his side.\n\nIf you feel yourself worthy, <name>, I want you to lead the assassination mission on Grawmug and his two thugs inside this cave. Go! I'll free myself from these bindings and meet you shortly.", objectives = "Kill the trogg leader, Grawmug, and his two guards, Gnasher and Brawler, and then report back to Captain Rugelfuss in Thelsamar.", completion = "Most excellent, <name>!  You have brought hope to Loch Modan.  With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land." }
WordHunterWoW_QuestEN[218] = { title = "Ice and Fire", description = "Soren did well to send you out on recon.  That's some good information you have right there.\n\nTrouble is, this just adds more work for us to do.  The trolls, confused as they are right now, still would like to kick the dwarves right out of Coldridge.  And I'm certainly not going to let some fiery demon turn our snowy valley into a mountain lake.\n\nThe troll leader, his servants, and the fire creature should all be in the cave to the southeast.  Take 'em all out.", objectives = "Kill Grik'nir the Cold, 6 Frostmane Blades, 3 Frostmane Novices, and the Wayward Fire Elemental.", progress = "<name>! Any luck?", completion = "I'm glad you've returned safely, <name>.  While it may not look like it now, you've proven to be a tremendous asset in the protection of Anvilmar.\n\nHere, take this as a symbol of my gratitude." }
WordHunterWoW_QuestEN[219] = { title = "Missing In Action", description = "At last, friends of the Alliance!\n\nHelp... please... \n\nThe last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly.\n\nI'll need help getting back to town... please... you're my last hope...", objectives = "Protect Corporal Keeshan on the journey back to Redridge.", completion = "You have served the Kingdom well, <class>.  Thank you for assisting Corporal Keeshan with his escape from those dreaded Blackrock Orcs.  You shall be rewarded for your brave acts this day." }
WordHunterWoW_QuestEN[220] = { title = "Call of Water", description = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.\n\nGo now and find her. We shall meet again some day.You will receive:", objectives = "Bring the Vial of Purest Water to Islen Waterseer at the Tidus Stair in the Barrens." }
WordHunterWoW_QuestEN[221] = { title = "Worgen in the Woods", description = "You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.\n\nOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.\n\nBe on your guard.", objectives = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.", completion = "You performed well against the Dark Runners, <name>. But it seems as though their numbers are inexhaustible. Every time we make progress, more spring up to refill their ranks.\n\nWhat is the evil power that draws them here? Why have they come to disturb our unhappy realm...\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem." }
WordHunterWoW_QuestEN[222] = { title = "Worgen in the Woods", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", objectives = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.", completion = "<name>, to be honest with you, I did not believe that you would get this far, but you are clearly a <class> to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation." }
WordHunterWoW_QuestEN[223] = { title = "Worgen in the Woods", description = "Here you go, <name>. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", objectives = "Bring Calor's note to Jonathan Carevin.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, <name>, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, <name>, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light." }
WordHunterWoW_QuestEN[224] = { title = "In Defense of the King's Lands", description = "We need to protect the Loch, <name>! With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front. Troggs are tunneling up from every crevice! The Trogg infestation poses the largest threat to Ironforge.\n\nWe need you, brave adventurer, to venture forth and lay waste to the Trogg threat. Slay 6 Stonesplinter Troggs and 6 Stonesplinter Scouts and report back. You will find most of the vermin through the passes into the mountains to the south.", objectives = "Mountaineer Cobbleflint at Thelsamar wants you to kill 6 Stonesplinter Troggs and 6 Stonesplinter Scouts.", completion = "Well done, <name>!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well.\n\nIf you fancy yourself well-suited for this kind of adventuring, I suggest you speak with Mountaineer Gravelgaw.  The Captain has him assigned to a rough patrol that I am sure he can use some help with.  Check with Gravelgaw just inside the tower." }
WordHunterWoW_QuestEN[225] = { title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", objectives = "Speak with Sirra Von'Indi in Darkshire.", completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections..." }
WordHunterWoW_QuestEN[226] = { title = "Wolves at Our Heels", description = "Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work!\n\nBut if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.", objectives = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.", completion = "Oh good.  You thinned out that pack quite a bit, and without those wolves nipping out our heels, we can bind our minds to dealing with Morbent Fel.\n\nHere, take some of these Flash Bundles.  They make them in town, and a lot have been donated to Sven to help with his cause." }
WordHunterWoW_QuestEN[227] = { title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", objectives = "Speak with Commander Althea Ebonlocke in Darkshire.", completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A wandering undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n<She sizes you up.>\n\nYou seem to be capable enough, maybe you could lay him to rest." }
WordHunterWoW_QuestEN[228] = { title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", objectives = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", progress = "I don't blame you if you're having trouble with him, <name>. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, <name>! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however..." }
WordHunterWoW_QuestEN[229] = { title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", objectives = "Speak with Watcher Sarah Ladimore in Darkshire.I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", completion = "Yes? My father...\n\n<Her eyes become downcast.>\n\nI wish... there was something I could have done for him... If only I had talked to him before he..." }
WordHunterWoW_QuestEN[230] = { title = "Sven's Camp", description = "Digging through the mound, you find a small, dirt-stained book.\n\nThe book has no title, but...it has information Sven would like to know.", objectives = "Bring the Book from Sven's Farm to Sven.", progress = "You found what??  Please, let me see it...", completion = "<Sven reads the book's pages, then slams it shut.>\n\nThat shadowy figure I saw was a witness to my family's death!  There are questions I'd like to ask that man...if only I knew who he was!" }
WordHunterWoW_QuestEN[231] = { title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, <name>.", objectives = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", progress = "Leave me be...", completion = "<A ghostly voice sounds on the wind...>\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n<name>. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love..." }
WordHunterWoW_QuestEN[232] = { title = "Errand for Apothecary Zinge", description = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.\n\nApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.", objectives = "Take the purchase order to Alessandro Luca in the Undercity.", progress = "Yes, and what may I assist you with?  Are you here on business for the Royal Apothecary Society, or have you arrived here merely to brighten my day?", completion = "Ah, Zinge needs a kit, does she?  It saddens me that Zinge does not choose to grace myself with her sweet presence.\n\nVery well, let me procure a kit for you." }
WordHunterWoW_QuestEN[233] = { title = "Coldridge Valley Mail Delivery", description = "Hm, I don't suppose you'd be willing to do a favor for me, <lad/lass>? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?", objectives = "Deliver the stack of letters to Talin Keeneye in Coldridge Valley.", progress = "Yes? Do you have something for me?", completion = "Thank you, I've been waiting for these letters for quite some time...\n\nUnfortunately, these letters aren't all for me. This one is addressed to Grelin Whitebeard. He's not too far away if you'd like to deliver it to him." }
WordHunterWoW_QuestEN[234] = { title = "Coldridge Valley Mail Delivery", description = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.", objectives = "Deliver the letter to Grelin Whitebeard in Coldridge Valley.", progress = "Is there something I can help you with?", completion = "Ahh, excellent. It's been a while since I received word from Ironforge." }
WordHunterWoW_QuestEN[235] = { title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", completion = "Welcome to the new frontier, <name>. Ashenvale is a land of opportunity, one where a young <class> like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know." }
WordHunterWoW_QuestEN[236] = { title = "Fueling the Demolishers", description = "{name}! About time you showed up. While the battle may be over, we still need to prepare for the next battle. Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We can't let them have the advantage in the next battle.", objectives = "Siege Master Stouthandle at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", completion = "Excellent! This will help fuel the flames of war for days to come." }
WordHunterWoW_QuestEN[237] = { title = "In Defense of the King's Lands", description = "Mountaineer Cobbleflint had nothing but good things to say about you, <race>.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front.\n\nSet forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.", objectives = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.", completion = "You accomplished your mission well, <race>.  The King himself would be proud.\n\nThe reinforcements promised to us never showed, however.  Apparently the Alliance front is a sea of crimson from the blood of our fallen brethren.  The news of the losses leaves a bitter taste in one's mouth.  But we must not let their deaths go for naught.  We must rally in these grim times and bring glory back to the Alliance.\n\nSpeak with Mountaineer Wallbang for reassignment.  You're needed now more than ever." }
WordHunterWoW_QuestEN[238] = { title = "Errand for Apothecary Zinge", description = "The kit is ready, <name>.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.\n\nWell, don't just stand there.  Such is the life of a simple courier, yes?", objectives = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.", progress = "Yes, I think Luca is as disturbing as you do.  It matters not - hand me the field sampling kit.  I will need to make some adjustments to it in order to survey for the proper base materials.\n\nYou have the kit, don't you?", completion = "Good - it pleases me to be working with someone who takes pride in not wasting my time.\n\nAfter I make some adjustments to this kit, you'll be ready to head out into the field.  You'll be using it to collect some vital data to the task at hand.\n\nIt will take just a moment for me to finish the modifications.  While you are waiting, you should probably start thinking about what you'd like to bring to the desert with you.\n\nYes, I said the desert." }
WordHunterWoW_QuestEN[239] = { title = "Westbrook Garrison Needs Help!", description = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.", objectives = "Go to the Westbrook Garrison and speak with Deputy Rainer.", completion = "Marshall Dughan sent you, eh?  Well you're not from the army, but if Dughan sent you then that's good enough for me!\n\nOur situation is, to say the least, a stressed one.  I hope you can give us a hand." }
WordHunterWoW_QuestEN[240] = { title = "Return to Jitters", description = "And here we are - \"Crab\" Cakes ala Grual!", objectives = "Return to Jitters with the Dusky Crab Cakes.", progress = "<name>, you're here!  Do you have my food?!?", completion = "Aha!  Thank you, <name>.  Those really hit the spot!\n\nAnd here, please let me pay you for these!" }
WordHunterWoW_QuestEN[243] = { title = "Into the Field", description = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.\n\nIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.\n\nReturn to me only when you are successful.", objectives = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.\n\nProvided item:", completion = "Ah, our model 4711-FTZ power sources!  We normally use them to power the water wells, but THANKS TO THE VILE NOMADS, we have an over abundance of power sources right now.\n\nSure, I can get you a power source for whatever nefarious science experiment you think you're trying to hide from me.  It ain't gonna be free though, <race>.  Nothing's free in Gadgetzan." }
WordHunterWoW_QuestEN[244] = { title = "Encroaching Gnolls", description = "Hail, <class>.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here.\n\nLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage.\n\nFeldon's usually inspecting the area south of the bridge to Lakeshire.", objectives = "Report to Deputy Feldon at the bridge south of Lakeshire in Redridge Mountains.", completion = "There are Redridge gnolls that close to Elwynn??  They may be poised to advance into our homeland.  Soon the people of Lakeshire may not be the only humans under siege!\n\nHere is your pay, though you bring us dire news.  And it comes at a bad time, for we are ill equipped to deal with it." }
WordHunterWoW_QuestEN[245] = { title = "ight-Legged Menaces", description = "Hail, <class>. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire.\n\nI hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs.\n\nOh, and a word of advice, you'll want to avoid their venom if you can.", objectives = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.", completion = "Ah! You're back. And not too much worse for wear, it'd seem. Of course, <name>, the Night Watch is grateful for your work, and I did promise you a reward, so here." }
WordHunterWoW_QuestEN[246] = { title = "Assessing the Threat", description = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, <name>, and you will be rewarded.", objectives = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.", completion = "<Deputy Feldon listens to your report...>\n\nThere's a sizable force of gnolls encamped there, and from what you tell me they are tough ones.  It must not have been easy for you to gather this intelligence.\n\nHere you are, <name>.  We are grateful for your aid.\n\nAnd if you haven't already done so, speak with Marshal Marris and Magistrate Solomon within Lakeshire.  Our situation grows ever more desperate - those two will have need of you I'm sure." }
WordHunterWoW_QuestEN[247] = { title = "The Hunt Completed", description = "", objectives = "<name>, you have slain all three beasts that comprise the Ashenvale Hunt.  You have brought me adequate proof of their demise; there is no question of your strength and tenacity.  The blood of a hunter streaks through your veins, and you should be commended!\n\nPlease, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today.  May your ancestors watch over you!" }
WordHunterWoW_QuestEN[248] = { title = "Looking Further", description = "I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery.\n\nTake another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep.\n\nFind a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.", objectives = "Climb the intact watch tower beside Stonewatch Keep in Redridge Mountains.\n\nFind a suitable container to place the Glyph of Azora.", progress = "This jar once held a foul-smelling liquor, but now lies empty and forgotten on a pair of barrels.", completion = "It is a suitable vessel for the Glyph of Azora, allowing Theocritus to delve into the minds within Stonewatch Keep." }
WordHunterWoW_QuestEN[249] = { title = "Morganth", description = "After much observation, I have discovered Morganth's plans.\n\nHe searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might.\n\nI am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth.\n\nDefeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.You will receive:", objectives = "Defeat Morganth.\n\nBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest." }
WordHunterWoW_QuestEN[250] = { title = "A Dark Threat Looms", description = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.\n\nThat's why I need you, <name>.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.", objectives = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.", completion = "The suspicious looking barrel contains a strange smelling powder." }
WordHunterWoW_QuestEN[251] = { title = "ranslate Abercrombie's Note", description = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.", objectives = "Bring the Letter to Ello to Sirra Von'Indi.", progress = "A note from Abercrombie the hermit, eh?  I don't know him, though if he lives out at the graveyard then I do know his brains have rotted out!", completion = "<Sirra begins translating the note...>" }
WordHunterWoW_QuestEN[252] = { title = "Translation to Ello", description = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.\n\nYou better bring the translated note back to Ello.\n\nAnd do so quickly, for I fear a doom already lumbers toward our town...", objectives = "Bring the Translated Letter to Lord Ello Ebonlocke", progress = "Ah, is the note translated?  Please, let me see it...", completion = "<Ello reads the letter...and his face goes white.  He then looks at you...>\n\nAlthough the aid you gave Abercrombie may have been motivated from kindness, your actions have doomed our town.\n\n<Ello becomes lost in his thoughts...>" }
WordHunterWoW_QuestEN[253] = { title = "ride of the Embalmer", description = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.\n\nThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.\n\nHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.", objectives = "Find Eliza's grave. Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.", progress = "Have you yet found Eliza's grave?  Do you have the Embalmer's heart?", completion = "You've done it!  The magic within his heart will be proof against the Embalmer's evil, and a powerful aegis over the town of Darkshire.\n\nYou have done a great thing for our people, <name>.  Your name will remain in our annals forever." }
WordHunterWoW_QuestEN[254] = { title = "Digging Through the Dirt", description = "", objectives = "You dig through the semi-loose dirt over the grave...and find the remains of a coffin.\n\nWithin the coffin you can feel the vibrating scrapes of clawed fingers and the gnashing of rotted teeth...\n\nWill you open the coffin and retrieve the Embalmer's heart?" }
WordHunterWoW_QuestEN[255] = { title = "ercenaries", description = "Hunting wildlife gets old after a while. I'm into bigger game... much bigger actually. Ogres to be precise.\n\nThe dwarves here are quite concerned with the Mo'grosh Stronghold to the northeast, but they don't have the manpower to do much about it. If you'd like to join in on the hunt, please feel free to kill any ogres you find. Bring me news regarding the deed, and I'll split the reward from the arrangement I have with the Magistrate.", objectives = "Kelt Thomasin of the Mo'grosh camp has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.", completion = "Ah, this is excellent news! Your efforts are greatly appreciated by myself and the people of Thelsamar. Better yet, if we can solve the ogre problem, we'll be able to shift our focus to those Light-burning troggs." }
WordHunterWoW_QuestEN[256] = { title = "WANTED: Chok'sul", description = "By order of the Magistrate of Thelsamar:\n\nChok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary.\n\nMonetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death.\n\nChok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.", objectives = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.", progress = "Yes? Is there something I can do for you?", completion = "Yech! What is that thing? And why would you bring it...\n\nBloody--! Is it? Well, Light burn me, is that the head of that bloody ogre? This certainly is a catch then! Here, your reward and the thanks of myself and the people of Thelsamar." }
WordHunterWoW_QuestEN[257] = { title = "A Hunter's Boast", description = "Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.\n\nA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge, I'll give you my bow or gun.\n\n<He looks you over dismissively.>\n\nIt seems you haven't much to lose, anyways.", objectives = "Kill 8 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge.", completion = "What? Success?\n\nTake it from me, Astridama, you don't let it get to your head. I mean, any unshaven boy with a bow could have killed such... small specimens. And I hope you don't enjoy killing the buzzards so much, yes? We wouldn't want them to become extinct. \n\nWell, err... Never let it be said that Daryl the Bold would not hold to his word." }
WordHunterWoW_QuestEN[258] = { title = "A Hunter's Challenge", description = "<name>ath, is it? I can tell you're bursting with pride over your hunting prowesst, hm? It's no large feat.\n\nYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them.\n\nDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!\n\nHave I ever related to you the story of how I received my famous scar? No? It was two years ago...", objectives = "Kill 10 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge.", completion = "You seem a bit worse for wear. No doubt the boars gave you some trouble, hm? No worries, I will be discreet about your struggle, I can imagine how hard it must be for you without the accusations of wagging tongues.\n\nOh! You managed to kill the boars? I... well, that is... that is to say, I'm not surprised! Any child could have--bet?\n\nWhat bet?" }
WordHunterWoW_QuestEN[261] = { title = "Down the Scarlet Path", description = "I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.\n\nIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.\n\nDo this, and the Crusade will embrace you.", objectives = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", completion = "You have proven your resolve, and the Scarlet Crusade commends you.\n\nIf you do not shy from righteous slaughter, then perhaps your path lies with us..." }
WordHunterWoW_QuestEN[262] = { title = "The Shadowy Figure", description = "I must know who was that skulker in the shadows I saw the night my family was killed!\n\nPlease, <name>, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!\n\nI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.", objectives = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.", progress = "If you have something that belongs to the shadowy figure for whom you seek, then let me see it.  I may be able to divine something of its owner.", completion = "Hmm... Someone handled this book recently, someone who is driven by revenge.  But the impressions left on it, at least the impressions from the original owner, are faint.\n\nI can tell, however, that the original owner of this book is not a native of Darkshire." }
WordHunterWoW_QuestEN[263] = { title = "In Defense of the King's Lands", description = "The Mountaineers tell me you are quite brave and capable, <name>.  We need a <race> like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned <class> here, let's see what you can do.\n\nGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.\n\nLet's see if you live up to your reputation, Trogg-Slayer.", objectives = "Mountaineer Wallbang in the southern guard tower wants you to kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers.", completion = "I knew the second I laid eyes on you, <name>, that you would make Ironforge proud.  You have served King Magni well.  Now that you've proven yourself to be such a loyal aid to the Kingdom, perhaps you should talk with the Captain to see if he'll entrust you with a higher detail.\n\nI salute you, <name>." }
WordHunterWoW_QuestEN[264] = { title = "Until Death Do Us Part", description = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, {name}! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!", objectives = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.", progress = "The stone is cold to the touch,  but has obviously been abused. Trash litters the area; nicks and gashes decorate the relief atop the coffin; and the foliage around the grave has started to grow over the site.\n\nNo one cares for whoever is buried here, especially not any victims of the plague.", completion = "You place the worthless pendant on the grave, and the gemstone within the setting seems to dull noticeably.\n\nAs you stand to leave, you look down at the pendant; it lies lifelessly over the hands of the relief sculpted into the top of the coffin. Your thoughts are interrupted by a stiff, cool breeze passing over the Sepulcher. For a moment everything around you is silent." }
WordHunterWoW_QuestEN[265] = { title = "The Shadowy Search Continues", description = "Here is your book back, <name>, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.\n\nAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.", objectives = "See if other townsfolk have clues about the shadowy figure.", progress = "Sometimes I'll sell blank books to scholars and mages, or to anyone who wants to keep a journal.\n\nI remember well everyone to whom I sold a book within the last few months...", completion = "Ah, yes.  I sold this book a month ago to a shady person.  He didn't tell me his name, but he was a nervous, jittery chap, always looking over his shoulder.\n\nI hope that helps you..." }
WordHunterWoW_QuestEN[266] = { title = "nquire at the Inn", description = "Here is your book, and good luck with your inquiries.\n\nYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.", objectives = "Search the inn for clues about the shadowy figure.", progress = "The Scarlet Raven doesn't see the business it used to, but we still do get travelers passing through.\n\nIf you can describe the person you're looking for, maybe I'll remember him.", completion = "Oh yeah, I remember this book.  Its owner rented a room for a few days, and spent his nights at the bar, writing.\n\nHe left town in a hurry, muttering about being hunted by...something.  Last I saw him he was heading west out of town, looking for a new spot to hide.\n\nThe first place he'd find to the west is Raven Hill..." }
WordHunterWoW_QuestEN[267] = { title = "The Trogg Threat", description = "<class>, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the town here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as proof.", objectives = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.", progress = "Do you have 8 Trogg Stone Teeth to show me?  If not, there is still work to be done, <name>.", completion = "I am quite impressed, <name>.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!" }
WordHunterWoW_QuestEN[268] = { title = "Return to Sven", description = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...\n\nHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.\n\nAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!", objectives = "Return to Sven with Jitters' completed journal.", progress = "Did you find who the Shadowy Figure was?", completion = "This journal explains much to me, and sets me on the path against the dark riders!  I have seen these riders in Duskwood, and have seen them speak with the wizard Morbent Fel, at the Forlorn Rowe." }
WordHunterWoW_QuestEN[269] = { title = "Seeking Wisdom", description = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.\n\nAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.\n\nYour mission is perilous, but hurry, <name>.  With each passing hour, the shadows of Duskwood grow ever darker.", objectives = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.", progress = "Rest, brother.  I can tell you have traveled far, and you bear a heavy burden.  Can you tell me what casts that dark shadow over you?", completion = "<After reading the journal and hearing your intent...>\n\nAn evil taint has gained a foothold within the already beleaguered Duskwood.  I thank the Light we have a hero such as you to face it.\n\nBut you must first prepare yourself for the coming trial...for the Necromancer Morbent Fel is immensely powerful, and has cast dark enchantments about himself to protect him from physical assaults.  If you are to defeat him, you will need a weapon that is proof against these protections." }
WordHunterWoW_QuestEN[270] = { title = "The Doomed Fleet", description = "Years ago, the Third Fleet of Kul Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.\n\nThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.\n\nGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.", objectives = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.", completion = "Lightforge Iron is a precious metal, but it sounds like your quest is a dire one.  You've come a long way, Brother.  With luck, you might just find what you seek!\n\nAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood." }
WordHunterWoW_QuestEN[271] = { title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the cave to the north.", objectives = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.", progress = "Ah, <name>! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks at it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!" }
WordHunterWoW_QuestEN[272] = { title = "Trial of the Sea Lion", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", objectives = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", progress = "Have you formed your pendant for me to inspect, <name>? If you need help in locating the parts, try asking the local populace for information. Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, <name> - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form." }
WordHunterWoW_QuestEN[273] = { title = "Resupplying the Excavation", description = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.\n\nShouldn't have a problem finding them unless they've already gotten there.", objectives = "Speak with Huldar.", completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later." }
WordHunterWoW_QuestEN[274] = { title = "A Dark Threat Looms", description = "Now get this mixture back to the Chief quickly. The Dark Irons won't delay, so neither can we.", objectives = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir with the disarming mixture..", progress = "What is that you bring from Ashlan?", completion = "A disarming colloid? For Seaforium?  Oh heavens!" }
WordHunterWoW_QuestEN[275] = { title = "Blisters on The Land", description = "I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes.\n\nThe Fen Creepers shamble amidst the waterways of the Wetlands.", objectives = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.", completion = "This land is soothed by your efforts, and for this I will grant you a boon." }
WordHunterWoW_QuestEN[276] = { title = "Tramping Paws", description = "The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.\n\nThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.\n\nKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.", objectives = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.", completion = "By reducing the Gnolls' number, you have tended to the health of the Wetlands.  Although my faith in your people has been taxed in the past, <race>, it may yet be restored." }
WordHunterWoW_QuestEN[277] = { title = "Fire Taboo", description = "The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!\n\nRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.", objectives = "Bring Rethiel the Greenwarden 9 Crude Flints.", progress = "Do you have the Gnolls' tools for fire?", completion = "... thank you.  I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood." }
WordHunterWoW_QuestEN[278] = { title = "A Dark Threat Looms", description = "Begin collecting the disarming materials immediately, <name>. Lurker Venom can be found on the indigenous spiders nearby. Crocolisk tears are found in the Loch itself. But a Mo'grosh crystal will be very difficult to procure. The ogres to the northeast mine them but the crystals are a very rare commodity.\n\nWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.", objectives = "Ashlan Stonesmirk at the Mo'grash Camp wants you to gather Lurker Venom, Frenzy Blood, and a Mo'grosh Crystal.", progress = "Do you have the needed items?  Time is of the essence!!", completion = "Just in time, <name>!" }
WordHunterWoW_QuestEN[279] = { title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", objectives = "Kill 12 Bluegill Murlocs.\n\nSlay Gobbler and take his head.\n\nBring Gobbler's Head to Karl Boran in Menethil Harbor.", progress = "Our merchants will not be safe until we are rid of Gobbler and those murlocs.", completion = "Ah, well done <name>.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines." }
WordHunterWoW_QuestEN[280] = { title = "A Dark Threat Looms", description = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg. No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!\n\nNow I need you to take this mixture and stir it into the keg before it's too late! Hurry!", objectives = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.", progress = "The top of the keg slowly twists off.", completion = "The keg fizzles slightly as the Disarming Mixture settles in." }
WordHunterWoW_QuestEN[281] = { title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.", objectives = "Search the crates and barrels at the coastal Murloc camps.", completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles." }
WordHunterWoW_QuestEN[282] = { title = "Senir's Observations", description = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.", objectives = "Speak with Mountaineer Thalos.", progress = "Hail! Have a care, <name>, the tunnel to Dun Morogh is infested with troggs and is not safe for travel.\n\nIf you haven't any pressing business in Dun Morogh, I'll have to ask you to remain in Anvilmar until the tunnel is safer.", completion = "Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can't very well stop you, can I?\n\nAt least let me provide you with some advice and directions." }
WordHunterWoW_QuestEN[283] = { title = "A Dark Threat Looms", description = "The keg fizzles slightly.", objectives = "The Disarming Mixture seemed to take effect. Return to Chief Engineer Hinderweir to report the good news.The keg fizzles slightly.", completion = "Thank you so much, <name>!! You have saved the Stonewrought Dam!  Without your help, the Dark Iron terrorists would have surely seen to this mighty landmark's demise.  You have made the Kingdom and the Alliance proud, brave <class>.\n\nThe Dam is once again safe. . . for the time being at least. . . ." }
WordHunterWoW_QuestEN[284] = { title = "The Search Continues", description = "You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", objectives = "Search for the Menethil Statuette.", completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!" }
WordHunterWoW_QuestEN[285] = { title = "Search More Hovels", description = "This grouping of Murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil Statuette!", objectives = "Continue searching the Murloc hovels for the Menethil Statuette.", completion = "This barrel is halfway buried amidst the mud and grass ..." }
WordHunterWoW_QuestEN[286] = { title = "Return the Statuette", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised.\n\nThis must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.", objectives = "Bring Karl Boran at Menethil Harbor in Wetlands the Menethil Statuette.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You have well earned this payment for services rendered.\n\nIt is good to see dependable folk like you, especially in trying times such as these." }
WordHunterWoW_QuestEN[287] = { title = "Frostmane Hold", description = "I'm behind on my report, and could use your help, <name>. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.", objectives = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.", completion = "Ah, <name>! I didn't think you'd have much trouble finding the place, my directions are excellent, you know...\n\nLet me just finish up my report then.\n\n\n\nThere! Well, haha, now this certainly is funny... I don't suppose, <name>, that you would mind doing one last favor for me?" }
WordHunterWoW_QuestEN[288] = { title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.", objectives = "Buy First Mate Fitzsimmons a Flagon of Mead.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!" }
WordHunterWoW_QuestEN[289] = { title = "The Cursed Crew", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nBut if you can free some of my brothers, then perhaps you can break their curse.", objectives = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig. Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.", progress = "In my dreams, I can sometimes hear the doomed moans of my brethren!  Please, good sir, free them from the bonds and quiet their cries.", completion = "My thanks to you, <name>.  And the gratitude of my cursed brethren goes to you as well." }
WordHunterWoW_QuestEN[290] = { title = "Lifting the Curse", description = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.\n\nMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.\n\nThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.", objectives = "Get the Intrepid Strongbox Key from Captain Halyndor.\n\nUse the key to open the Intrepid's Locked Strongbox.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly." }
WordHunterWoW_QuestEN[291] = { title = "The Reports", description = "Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court.\n\nDon't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside.\n\nBy the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?", objectives = "Deliver Senir's report to Senator Barin Redstone in Ironforge.", progress = "Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Well, what do you want? Make it quick.", completion = "<He quickly peruses the report.>\n\nAuthority of the KING!? Has Magni taken complete leave of his senses! And that damnable Whitebeard... Taken matters into his own hands, has he? The Senate will not be pleased to hear about this, not one bit.\n\nWhat, are you still here? Go, before I call the guards!" }
WordHunterWoW_QuestEN[292] = { title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.\n\nTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.", objectives = "Bring the Cursed Eye of Paleth to Glorin Steelbrow at Menethil Harbor in Wetlands.", progress = "That drunk Fitzsimmons sent you to me?  Well, you can tell him I don't have any extra ale.  He's going to have to panhandle someone else!", completion = "An Eye of Paleth?  Amazing!  Hmm...there's something wrong with this one.  You found it on one of those shipwrecks?  Well that explains it!  But...I didn't know they had such an Eye on the Third Fleet...\n\nIt's no wonder Fitzsimmons was so spooked.  A Cursed Eye of Paleth is no cause for mirth." }
WordHunterWoW_QuestEN[293] = { title = "Cleansing the Eye", description = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.\n\nI hope, for your sake.", objectives = "Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind.", progress = "What is that orb you have?  It looks...soiled.", completion = "An Eye of Paleth.  But this one has seen much sorrow...it must have been witness to a terrible, terrible tragedy.\n\nLet me cleanse it, for the Eyes were created to shine bright, and their powers can be quite dangerous if tainted like this one." }
WordHunterWoW_QuestEN[294] = { title = "Ormer's Revenge", description = "The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here.\n\nHelp clear the Wetlands of these Raptors, <name>.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can.\n\nThat will be a good start to the vengeance I have planned for them.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.", completion = "Killing is a dirty business, but you did your job well, <name>.  If I weren't obligated to stay with the Prospector and Merrin, I'd be down there shedding blood right along side you." }
WordHunterWoW_QuestEN[295] = { title = "Ormer's Revenge", description = "Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!", objectives = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.", completion = "You did a bang-up job of clearing out those Raptors, <name>!" }
WordHunterWoW_QuestEN[296] = { title = "Ormer's Revenge", description = "While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.\n\nI ask of you now one final task, <name>.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.", objectives = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.", progress = "Is Sarltooth dead? Have you redeemed the memory of the fallen?", completion = "Thank you, <name>.  Your efforts here will not be forgotten.  Many innocent Dwarves died at this site, simply doing their jobs.  The vengeance you delivered to those evil creatures should make them think twice before attacking King Magni's subjects ever again." }
WordHunterWoW_QuestEN[297] = { title = "Gathering Idols", description = "Recently, just before the troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the troggs chased us away from the ruins! And those idols have a strange effect on the yroggs. It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of trogg hands!  You can find the idols on the troggs infesting the site.", objectives = "Bring 8 Carved Stone Idols to Magmar Fellhew at Ironband's Excavation.", progress = "Do you have those Idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, <name>!\n\nAnd you don't look too worse for wear, even with those berserk Troggs about.  I'm going to keep my eye on you...you show some promise." }
WordHunterWoW_QuestEN[298] = { title = "Excavation Progress Report", description = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.\n\nIt's not a difficult task, but it must be done.", objectives = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.", progress = "Oh, a progress report from the site?  Very good!", completion = "Bah!  Ironband's having trouble with the Troggs.  I wonder if he wants that blastpowder to aid his digging, or to aid his efforts against the Trogg beasts...\n\nWell, either way it's powder well spent!\n\nBut what's strange is, I sent him plenty of blastpowder weeks ago.  I wonder where it went..." }
WordHunterWoW_QuestEN[299] = { title = "Uncovering the Past", description = "Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a \"divine plan\" and a \"doomed prophecy.\"\n\nI fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong.\n\nScour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the mystery!", objectives = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.", progress = "Have you uncovered the four fragments yet, <name>?   Ados, Modr, Golm and Neru...", completion = "Ah the Goaz Stone is complete!  Fine work, <name>.  Fine work indeed.  Now I can continue with the delicate translation of this Titan script.  I can make out new words already!  Hmm. . .it says here, \"Old Gods. . .Chained Beneath the Land.\"  This is the beginning of something epic." }
WordHunterWoW_QuestEN[301] = { title = "Report to Ironforge", description = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.", objectives = "Take Ironband's Progress Report to Prospector Stormpike.", progress = "We Stormpikes don't like being bothered with trivial matters, <class>.  I hope you brought news worthy of my valuable attention.", completion = "Curse that Ironband!  I sent him a load of blastpowder weeks ago, but he's made no mention of it in this report.\n\nSo...where did the blastpowder go?!?" }
WordHunterWoW_QuestEN[302] = { title = "Powder to Ironband", description = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.\n\nAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.", objectives = "Speak with Jern Hornhelm in Thelsamar.", completion = "What? Stormpike wants you to personally see the shipment to Ironband?\n\nI... suppose that's fine, the only problem is, I've already sent Huldar with the porters, Miran and Saean. You just missed them, they left just a short while ago." }
WordHunterWoW_QuestEN[303] = { title = "The Dark Iron War", description = "War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after.\n\nWe need you to gather force and push the front back.  If you can kill 10 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!", objectives = "Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", completion = "You upheld your orders well, <class>.  You have proven yourself to be a valiant soldier and loyal servant to King Magni and for that I salute you!  With the pressure you applied to the Dark Iron encampment, we now stand a chance of driving them off our lands for good. . .if only the damned reserve would show. . . ." }
WordHunterWoW_QuestEN[304] = { title = "A Grim Task", description = "Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of the thugs in the Wetlands is a warlock named Balgaras the Foul. He is quite a coward, sending his soldiers to do his bidding but hides in his camp on Direforge Hill, to the southeast.\n\nIf you can find the spineless scum, slay him and bring me his ear. I will reward you, <class>.", objectives = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.", progress = "Were you able to locate Balgaras the Foul yet, <class>?  He has been evading us for quite some time.", completion = "Balgaras the Foul is finally dead.  While his death will not bring back the many innocent dwarves who died needlessly by his hand, it will help to restore peace of mind to those who survived.  With Balgaras dead, the remaining Dark Iron scum should be easy enough to manage.  Now, we must wipe them out before a new leader is sent to these parts.\n\nYou have done well, <class>." }
WordHunterWoW_QuestEN[305] = { title = "In Search of The Excavation Team", description = "Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been.\n\nMy wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong!\n\nLongbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, <name>.  Find Merrin at the excavation site to the east!", objectives = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.", completion = "Oh, thank the heavens you are here!" }
WordHunterWoW_QuestEN[306] = { title = "In Search of The Excavation Team", description = "It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones.\n\nBefore we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost.\n\nOrmer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin.\n\nHere, take this note back to my sweet Tarrel.  It will explain the situation to him.", objectives = "Return to Tarrel Rockweaver at Menethil Harbor in Wetlands with Merrin's note.", progress = "Were you able to find Merrin?  Did she send word?", completion = "Such horrible news!  At least 3 of them survived.  But when will the killing end?  I long for the day when King Magni's subjects can live without fear." }
WordHunterWoW_QuestEN[307] = { title = "Filthy Paws", description = "The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", objectives = "Go to the Silver Stream Mine and collect 6 loads of Miners' Gear.\n\nReturn to Mountaineer Stormpike.", progress = "Do you have that Miners' Gear, <name>?", completion = "Did you see a lot of Kobolds in there?  I can't wait for the order to clear them out of the mine.  The thought of their grimy hands clawing around our mine makes my stomach rumble!" }
WordHunterWoW_QuestEN[308] = { title = "Distracting Jarven", description = "", objectives = "Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!", progress = "Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!", completion = "For me?  You're a true hero, <name>!" }
WordHunterWoW_QuestEN[309] = { title = "Protecting the Shipment", description = "We need to get this powder to Ironband, but this cart isn't going anywhere now. It'll be a lot for us to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for us now that Saean is with them.\n\nI'll feel a lot better if you helped me watch over things. Miran can offload the powder kegs at camp while you and I protect the cart.", objectives = "Protect Huldar and the Ironband Caravan, and then inform Prospector Ironband.", progress = "I'm glad to finally have my powder! We're on top of some amazing discoveries.", completion = "It is troubling news that you bring. To think that the Dark Irons have sympathizers able to procure this sort of material for their dastardly plans.\n\nThat's a matter for someone else to consider, some other time. Thank you for protecting Huldar and the cart!" }
WordHunterWoW_QuestEN[310] = { title = "Bitter Rivals", description = "I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson...\n\nHere, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs!\n\nAnd if the barrels are guarded, then you might have to distract the guard ...", objectives = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.", progress = "The date on this barrel shows that it'll soon be tapped.", completion = "You quickly place Marleth's barrel of Barleybrew Scalder among the Thunderbrew barrels." }
WordHunterWoW_QuestEN[311] = { title = "Return to Marleth", description = "Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...", objectives = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.", progress = "Did you make the switch?", completion = "Not bad, <name>!  Did you have a hard time getting past their guard?\n\nNo matter - many thanks, and if you're ever in need of stout with a kick, don't forget the Barleybrews!" }
WordHunterWoW_QuestEN[312] = { title = "Tundra MacGrann's Stolen Stash", description = "I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back.\n\nYou seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.", objectives = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.", progress = "Were you able to get into my meat locker, <name>?", completion = "What a kind soul you are, <name>!  Thanks to your bravery I won't find myself starving when the cold season flurries blow in." }
WordHunterWoW_QuestEN[313] = { title = "Forced to Watch from Afar", description = "The cataclysm drove the troggs to the surface in hordes, forcing the Frostmane trolls to flee for their lives. Unfortunately, they've decided to settle right on our doorstep and make trouble for us.\n\nI deployed Mountaineer Dunstan and his squad to the Grizzled Den just southwest of town to keep an eye on the wendigos that live there, but now I need to recall them to Kharanos. Find them and tell them to deploy those remote observation bots the gnomes provided, then return to Kharanos.", objectives = "Relay Captain Tharran's orders to Mountaineer Dunstan, Mountaineer Lewin, and Mountaineer Valgrum in the Grizzled Den.", completion = "Thank you for your help, <name>. Our forces are deployed thinly these days and three mountaineers could be the difference between defending Kharanos and being overrun." }
WordHunterWoW_QuestEN[314] = { title = "Protecting the Herd", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With Ironforge's troops already spread thin, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", objectives = "Obtain Vagash's Fang.", progress = "Vagash still terrorizes the herd!  Please help us by killing the wretched beast.", completion = "Very well done!  Veron will be so happy when he hears the good news.  To kill Vagash is no easy task.  I imagine one day you'll be fighting alongside King Magni's men on the Alliance Front." }
WordHunterWoW_QuestEN[315] = { title = "The Perfect Stout", description = "I'm on a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, up on Shimmer Ridge to the northwest.  They use it in their strange, tribal rituals. We haven't found much use for it, but it has a unique taste... and I want to experiment with it in my brews!\n\nObtaining the shimmerweed will be dangerous, but I'll pay well for any you can \"borrow\" from the baskets in the troll village.", objectives = "Bring 7 Shimmerweeds to Rejold Barleybrew in Kharanos.", progress = "Do you have that shimmerweed?  I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.", completion = "Great!  I can't wait to use these in some of my recipes.  There's one in particular I think it'll work great in..." }
WordHunterWoW_QuestEN[316] = { title = "<UNUSED 1>", description = "", objectives = "" }
WordHunterWoW_QuestEN[317] = { title = "Stocking Jetsteam", description = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.", objectives = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.", progress = "Preparations are going well.  How goes your hunting?", completion = "By Magni's beard, you sure did a lot of hunting!!  Thank you, <name>." }
WordHunterWoW_QuestEN[318] = { title = "Evershine", description = "Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat.\n\nHe lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road.\n\nAnd...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.", objectives = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.", completion = "Bellowfiz needs some of my Evershine?  Hm...all right." }
WordHunterWoW_QuestEN[319] = { title = "A Favor for Evershine", description = "I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close.\n\nWe're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.", objectives = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.", completion = "Thank you, <name>.  It'll be nice to work our crafts without hearing so many growls and snorts outside the village." }
WordHunterWoW_QuestEN[320] = { title = "Return to Bellowfiz", description = "Here's your cask of Evershine, <name>.  And again, thank you for the hunting earlier.", objectives = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.", progress = "Did you get that Evershine?", completion = "Yes, this will do just fine.  I think I'll open a bottle right now and have a taste..." }
WordHunterWoW_QuestEN[321] = { title = "Lightforge Iron", description = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...\n\nEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.", objectives = "Search the wreckage of The Flying Osprey in the Wetlands.The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it. It was shipping a load of Lightforge Iron and joined the Third Fleet for protection. Ironic that it sunk to the same dragons...\n\nEnough history. The Flying Osprey is wrecked to the south of Menethil Harbor. If you find the Lightforge Iron there, bring it to me.", completion = "This chest is waterlogged, and its siding broken.  Many claw marks mar both the inside and outside of the chest...as if Murlocs have searched through it and stolen its treasure.\n\nBut tucked deep within the chest is a single Lightforge Ingot.  Unfortunately, many more will be needed if enough metal to fashion a weapon is to be gained." }
WordHunterWoW_QuestEN[322] = { title = "Blessed Arm", description = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.\n\nI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!", objectives = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.", progress = "How might I ply my craft for you, <class>?", completion = "That is quite a tale you have.  And lightforge iron!  Not for years have I worked with such a metal.  It will be an honor to craft with it again.  And you must return to me later with the story of your battle against the Necromancer.\n\nBut we get ahead of ourselves.  First, your weapon against Morbent Fel..." }
WordHunterWoW_QuestEN[323] = { title = "Proving Your Worth", description = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.\n\nYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.", objectives = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.", completion = "Your skill in combat, <name>, can not be doubted.  Your resolve may yet see us through to the end of Morbent Fel!" }
WordHunterWoW_QuestEN[324] = { title = "The Lost Ingots", description = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.", objectives = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.", progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?" }
WordHunterWoW_QuestEN[325] = { title = "Armed and Ready", description = "Here is the weapon against the fiend of which you spoke.  You're all ready, <name>.  Best of luck to you, and I look forward to your tale of glory!", objectives = "Bring Morbent's Bane to Sven in Duskwood.", progress = "Hello, <name>.  You haven't been gone that long, but I see a fire in your eyes I did not see before.", completion = "Ah, this will be proof against the fiend Morbent Fel!  Well done!\n\nYou are ready.  Morbent Fel will fall." }
WordHunterWoW_QuestEN[328] = { title = "The Hidden Key", description = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed.", objectives = "Use the Small Brass Key to open Bookie Herod's Strongbox.", progress = "The strongbox is bound in bronze, very sturdy, and very heavy.", completion = "Opening the strongbox, it's clear that this is where Herod keeps his more valuable coins and items." }
WordHunterWoW_QuestEN[329] = { title = "The Spy Revealed!", description = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.", objectives = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.", progress = "Did you discover who knew Thorsen's secret?  Is there a traitor among us?", completion = "Thank you, <name>.  This note is the clue we need to root out the traitor!" }
WordHunterWoW_QuestEN[330] = { title = "Patrol Schedules", description = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.", objectives = "Speak with Corporal Sethman.The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week. So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman. He handles the patrol schedules and can tell you who was with Thorsen.", completion = "Oh, yes I can check that for you.  Let's see...last week it was...\n\n...why, it was Private Merle scheduled with Thorsen.  They had the same patrol times all of last week." }
WordHunterWoW_QuestEN[331] = { title = "Report to Doren", description = "Did Lieutenant Doren want you to report back to him with that patrol information?", objectives = "Speak with Lieutenant Doren.Did Lieutenant Doren want you to report back to him with that patrol information?", completion = "It pains me to find out it was Merle who betrayed us.  He has always been a brave soldier, and I had thought his heart was true.  But it is a great relief to have found him out - with a spy like him among us...we would not last long against Colonel Kurzen." }
WordHunterWoW_QuestEN[332] = { title = "Wine Shop Advert", description = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of the famous Dalaran Noir.  You won't regret it!", objectives = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.", progress = "Greetings and welcome, master.  Have you yet tried one of our fine wines?", completion = "Ah, so you've seen Renato?  Well here you are, sir.  A bottle of our special Dalaran Noir.  You'll not find its equal in all of Azeroth!" }
WordHunterWoW_QuestEN[333] = { title = "Harlan Needs a Resupply", description = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.", objectives = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.", progress = "You bring word from Mr. Bagley?", completion = "It says here that Harlan's business is booming.  That's good news, but I wonder why people have need of all that armor.  I've heard nothing of open war...is there something the nobles aren't telling us?\n\nWell, thank you for bringing the request.  Here's your payment, and I'll see to it that Harlan gets his supplies." }
WordHunterWoW_QuestEN[334] = { title = "Package for Thurman", description = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great {class} like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, {name}.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.", objectives = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.", progress = "Are you here to buy clothes?", completion = "Oh, blast!  I thought forgetting my kit would free me from work.  Now I guess I'll have to help the Larsons with their sewing...\n\nOh, well.  Fun will come later I guess." }
WordHunterWoW_QuestEN[335] = { title = "A Noble Brew", description = "Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little \"establishment\" down here and is lobbying for a full investigation.  I have a plan to keep Wishock \"preoccupied,\" but I'll need your help. \n\nThere is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetlands.", objectives = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.", progress = "Wishock will soon garner enough support to cause us much grief.  Were you able to obtain the Tear of Tilloa or Musquash Root yet?", completion = "Most excellent! These are fine samples indeed!" }
WordHunterWoW_QuestEN[336] = { title = "A Noble Brew", description = "Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little \"tavern\" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, <name>.\n\nTake it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.", objectives = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.", progress = "Can you not see that I am busy?  My words must be heard!  I am very important to the future of this Kingdom!\n\nOh... what have you there?  Why it looks like a refreshing drink...", completion = "Ah, thank you for bringing me this fine looking stout, servant.  Here's a copper for you.  Now, out of sight with you and let me enjoy my drink!" }
WordHunterWoW_QuestEN[337] = { title = "An Old History Book", description = "Although the cover of this book is marred by scratches and caked with mud, the words \"The History of Stormwind\" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page.\n\nIt looks like someone checked out this book, and never returned it...", objectives = "Return the book: The History of Stormwind, to the Stormwind Library.", progress = "Ooh!  What's that old book you have there?  Can I see it??", completion = "Oh my!  This book hasn't rested on these shelves since before the rebuilding of Stormwind, years ago.  It will have to be restored of course, it's in bad shape, but I would be honored to place it within our rare books collection.\n\nThank you, sir.  Please accept this as payment for returning the book!" }
WordHunterWoW_QuestEN[338] = { title = "The Green Hills of Stranglethorn", description = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.", objectives = "Collect the missing pages from The Green Hills of Stranglethorn manuscript. Once all four chapters are complete, return them to Barnil.", progress = "Have you assembled the chapters yet, <name>?", completion = "You've certainly saved me a heap of trouble, <name>!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!" }
WordHunterWoW_QuestEN[339] = { title = "Chapter I", description = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!", objectives = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.", progress = "I don't suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.", completion = "At last!  Chapter I is complete!" }
WordHunterWoW_QuestEN[340] = { title = "Chapter II", description = "Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.", objectives = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.", progress = "We still need pages 10, 11, 14 and 16 to complete Chapter II, <name>.", completion = "Chapter II is finally complete!  Well done!" }
WordHunterWoW_QuestEN[341] = { title = "Chapter III", description = "Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .", objectives = "Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.", progress = "Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.", completion = "Phew!  Good work, <name>.  Chapter III is now back together in one piece!" }
WordHunterWoW_QuestEN[342] = { title = "Chapter IV", description = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.", objectives = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.", progress = "We just need three pages to finish off Chapter IV, <name>.  Do you have pages 25, 26 or 27 yet?", completion = "Superb!  We now have Chapter IV ready to go!" }
WordHunterWoW_QuestEN[343] = { title = "Speaking of Fortitude", description = "I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - \"The Stresses of Iron.\"  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you!\n\nThe Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.", objectives = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech.", completion = "Metallurgy?  Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech!  Now...which particular book was it the good brother needed?" }
WordHunterWoW_QuestEN[344] = { title = "Brother Paxton", description = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago.  I wonder why it's taking him so long...", objectives = "Speak with Brother Paxton in the Northshire Abbey.The Stresses of Iron?  Yes, I know the book. Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago. He spent most his time deep in the mountains of Khaz Modan, digging ore. Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey. The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago. I wonder why it's taking him so long...", completion = "Mr. Sheaf is wondering where his book is?  Well this is a tad embarrassing.  I have the book, but I'm still making my copy and I'm not quite ready to give the original up!" }
WordHunterWoW_QuestEN[345] = { title = "Ink Supplies", description = "I've been meaning to finish my copy of The Stresses of Iron, but...\n\nWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly.  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!\n\nTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.", objectives = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.", completion = "You need what??  Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks.  If you need Rethban Iron Ore, you'll have to get it yourself!" }
WordHunterWoW_QuestEN[346] = { title = "Return to Kristoff", description = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.", objectives = "Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.", progress = "Were you able to find the book?", completion = "That's the one!  Thank you, <name>.  May the Light shine brightly upon both your body and spirit!" }
WordHunterWoW_QuestEN[347] = { title = "Rethban Ore", description = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.\n\nWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.\n\nSo if you need some, you'll have to get it yourself.", objectives = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.", progress = "Do you have the Rethban Ore?", completion = "Oh, splendid!  I can use this ore to make my dye, and then can finish copying The Stresses of Iron.\n\nThank you, <name>!" }
WordHunterWoW_QuestEN[348] = { title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying....", objectives = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me...." }
WordHunterWoW_QuestEN[349] = { title = "Stranglethorn Fever", description = "temp text 02 - description", objectives = "temp text 02 - log", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other Gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!" }
WordHunterWoW_QuestEN[350] = { title = "Look to an Old Friend", description = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...\n\nHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.\n\nYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.", objectives = "Speak to Elling Trias in Stormwind.", completion = "You're kidding? Shaw wants my help again? Of all the nerve...\n\nThe Defias Brotherhood, you say? Well, you're certainly the bearer of wonderful news, aren't you? Next you're going to tell me that Deathwing is still alive and attacking the city.\n\nAll right, tell me everything from the beginning. And don't leave out something you think might not be important. I need to know it all." }
WordHunterWoW_QuestEN[351] = { title = "Find OOX-17/TN!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"", objectives = "Bring the distress beacon to Oglethorpe's homing robot.", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover.  The beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-17/TN is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" }
WordHunterWoW_QuestEN[353] = { title = "Stormpike's Delivery", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", objectives = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.", progress = "You come all the way from Stormwind?  I hear it's getting dicey down there in the human lands, with brigands and orcs running about.  A perfect place for a <class> to prove his worth!", completion = "Aha!  So Grimand finally finished my axe!  I can't wait to try it against some troggs and kobolds!\n\nMany thanks, <name>.  It was a long distance to travel for this delivery.   Here are some coins for your efforts." }
WordHunterWoW_QuestEN[354] = { title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.", objectives = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless." }
WordHunterWoW_QuestEN[355] = { title = "Speak with Sevren", description = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.", objectives = "Speak with Magistrate Sevren in Brill.", completion = "Coleman speaks well of you, <name>, telling of your successful forays into the Agamand Mills.\n\nThe Forsaken have need of your talents once again..." }
WordHunterWoW_QuestEN[356] = { title = "Rear Guard Patrol", description = "Here at the Bulwark, we must be on constant alert to protect Tirisfal from Scourge incursions.  Even so, sometimes the Scourge will slip past us.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our supply line to be cut.\n\nPatrol west and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead.  It has become a haven for interloping Scourge.", objectives = "Kill 8 Bleeding Horrors and 8 Wandering Spirits.", completion = "Very good.  Your efforts do much to keep the Scourge at bay.  A commendation will be sent to my superior, Executor Zygand." }
WordHunterWoW_QuestEN[357] = { title = "The Lich's Identity", description = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.", objectives = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.", progress = "<name>, have you acquired the book?", completion = "Very good, <name>.  I will study this book and determine the identity of that lich.  You have served your Queen well.\n\n\n\nAstonishing!  The book you retrieved belongs to no one other than Gunther Arcanus!\n\nGunther was a skilled Necromancer in life; he and I were friends and comrades-in-arms, before the Plague.  And judging from his book he has grown even more powerful in death.\n\nHis skills would be a great boon to us." }
WordHunterWoW_QuestEN[358] = { title = "Graverobbers", description = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.", objectives = "Kill Rot Hide Graverobbers and Rot Hide Mongrels. \n\nBring 8 Embalming Ichors to Magistrate Sevren in Brill.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, <name>.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by our Apothecaries.  It may have secrets we can use against them.\n\nAs I said, well done.  But our struggle continues, and the conflict will surely offer you more chances to prove your worth to the Forsaken." }
WordHunterWoW_QuestEN[359] = { title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", objectives = "Speak with Deathguard Linnea.", completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead." }
WordHunterWoW_QuestEN[360] = { title = "Return to the Magistrate", description = "Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.\n\nAnd if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.", objectives = "Return to Magistrate Sevren in Brill.", completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  The Lich King and his minions are ceaseless in their assaults.\n\nBut we will not give in.  He will not take us again!" }
WordHunterWoW_QuestEN[361] = { title = "A Letter Undelivered", description = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...", objectives = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.", progress = "Yes?", completion = "Oh...my poor Thurman!  I begged him to leave Agamand Mills with me and my father, but his family loyalty was too strong!  And I knew it!  I just knew it that Brand meant him harm!!  Oh, curse this Plague, and the Scourge!\n\n<Yvette's face then smoothes and grows cold.>\n\nBut regrets are for the weak.  As a Forsaken, I have new goals and love is not one of them.  I would thank you for delivering this letter, for I had wondered what happened to my past love.\n\nBut that life is over.  Forever." }
WordHunterWoW_QuestEN[362] = { title = "The Haunted Mills", description = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.", objectives = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.", progress = "Did you find Devlin?", completion = "Thank you.  Devlin's bones will rest nicely on my mantle.\n\nIf my cold heart can find warmth, it is in knowing that the Agamands are destroyed.  They failed me and my family when the Plague came - now I swear I will smash their remains under my heel!" }
WordHunterWoW_QuestEN[363] = { title = "Rude Awakening", description = "I'm glad you woke up. We were ready to toss you into the fire with the others, but you pulled through.\n\nI am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King's slave no more.\n\nSpeak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know.\n\nTo get out of this crypt, take the steps up to the surface. Follow the road down to the chapel to find Sarvis.", objectives = "Speak with Shadow Priest Sarvis.", completion = "Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...\n\nI see the confusion on your face. Let me try to explain our... situation... to you.\n\nWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step." }
WordHunterWoW_QuestEN[364] = { title = "The Mindless Ones", description = "Since the first Forsaken crawled out of his tomb, we have been at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres.\n\nThe Lich King no longer sits the Frozen Throne, but the northern part of the village remains overrun with his slaves.  Destroy them, show them no mercy, our former brothers and sisters as they might be.", objectives = "Kill 5 Mindless Zombies and 5 Wretched Ghouls.", completion = "It is unfortunate that the Scourge cannot be brought into the fold, their large numbers would be useful in the battles ahead.\n\nBut they will not join us, so we have no choice but to destroy them." }
WordHunterWoW_QuestEN[365] = { title = "Fields of Grief", description = "What have we here?  You look like a fledgling <class>.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.", objectives = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.", progress = "Deathguard Simmer sent word that you were going to provide me with some much needed reagents.  Were you able to gather 10 pumpkins yet, <name>?", completion = "You have performed your bidding well, young <class>.  You are proving yourself to be quite an asset to The Dark Lady's army." }
WordHunterWoW_QuestEN[366] = { title = "Return the Book", description = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.", objectives = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.", progress = "Your masters are fools to send you here, for I will never again be a Scourge slave!", completion = "My book?!?  So you were the thief who stole it!\n\nBut...what is this new enchantment upon it...Bethor?  He is in  Lordaeron?\n\nIf he still exists, then perhaps he too escaped from the Lich King's grasp..." }
WordHunterWoW_QuestEN[367] = { title = "A New Plague", description = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory.", objectives = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.", progress = "Have you collected 5 vials of darkhound blood yet, <name>? Time is fleeting!", completion = "You have done well, <name> and I thank you for your efforts." }
WordHunterWoW_QuestEN[368] = { title = "A New Plague", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.", objectives = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.", progress = "<name>, were you able to obtain 5 Vile Fin Scales from the Murlocs?", completion = "The scales are perfect, <name>. Exactly what I needed for this concoction." }
WordHunterWoW_QuestEN[369] = { title = "A New Plague", description = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.", objectives = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.", progress = "Do you have some venom from a Vicious Night Web Spider yet, <name>?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, <name>.  Everything else has been added to my concoction and boiled down.  Finally, I am ready to try this new deadly agent!" }
WordHunterWoW_QuestEN[370] = { title = "At War With The Scarlet Crusade", description = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.", objectives = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.", completion = "Captain Perrine's death will undoubtedly please The Dark Lady.  You have performed your duty well, <class>." }
WordHunterWoW_QuestEN[371] = { title = "At War With The Scarlet Crusade", description = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!", objectives = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.", completion = "Captain Vachon's death will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit.  But other threats loom." }
WordHunterWoW_QuestEN[372] = { title = "At War With The Scarlet Crusade", description = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.", objectives = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.", completion = "You have done extremely well, <class>.  With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all.  I have a good feeling about you, comrade." }
WordHunterWoW_QuestEN[373] = { title = "The Unsent Letter", description = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed.", objectives = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", progress = "Yes? Is there something I can help you with?", completion = "Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you've killed him then? Pardon me in saying, but I'm somewhat surprised. He was a peerless fighter in his younger years. Let's see what he finds the need to write to me about after so many years.\n\n<Baros peruses the letter.>\n\nEdwin... I see the years haven't changed you a bit, an idealist as ever, and a romantic. He doesn't care who he hurts, <name>. Revenge has consumed him. But then, I'm not sure I can blame him." }
WordHunterWoW_QuestEN[374] = { title = "Proof of Demise", description = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, <class>. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.", objectives = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.", progress = "Have you collected 10 Scarlet Insignia Rings yet, <class>?", completion = "Varimathras would be proud.  You serve your leaders well, <class>." }
WordHunterWoW_QuestEN[375] = { title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, <name>, so that I can continue to serve the cause.", objectives = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.", progress = "Do you have five Duskbat Pelts and some Coarse Thread yet, <name>?", completion = "I appreciate your efforts, <name>.  May Sylvanas recognize your bravery one day. . . ." }
WordHunterWoW_QuestEN[376] = { title = "The Damned", description = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.\n\nFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.", objectives = "Obtain 4 Scavenger Paws and 4 Duskbat Wings.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, <name>. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it..." }
WordHunterWoW_QuestEN[377] = { title = "Crime and Punishment", description = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.", objectives = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.", progress = "So long as a molester of the dead like Dextren Ward is permitted to live, justice stands betrayed.  Return to me once Lord Ebonlocke's sentence of death is carried out on that defiler, Ward.  We shall give the families of the dead the closure they deserve and better yet, we will send a clear message to the House of Nobles in Stormwind.", completion = "So Dextren Ward finally paid for his crimes against humanity?  Good riddance to the scum I say.  And cheers to you, my friend!  Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles.  Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny." }
WordHunterWoW_QuestEN[378] = { title = "The Fury Runs Deep", description = "You have proven your loyalty to King Magni, <class>.  And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, <name>.  For Longbraid!  Bring me his head!", objectives = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", progress = "I won't let foolish Human bureaucracy interfere with Dwarven matters, <name>.  Kam Deepfury is a proven conspirator in the Thandol Span attack.  King Magni's good people lost their lives because of Deepfury's deceit.  The Humans might be content to let Deepfury rot in The Stockade but I will not sleep soundly at night until Deepfury is slain.", completion = "So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death?  Good.  Serves the cowardly Dark Iron scum right.  You have done well, <class>.  The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest.  Their families will have the peace of knowing Deepfury got the punishment he deserved.  Longbraid's brother's death has been avenged." }
WordHunterWoW_QuestEN[379] = { title = "Slake That Thirst", description = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.\n\nNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.", objectives = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.", progress = "Well, did the nomads \"volunteer\" up those water pouches for you?", completion = "Excellent, the power source is yours.  Now, it isn't completely designed for use in a science kit like that, so you'll only have a limited amount of time before all the data you collect will go kablooey!\n\nWhen you collect everything you need for whatever it is you are doing, bring it to me and I'll shut it down properly.  You'll have at most two hours to get what you need to get done, done.\n\nIf you don't get it done in time, I can always sell you another power source to try again.  You heard me - sell!" }
WordHunterWoW_QuestEN[380] = { title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.\n\nThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, <name>.", objectives = "Executor Arren wants you to kill 8 Young Night Web Spiders and 5 Night Web Spiders.", completion = "Hmm, well, it's a start. It'll take a few weeks or months to fully clean out the infestation. After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, <name>, I'm sure I can find something else for you to do." }
WordHunterWoW_QuestEN[381] = { title = "The Scarlet Crusade", description = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.\n\nMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!\n\nBe careful, their unholy zeal makes them dangerous adversaries.", objectives = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.", progress = "Those fools... They happily send themselves to their own graves.", completion = "If only they listened to reason, eh, <name>? Perhaps we could sit them down for reasonable discourse... ha!\n\nLight-blinded fools." }
WordHunterWoW_QuestEN[382] = { title = "The Red Messenger", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, <name>. Find that messenger and bring me whatever information you can find.", objectives = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.", progress = "How goes your mission, <name>?", completion = "Hmm... Let's see what you've got...\n\n<He begins to rifle through the documents you recovered.>\n\nSome news of their exploits against us... Worthless. Scouting reports... New orders, \"Continue to build up a camp near the ruined city...\" Nothing we didn't know already... Ah, what's this? A map of the dispositions of some of their field commanders and agents! We can use this." }
WordHunterWoW_QuestEN[383] = { title = "Vital Intelligence", description = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.\n\nTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way.", objectives = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, <name>. Hmm... names of the officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike." }
WordHunterWoW_QuestEN[384] = { title = "Beer Basted Boar Ribs", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me some boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", objectives = "Ragnar Thunderbrew in Kharanos wants 4 Tender Boar Ribs and a mug of Rhapsody Malt.", progress = "I'm going to need those crag boar ribs and a mug of Rhapsody Malt, <name>.", completion = "The Malt is brewed, the Boars are dead\nAnd before all is done and anything said\nWe will have to fight for first dibs\nOn these savory Beer Basted Boar Ribs!" }
WordHunterWoW_QuestEN[385] = { title = "Crocolisk Hunting", description = "Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.\n\nWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.\n\nWhy, this one time...", objectives = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.", progress = "Did I tell you about the time I almost lost my hand to one of the crocs? Nasty bugger it was, teeth like knives. But I was lucky... Jammed the brute's jaw shut with my knife. Still have the knife around here somewhere...", completion = "Well now, these are excellent specimens you collected, <name>. Good money for high quality materials, that's for sure." }
WordHunterWoW_QuestEN[386] = { title = "What Comes Around...", description = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, <name>.  Travel to The Stockade and behead him before trickery is upon us.", objectives = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", progress = "Have you been to Stormwind yet, to The Stockade?  I fear whatever trickery that has kept Targorr the Dread alive for this long will eventually bring about his freedom.  He was sentenced to die, <name>, not act as some political pawn on a noble's whim.", completion = "Targorr the Dread has finally met his fate.  I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death's ruthless grip.  You have done well, <name>.  Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics." }
WordHunterWoW_QuestEN[387] = { title = "Quell The Uprising", description = "The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.", objectives = "Warden Thelwater of Stormwind wants you to kill 10 Prisoners, 8 Convicts, and 8 Insurgents in The Stockade.", completion = "Your efforts in The Stockade were valiant, <name>.  It's obvious this problem is bigger than the both of us.  But you have performed well and for that I am thankful." }
WordHunterWoW_QuestEN[388] = { title = "The Color of Blood", description = "Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back.\n\nI want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of blood.", objectives = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.", progress = "I see you are back, <class>.  Have you collected 10 Red Wool Bandanas from those Defias Scum in The Stockade yet?", completion = "So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. \n\nBut alas, I cannot return to the past.  Just know, <name>, that you have brought my family justice through your deeds." }
WordHunterWoW_QuestEN[389] = { title = "Bazil Thredd", description = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.", objectives = "Speak with Warden Thelwater in the Stockade.", completion = "What in the Light do you want? Can't you see we have a crisis here?\n\nBazil Thredd?! Why would you want to speak with that fool? How am I supposed to know you're not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren't open, I might throw you in one for a while!" }
WordHunterWoW_QuestEN[391] = { title = "The Stockade Riots", description = "Let's get one thing straight, <name>: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.", objectives = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", progress = "Either you bring me Thredd's head, or I'll take yours, understand, <name>?", completion = "Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.\n\nI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.\n\nI'd guess, then, that you didn't get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd's activities." }
WordHunterWoW_QuestEN[392] = { title = "The Curious Visitor", description = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.\n\nAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.\n\nHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.", objectives = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.", progress = "Yes, <name>? What have you found?", completion = "Hmm. Maelik? No, the name doesn't sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think." }
WordHunterWoW_QuestEN[393] = { title = "Shadow of the Past", description = "I really haven't a clue, <name>. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.\n\nIf anyone knows, it'd be him.", objectives = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.", progress = "Greetings. Of what service can I be to you, <class>?", completion = "What? What's this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.\n\nRegardless, he is an assassin and I know a good deal about him.\n\nMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind." }
WordHunterWoW_QuestEN[394] = { title = "The Head of the Beast", description = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.\n\nHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, <name>. The nobles can think they rule the city all they want, but some things remain out of their hands.", objectives = "Speak to Mathias Shaw in Stormwind.", completion = "He is dead, then? Your justice was swift, <name>. I pray to the Light that I never become your quarry!\n\n\n\nI mean no criticism, <name>. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you." }
WordHunterWoW_QuestEN[395] = { title = "Brotherhood's End", description = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.\n\nA bit of advice, <name>: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.\n\nAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.", objectives = "Speak with Baros Alexston in Stormwind.", completion = "It's good to see you, <name>. I have heard that Lord Gregor Lescovar was found dead not long ago.\n\nIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef's revenge." }
WordHunterWoW_QuestEN[396] = { title = "An Audience with the King", description = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.\n\nYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.", objectives = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.", progress = "<name>, yes? I was informed by Baros Alexston that you would be coming. I must say, I am most interested in what you have to say.", completion = "You are to be commended for the service you have done for Stormwind, <name>. If VanCleef had been successful in his machinations, he would no doubt have done considerable harm to the kingdom--something we must obviously avoid.\n\nTake this, <class>, as a token of the my appreciation." }
WordHunterWoW_QuestEN[397] = { title = "You Have Served Us Well", description = "I hear Lord Wishock enjoyed his beverage.  \n\nYou have served us well, <name>.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.You will receive:", objectives = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.I hear Lord Wishock enjoyed his beverage. \n\nYou have served us well, <name>. The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you. For your efforts, I have prepared a special gift for you. Speak with my servant, Zggi, and claim your reward.You will receive:" }
WordHunterWoW_QuestEN[398] = { title = "Wanted: Maggot Eye", description = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.", objectives = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.", progress = "Yes?", completion = "Maggot Eye's dastardly acts have finally been avenged.  Maybe your acts of valor will send a clear message to those who wish to bring harm to our people.  On behalf of the town of Brill I thank you, <name>." }
WordHunterWoW_QuestEN[399] = { title = "Humble Beginnings", description = "It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by transients.\n\nI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.\n\nYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?", objectives = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.", progress = "<name>! Did you have any luck?", completion = "Oh, thank you, <name>! It's of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks." }
WordHunterWoW_QuestEN[400] = { title = "Tools for Steelgrill", description = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.", objectives = "Deliver Steelgrill's Tools to Beldin Steelgrill.", progress = "Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?\n\nWell take a number and get comfortable.  I'm working on a couple engines right now and won't have time for another job for at least a few days.\n\nOr, were you here for something else...?", completion = "You have my tools?  Well done, lad, well done!  I just broke my last fang-ratchet an hour ago and I need one of those to finish repairs on Pilot Stonegear's siege engine.  You did a good thing by lugging those tools here, <name>.\n\nHere, take these coins for your help." }
WordHunterWoW_QuestEN[401] = { title = "Wait for Sirra to Finish", description = "I'm almost finished translating that note.  If you come back in a few moments I should be done.", objectives = "Wait a moment, then speak with Sirra Von'Indi again.I'm almost finished translating that note. If you come back in a few moments I should be done.", completion = "There we are.  It's translated...\n\n<The air grows heavy, as if a thick, black curtain is drawn over the land...>" }
WordHunterWoW_QuestEN[402] = { title = "Sirra is Busy", description = "I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to.  Perhaps later, if we survive, I can finish this translation.", objectives = "Check back with Sirra later to see if he's still busy.I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to. Perhaps later, if we survive, I can finish this translation." }
WordHunterWoW_QuestEN[403] = { title = "Guarded Thunderbrew Barrel", description = "", objectives = "" }
WordHunterWoW_QuestEN[404] = { title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge.\n\nGo there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.", objectives = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I regret not being there to see you smash those <race> into rotting pulp!" }
WordHunterWoW_QuestEN[405] = { title = "The Prodigal Lich", description = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, <name>, will be that agent.\n\nPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.\n\nSo ready yourself, <class>.  You must not fail.\n\nYou may find Bethor in the Magic Quarter of the Undercity.", objectives = "Present Sevren's Orders to Bethor Iceshard in the Undercity.", progress = "Greetings.  Either you do not know who I am, or your business with me is urgent.\n\nBecause if neither of these were true, then you would not be foolish enough to disturb me...", completion = "Ah, you are the agent sent by Magistrate Sevren.  Then yes, your business with me is crucial.\n\nI trust Sevren has mustered someone suitable for my task...but we shall see." }
WordHunterWoW_QuestEN[407] = { title = "Fields of Grief", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.", objectives = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .\n\n. . .oh wait.  Is that food for me?  I am so hungry. . .", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin. . . ." }
WordHunterWoW_QuestEN[408] = { title = "The Family Crypt", description = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.", objectives = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.", progress = "Time is not a luxury we have, <name>.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, <name>, and one day we will drive the Lich King himself from Azeroth!" }
WordHunterWoW_QuestEN[409] = { title = "Proving Allegiance", description = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.", objectives = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.", completion = "You have defeated Lillith Nefara, proving you are an enemy of the Scourge.  Incredible.\n\nI had believed I was the only Undead with free will, but you have shown me there are others who have broken the Lich King's domination." }
WordHunterWoW_QuestEN[410] = { title = "The Dormant Shade", description = "", objectives = "This is an old, beaten, bloody table.", progress = "This is an old, beaten, bloody table.", completion = "You place the Candle of Beckoning upon the table and light it..." }
WordHunterWoW_QuestEN[411] = { title = "The Prodigal Lich Returns", description = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.", objectives = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", progress = "Have you returned Gunther's book?  Has he responded?", completion = "You convinced him to join us!  You have done a great deed for the Forsaken, <name>.  The Dark Lady will be informed." }
WordHunterWoW_QuestEN[412] = { title = "Operation Recombobulation", description = "I should go back to Gnomeregan and continue researching a cure for irradiated gnomes.\n\nBut, I stayed behind in Kharanos because the town is my home and I wanted to help defend it from the Frostmane attacks. I've been working on maintaining and repairing the steam tanks.\n\nFor some reason, Frostmane scavengers have taken a liking to the gyromechanic gears I need to complete the repairs. They're all over the Frostmane Front to the southeast of town. Will you help me get those gears back?", objectives = "Bring Razzle Sprysprocket 8 Gyromechanic Gears.", progress = "Those pilots can't wait to get back into their steam tanks and take to the field again. Let's not let them down.", completion = "These gyromechanic gears are perfect! These two tank pilots are well on their way to being back in the fight!" }
WordHunterWoW_QuestEN[413] = { title = "Shimmer Stout", description = "I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.\n\nHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.\n\nCan you bring him this Barrel of Shimmer Stout for me?", objectives = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.", progress = "Hello, <class>!  And what business takes you all the way out here?\n\nSomething exciting, I hope.  I haven't been in a good fight in days, and this barrel of ale is almost dry...", completion = "<Mountaineer Barleybrew tastes the Shimmer Stout...>\n\nOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!" }
WordHunterWoW_QuestEN[414] = { title = "Stout to Kadrell", description = "I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.\n\nTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.\n\nGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!", objectives = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.", progress = "Greetings, <class>, and welcome to Thelsamar!", completion = "Now, let me have a taste...\n\nMagni's Beard!  This stuff gets your head turning!  And it lightens the limbs, too.\n\nI feel like I can fly!" }
WordHunterWoW_QuestEN[415] = { title = "Rejold's New Brew", description = "Rejold Barleybrew at Brewnall Village has been asking for you.\n\nHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.\n\nThere could be some free booze in it for you...", objectives = "Speak with Rejold Barleybrew.", completion = "<name>!  You know that Shimmerweed you brought me?  Well I used it in a few recipes I've been working on, and one of them turned out great!\n\nHere, try it out and tell me what you think..." }
WordHunterWoW_QuestEN[416] = { title = "Rat Catching", description = "We have a real infestation problem all over. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!\n\nWe want them eliminated. Hunt them, bring me their ears and earn their bounty.\n\nYou can find the greatest concentration of tunnel rat kobolds in and around the Silver Stream Mine to the east.", objectives = "Bring 8 Tunnel Rat Ears to Mountaineer Stormpike in Algaz Station.", progress = "Hail, <name>.  How goes the rat catching?", completion = "Ugh!  When I asked for those ears I didn't realize they'd smell so bad!\n\nHere's your reward, <name>.  Well done." }
WordHunterWoW_QuestEN[417] = { title = "A Pilot's Revenge", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", objectives = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot at the South Gate Outpost.", progress = "Hello, <name>.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, <name>.  Your deed will be remembered by the pilots of the Ironforge Siege Brigade." }
WordHunterWoW_QuestEN[418] = { title = "Thelsamar Blood Sausages", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy <class>, you'll be any exception.\n\nAll I need is bear meat and rest is all in the preparation. You get me some of those, and leave the cooking to Vidra!", objectives = "Bring 8 pieces of Bear Meat to Vidra Hearthstove in Thelsamar.", progress = "I'm all ready to start cooking, do you have the ingredients for me?", completion = "Trust me, it seems a lot harder than it looks, but...\n\nOh, I've never known someone to take much interest in the making of sausages, but I'll give you the recipe just in case. Here you go, mind you eat them fresh!" }
WordHunterWoW_QuestEN[419] = { title = "The Lost Pilot", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, <name>. Find him.", objectives = "Pilot Hammerfoot at the South Gate Outpost wants you to find Pilot Hildelve.My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills. We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot.\n\nIt's been days, and I've heard some beastly growls north of Helm's Bed Lake, west of the tunnel. Mori's tough as nails, but I'm worried.\n\nPlease, <name>. Find him.", completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end." }
WordHunterWoW_QuestEN[420] = { title = "Senir's Observations", description = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.", objectives = "Deliver Grelin's report to Senir Whitebeard in Kharanos.", progress = "How are you? Like to share a drink with me, perhaps? Not much else to do in the cold.", completion = "What's this? Ah, my brother's report. Hmm...\n\nI told him to be sparing with the use of the King's name, but he didn't listen. No harm, I suppose, though it's sure to ruffle some feathers in the Senate. Not that those weren't some feathers that needed ruffling! Hah!\n\nNonetheless, I guess that means that I should send my report on to Ironforge as well, but I must admit I'm a bit behind. Bloody cold.\n\nI should have some work for you later, if you're interested." }
WordHunterWoW_QuestEN[421] = { title = "Prove Your Worth", description = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.", objectives = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.", completion = "You have served me well, <class>.  It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal's curse." }
WordHunterWoW_QuestEN[422] = { title = "Arugal's Folly", description = "How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.\n\nWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.\n\nArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.", objectives = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.", progress = "Before I know what we are dealing with here, <class>, I need to study the spell known as Remedy of Arugal.  Bring it to me now or I shall be forced to find myself a worthy servant.", completion = "This is precisely the spell I was in search of, <class>.  If your dedication to The Dark Lady's cause remains infallible you will find you have quite a future amongst The Forsaken." }
WordHunterWoW_QuestEN[423] = { title = "Arugal's Folly", description = "After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!\n\nArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.", objectives = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.", progress = "I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal.  Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.", completion = "I hope I can acquire enough energy from such a limited sample.  Perhaps I should have had you get more shackles.\n\nNonetheless, you showed great skill in collecting these, <class>." }
WordHunterWoW_QuestEN[424] = { title = "Arugal's Folly", description = "It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.\n\nBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.\n\nThe mine would prove to be quite a resource for Varimathras's advance.\n\nI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.", objectives = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.", progress = "Has Grimson the Pale been slain?  Varimathras will not be pleased if we ignore his bidding.", completion = "Most excellent.  The mine will provide superb resources for our forces as we spread throughout Silverpine and into Azeroth." }
WordHunterWoW_QuestEN[425] = { title = "Ivar the Foul", description = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.\n\nWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.\n\nKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.", objectives = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.", progress = "Have you killed Ivar the Foul?  If you won't do it for me and my brother, then do it for the Forsaken.", completion = "Ah, thank you.  You have my gratitude, <name>.\n\nAnd I will include you in the report I make to my superiors." }
WordHunterWoW_QuestEN[426] = { title = "The Mills Overrun", description = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.", objectives = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.", progress = "Our battles with the Scourge wage on, <name>.  Do your part and throw those cursed, mindless undead back into the Plaguelands!", completion = "Your efforts in the war are felt among us, <name>.  I will not thank you for doing what is necessary, but the Deathguards of Tirisfal will remember your name." }
WordHunterWoW_QuestEN[427] = { title = "At War With The Scarlet Crusade", description = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.", objectives = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.", completion = "Most excellent, <class>.  Your skill in the art of combat is undeniable." }
WordHunterWoW_QuestEN[428] = { title = "Lost Deathstalkers", description = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.", objectives = "Find the Deathstalkers Quinn and Rane Yorick.", completion = "You found us!  And not a moment too soon..." }
WordHunterWoW_QuestEN[429] = { title = "Wild Hearts", description = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.\n\nGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.\n\nYou can find plenty of worgs between here and Malden's Orchard to the east.", objectives = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.", progress = "My time is short, <class>, for the Dark Lady has charged me with a grave task.", completion = "<Renferrel takes the hearts.>\n\nIt is troubling to hear our Deathstalkers have failed their mission.\n\nLet us hope that these failures are rare.\n\nI'll give you the potion in a moment, but here is its recipe - if those Deathstalkers find themselves in need of future aid, then perhaps you can give it yourself." }
WordHunterWoW_QuestEN[430] = { title = "Return to Quinn", description = "Here is the potion to aid in Quinn Yorick's recovery.\n\nNow if you will excuse me, I have very important work to continue...", objectives = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", progress = "My sister told me you were here to aid us.  Is that true?", completion = "<Quinn takes the potion and drinks it.>\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, <name>." }
WordHunterWoW_QuestEN[431] = { title = "Candles of Beckoning", description = "", objectives = "You grab one of the candles and place it in your pack." }
WordHunterWoW_QuestEN[432] = { title = "Those Blasted Troggs!", description = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!", objectives = "Kill 8 Rockjaw Skullthumpers and 8 Rockjaw Bonesnappers in the Gol'Bolar Quarry and its mine.", progress = "It makes me so mad! Grrr...", completion = "Well, that makes me feel a little better...\n\nBut I won't be happy until they're all dead! All of them!" }
WordHunterWoW_QuestEN[433] = { title = "The Public Servant", description = "As a member of the Senate and the Explorers' League, I've taken it upon myself to investigate conditions at the quarry. The troggs have run wild!\n\nThey've made a mess of the Gol'Bolar quarry. As we dug deep into the earth, they poured out, destroying our equipment and trapping many of the miners below ground.\n\nWe have to get them out of there. I've had mages working overtime to enchant these runes of return. If you can get them to the trapped miners, they can return to the surface in safety.", objectives = "Distribute Runes of Return to 7 Trapped Miners in the Gol'Bolar Quarry Mine.", completion = "What a relief! I'm glad to see that you were able to save so many miners, <name>. I will make sure that their families are notified immediately.\n\nThe Senate will know of your role in winning back the mines." }
WordHunterWoW_QuestEN[434] = { title = "The Attack!", description = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.\n\nWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.\n\nLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.", objectives = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", completion = "So it is done? Good. Thank you greatly for your discretion, <name>. You've proven worthy on more than one count. I'll be sure to keep my eyes on you and your progress within the Alliance.\n\nBe sure to keep your nose clean." }
WordHunterWoW_QuestEN[435] = { title = "Escorting Erland", description = "The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.\n\nI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.\n\nPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...", objectives = "Escort Erland through the wolves, to Rane Yorick.", completion = "Thank you for the aid, <name>.  I had feared Erland was overcome by the dangers of Silverpine.  With your help, I see that he has not." }
WordHunterWoW_QuestEN[436] = { title = "Ironband's Excavation", description = "Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.\n\nIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.\n\nGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.\n\nTo get to the excavation site, go around the southern tip of the lake, then head east.", objectives = "Speak with Explorer Fellhew.", completion = "Jern wants to know what the slowdown is, eh?\n\nIronband is putting together his latest progress report with details, but I can tell you this:\n\nIt's the Troggs!!" }
WordHunterWoW_QuestEN[437] = { title = "The Dead Fields", description = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.", objectives = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.", progress = "Have you defeated Nightlash, <name>?  Our success against the rot hides depends on her destruction!", completion = "I heard of your successful raid against the rot hides, <name>, and this essence is proof of Nightlash's death.\n\nThe Scourge have lost ground this day.  Your value to the Forsaken grows." }
WordHunterWoW_QuestEN[438] = { title = "The Decrepit Ferry", description = "<name>, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.\n\nThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.", objectives = "Go to the Decrepit Ferry.\n\nSearch for the reason the Scourge are there.", completion = "Heaped within this boat is a pile of wrapped corpses.  And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.\n\nThe fate of the corpses must lie on Fenris Isle." }
WordHunterWoW_QuestEN[439] = { title = "Rot Hide Clues", description = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  \n\nOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:\n\n\"For Deliah\"", objectives = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.", progress = "<name>.  You return, so I assume your investigations bore fruit?", completion = "You say that this ring was worn by a woman, recently killed?\n\nThe only nearby source of such a body would be the mass graves in Tirisfal.  The Rot Hide Gnolls must be taking those corpses to Fenris Isle!" }
WordHunterWoW_QuestEN[440] = { title = "The Engraved Ring", description = "If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.\n\nBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.", objectives = "Bring Deliah's Ring to Magistrate Sevren in Brill.", progress = "Hello, <name>.  What brings you back to Brill?", completion = "A Deliah did live in Brill not long ago.  She was buried in the mass grave but if what you say is true, then the Rot Hide Gnolls must have stolen her body and taken it to Silverpine.\n\nThe Rot Hides, like all the Scourge, must be destroyed.  I trust you are taking steps to make that happen." }
WordHunterWoW_QuestEN[441] = { title = "Raleigh and the Undercity", description = "Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.\n\nRaleigh is in the Trade Quarter of the Undercity.", objectives = "Bring Deliah's Ring to Raleigh.", progress = "Do I know you?", completion = "Yes, this ring was my wife's.  Her fate was the fate of all who fail to endure these harsh times.  I feel nothing for her death, nor for the story you tell of her body's abduction.\n\nSuch feelings have long since grown cold within me.  But desire does still burn in my dead heart, <name>.\n\nDesire for revenge." }
WordHunterWoW_QuestEN[442] = { title = "Assault on Fenris Isle", description = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.\n\nYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!\n\nThis mission is as dangerous as it is vital, <name>.  You must not fail.", objectives = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.", progress = "The Scourge cannot be allowed to remain in Silverpine, <name>.  Come back to me when you have proof of Thule's death.", completion = "The death of Thule Ravenclaw was no small event, <name>.  Renferrel tells me that the energies released when you destroyed Thule were felt even as far as the Sepulcher.\n\nYour actions ring through the ranks of the Forsaken.  Your value to us grows." }
WordHunterWoW_QuestEN[443] = { title = "Rot Hide Ichor", description = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.\n\nGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.", objectives = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.", progress = "Do you have the rot hide ichor, <name>?", completion = "Very good.  This ichor will help us understand the nature of the rot hides, and may show us their weakness...\n\n...if they have one." }
WordHunterWoW_QuestEN[444] = { title = "Rot Hide Origins", description = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.\n\nWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.\n\nGo.  You will find Bethor in the Magic Quarter of the Undercity.", objectives = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.", progress = "My studies require great concentration.  So I hope your visit is not a frivolous one.", completion = "This substance is laced with powerful spells, some of which I have not seen for a long, long time...\n\nOne moment -- I must invoke a spell of divination..." }
WordHunterWoW_QuestEN[445] = { title = "Delivery to Silverpine Forest", description = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.", objectives = "Take Apothecary Holland's findings to Apothecary Renferrel in Silverpine Forest.", progress = "What business do you have with me, <class>?", completion = "Ah, how good of Apothecary Johaan to send his research.  With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades.  Which reminds me, I need to get those samples off to the Necropolis soon.\n\nBut you must excuse my rambling.  Extend your stay in Silverpine, <name>.  We could use an able bodied <class> like you around here." }
WordHunterWoW_QuestEN[446] = { title = "Thule Ravenclaw", description = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.\n\nI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!\n\nI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.", objectives = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.", progress = "Greetings, <name>.  What did Bethor have to say?", completion = "This scroll is laced with powerful magic.  I've never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle." }
WordHunterWoW_QuestEN[447] = { title = "A Recipe For Death", description = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.", objectives = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", progress = "Hail, <class>.  What business do you have with the Royal Apothecary Society?", completion = "How good of Apothecary Renferrel to send you to me, <name>.  These samples will indeed prove useful to the cause.  I will begin studying their toxic and contaminable properties at once." }
WordHunterWoW_QuestEN[448] = { title = "Report to Hadrec", description = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.", objectives = "Report to High Executor Hadrec at the Sepulcher.", completion = "If what Bethor says is true then Thule Ravenclaw is a force that must be dealt with, and dealt with soon.\n\nTo aid in this task, you may take something from our arsenal here..." }
WordHunterWoW_QuestEN[449] = { title = "The Deathstalkers' Report", description = "Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.", objectives = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.", progress = "Did you discover the fate of the Deathstalkers?", completion = "I hadn't accounted for the level of Scourge presence we've seen in Silverpine Forest, nor for the troubles our Deathstalkers have had in their scouting efforts.\n\nYour aid to our Deathstalkers was invaluable, <name>.  And you will be commended." }
WordHunterWoW_QuestEN[450] = { title = "A Recipe For Death", description = "You can be of further service to the Royal Apothecary Society, <name>.\n\nWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.\n\nRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.", objectives = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", progress = "I see you are back, <name>.", completion = "Apothecary Berard's journal!  Why you are quite brave, <name>.  Now let's see what Berard was up to before he went mad. . ." }
WordHunterWoW_QuestEN[451] = { title = "A Recipe For Death", description = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.\n\nHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.\n\nCollect samples of the moss as well as the rare Hardened Tumor and take them to Master Apothecary Faranell in the Undercity.", objectives = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.", progress = "What brings you back to the Undercity, <name>?", completion = "Such a blow to the Royal Apothecary Society to lose Berard.  But through your hard work and Apothecary Renferrel's diligent research Berard's studies will still be useful to The Dark Lady's plight.\n\nWe are on the cusp of something great here, <name>.  If you were not so skilled in the ways of combat I would try to recruit you for membership in the Society." }
WordHunterWoW_QuestEN[452] = { title = "Pyrewood Ambush", description = "You got here just in the nick of time, <name>!\n\nThe Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master.\n\nI cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.", objectives = "Help Deathstalker Faerleia kill the Pyrewood Council.", completion = "You fought like a true disciple of the Dark Lady, <name>.  With the council dead, perhaps we can gain control of this town once and for all and drive Arugal from Shadowfang Keep.  I salute you!" }
WordHunterWoW_QuestEN[453] = { title = "Finding the Shadowy Figure", description = "Good luck, <name>.  I hope you find the chap, and I hope you find him alive.\n\nIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.", objectives = "Find the Shadowy Figure. Your clues:\n\nHe is not native to Darkshire.\n\nHe is a nervous, jittery person.\n\nHe left Darkshire and headed west.", progress = "Who are you??  Leave me be!", completion = "<Jitters sighs...>\n\nYes, I'm the author of that book.  You finally found me, eh?\n\nWell if you read that journal...then you only know the half of it!" }
WordHunterWoW_QuestEN[454] = { title = "After the Ambush", description = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.\n\nI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?", objectives = "Speak with Miran.", completion = "Hello, <class>.\n\nYou'll be escorting me to the excavation site? That's good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?\n\nAnyways, let me just make some final checks. Talk to me again when you're ready to go." }
WordHunterWoW_QuestEN[455] = { title = "The Algaz Gauntlet", description = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.\n\nBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.\n\nMenethil is through Dun Algaz, then north along the road, then west at the fork.\n\nWe're counting on you, <name>.  Do not fail.", objectives = "Traverse Dun Algaz.\n\nKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\n\nReport to Valstag Ironjaw in Menethil Harbor.", completion = "Your report is full of bad news!\n\nI see the Dragonmaws are making a strong move into Algaz.  Normally the Dragonmaws just hide up in the hills.  What made them surge into Algaz is still a mystery...\n\nThank you, <name>.  And we'll probably want your help dealing with these orcs." }
WordHunterWoW_QuestEN[456] = { title = "The Balance of Nature", description = "Greetings, <name>.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young <class>, and thin the boar and saber populations so that nature's harmony will be preserved.", objectives = "Kill 3 Young Nightsabers and 3 Young Thistle Boars.", completion = "You performed your duties well, <name>." }
WordHunterWoW_QuestEN[457] = { title = "Nature's Dues", description = "Thinning the younger population of creatures here in Shadowglen was a good start, <name>, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture farther in Shadowglen to the northeast and slay mangy nightsabers and thistle boars in the name of balance.", objectives = "Kill 6 Mangy Nightsabers and 6 Thistle Boars.", completion = "You have proven your dedication to nature well, <name>.  A young <class> like yourself has a promising future." }
WordHunterWoW_QuestEN[458] = { title = "The Woodland Protector", description = "Thank goodness you are here, <class>. Strange news has traveled to me through the whisperings of the forest spirits.\n\nThe mysterious woodland protector, Tarindrella, has returned to Shadowglen again. The dryad's presence has not been felt in the forests since before the blessing of Teldrassil. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.", objectives = "Seek out the dryad known as Tarindrella.", completion = "I see you found me, young <race>.  Melithar is a wise druid to have sent you." }
WordHunterWoW_QuestEN[459] = { title = "Demonic Thieves", description = "Vicious little grell! They've been stealing from our foodstores again.\n\nIf you wouldn't mind lending a hand, whatever they've stolen is sure to be scattered through grell camps to the west. I would be glad to reward you if you can bring it all back to me.", objectives = "Recover Dellylah's Stolen Beans, Dellylah's Stolen Water, and Dellylah's Stolen Bags.", progress = "Satisfy my suspicions, <name>.  Bring to me 8 Fel Moss.", completion = "Your service to the creatures of Shadowglen is worthy of reward, <name>.\n\nYou confirmed my fears, however.  If the grells have become tainted by the Fel Moss, one can only imagine what has become of the Gnarlpine tribe of furbolgs who once lived here.\n\nShould you find yourself in Dolanaar, able <class>, seek out the knowledgeable druid, Athridas Bearmantle.  He shares our concern for the well being of the forest." }
WordHunterWoW_QuestEN[460] = { title = "Resting in Pieces", description = "You don't look like a rot hide.  Good.  I had lost hope...\n\nMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!\n\nPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.", objectives = "Bring Alaric's Head to his grave.", progress = "This grave was hastily dug.", completion = "Thank you, <name>.  I had feared the Gnolls destroyed my body.  It is good to know they did not." }
WordHunterWoW_QuestEN[461] = { title = "The Hidden Niche", description = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!\n\nThe alcove is in the southwestern tower of the keep, behind a dusty shelf.\n\nTake my body, but leave my boots.  They never fit me anyway...", objectives = "Take Alaric to the hidden alcove.", progress = "This is the spot!  Bring me closer...", completion = "There we are, it's open.  Leave me here.  I spent the best days of my life in this keep, and the thought of resting within its walls gives me comfort.\n\nBe sure to close the alcove tight - I don't want those Rot Hides to find me.\n\nOh, and take this.  You've earned it." }
WordHunterWoW_QuestEN[463] = { title = "The Greenwarden", description = "You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from <his/her> death?\n\nIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!\n\nAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?", objectives = "Find the Greenwarden.", completion = "The roots and ferns speak well of you, small one.  Although I have many names, I answer to only a few.  But you may call me Rethiel.\n\nAnd you must harken...for these lands weep from festered wounds, and I would charge you to heal them." }
WordHunterWoW_QuestEN[464] = { title = "War Banners", description = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.\n\nNow they've gained strength, and have an encampment northeast of Menethil.\n\nWe want you to attack that encampment.  Gather and bring me their war banners as proof.", objectives = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.", progress = "Have you attacked the Dragonmaw encampment?", completion = "Well fought, <name>.  The Dragonmaws are not the same threat they were when they had dragons, but they're still fierce opponents.\n\nThe Dragonmaws are led by Nek'rosh, son of Nekros, who was the former head of the Dragonmaws years ago.  Nekros used powerful magic to tame the Red Dragons, but when that magic failed him...the dragons were not happy.\n\nNekros was killed, and his son has vowed revenge against the dragons who slew his father." }
WordHunterWoW_QuestEN[465] = { title = "Nek'rosh's Gambit", description = "While you were fighting the Dragonmaws, we discovered more of their plans.\n\nNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!\n\nYou need to take out those catapults.  They're in the Dragonmaw encampment.\n\nHere, take this tinder.  Fight your way to the catapults and light them with the tinder.\n\nAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.", objectives = "Destroy the Dragonmaw catapults.", progress = "The first catapult is before you.  Will you set it aflame?", completion = "You place some of the tinder on the catapult then strike a spark onto it.\n\nFlame erupts and quickly spreads!" }
WordHunterWoW_QuestEN[466] = { title = "Search for Incendicite", description = "I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!\n\nGet me incendicite ore and I'll find someone brave enough to experiment with it.\n\nOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!", objectives = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.", progress = "Where is that ore, <name>?!", completion = "You got the ore!  Well done, <name>!  I'll get someone to work with this right away.  Let's hope he doesn't blow himself up!" }
WordHunterWoW_QuestEN[467] = { title = "Stonegear's Search", description = "Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower!\n\nHe heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.", objectives = "Speak with Pilot Stonegear.", completion = "Hello <name>.  You're here about the task I have, eh?  It's good to see a young <race> like yourself whose blood burns at the prospect of adventure!" }
WordHunterWoW_QuestEN[468] = { title = "Report to Mountaineer Rockgar", description = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  \n\nIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.", objectives = "Speak with Mountaineer Rockgar.", completion = "Hello, <class>!  You're here for the scouting mission, are you?  Very good!\n\nI hope your gear is in good condition, because this \"scouting\" mission has changed into something more messy..." }
WordHunterWoW_QuestEN[469] = { title = "Daily Delivery", description = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.", objectives = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.", progress = "Hello there, <class>. Could I interest you in a pair of boots?  Perhaps some newly cured skins?", completion = "Hmm, this is from Einar, right? Hasn't delivered his skins to me in person for almost a week now. No doubt it's some differences with the wife!\n\nMaybe I'll have my wife go speak with Sida sometime..." }
WordHunterWoW_QuestEN[470] = { title = "Digging Through the Ooze", description = "On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked.\n\nI threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away.\n\nThe bad news is that I really need to get the contents of my bag!\n\nI don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!", objectives = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.", progress = "Did you find my bag?", completion = "Oh, thank you, <name>! I was afraid that it was lost for good!\n\n\n\nHm, I don't have much use for this anymore, but wash it off and I'm sure you could make use of it." }
WordHunterWoW_QuestEN[471] = { title = "Apprentice's Duties", description = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.", objectives = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.", progress = "My apprentice is like a son to me.  It's going to be hard for him to live his life with only one leg.\n\nAh, <name>, how goes it?  Do you have my skins?", completion = "Hmm... Don't suppose you'd be interested in becoming my apprentice, would you?\n\nHah! No, I'm just kidding. You're much too old, for one thing.  Besides - from the looks of you, it would seem that you have other ambitions in life.  Nonetheless, these are some fine skins you've procured, and I'll be able to put them to good use." }
WordHunterWoW_QuestEN[472] = { title = "Fall of Dun Modr", description = "Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, <class>.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, <race>!", objectives = "Search for Longbraid near the town of Dun Modr.Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, <class>. Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn. As we left the town I was hit by a stray axe in the back. All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers. Hope still burns within me. Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, <race>!", completion = "What brave <class> sends word from Menethil?  Ah <name>, they call you.\n\nYou bring hope to a hopeless situation.  'Tis good news indeed that young Harlo survived.  While fleeing he received a grievous wound.  We had but little time to send him on his way on the back of the only surviving steed with the regiment.\n\nBut now we face a perilous situation.  Dun Modr has fallen and we are but a shadow of the great regiment we once were." }
WordHunterWoW_QuestEN[473] = { title = "Report to Captain Stoutfist", description = "<name>.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.", objectives = "Speak with Captain Stoutfist.", completion = "<name>.  Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz.  You're a <race> of worth.\n\nAnd I have a task for you." }
WordHunterWoW_QuestEN[474] = { title = "Defeat Nek'rosh", description = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh.", objectives = "Kill Chieftain Nek'rosh\n\nBring Nek'rosh's Head to Captain Stoutfist.", progress = "Have you killed Nek'rosh?", completion = "Stoutly done, <name>.  You have dealt a telling blow to the Dragonmaw orc clan.  They may never recover.  And the destruction of those catapults has made Menethil Harbor safe.\n\nYou are a <race> of merit, and the kingdom of Ironforge rewards those who serve it well." }
WordHunterWoW_QuestEN[475] = { title = "A Troubling Breeze", description = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.", objectives = "Seek out Gaerolas Talvethren in Starbreeze Village.", completion = "Thank the forest spirits you are here!  I knew Athridas would sense trouble and send help." }
WordHunterWoW_QuestEN[476] = { title = "Gnarlpine Corruption", description = "The Gnarlpine tribe's corruption has returned!\n\nThey ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village. Something in the forest has corrupted Ursal the Mauler, their chieftain, and he is using the evil powers of the fel moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young {class}.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!", objectives = "Return to Athridas Bearmantle in Dolanaar.", completion = "By the stars!  This is quite disturbing indeed!\n\nWe've had troubles in the past with the corruption of the furbolgs, but such troubles should be long past since the cleansing of Teldrassil. I fear for all our people if the blessings of the aspects themselves cannot redeem our great tree." }
WordHunterWoW_QuestEN[477] = { title = "Border Crossings", description = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.", objectives = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.", completion = "<Prying open the lid of the crate, you find an assortment of carefully-packed objects. On the top of the crate lies a bundle of maps, yellowing with age, that appear to depict Silverpine Forest and other parts of western Lordaeron.\n\nUnderneath the maps is a mysterious-looking magical pendant.>" }
WordHunterWoW_QuestEN[478] = { title = "Maps and Runes", description = "<You quickly remove the pendant from the crate and replace the lid.>", objectives = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.", progress = "Have you learned anything useful, <name>?", completion = "Maps and this... pendant, hm? Interesting.\n\nIt is obvious that the Dalaran wizards are interested in Ambermill for some purpose, but still, their aim is hidden to me.\n\nPerhaps Dalar will know something of their use." }
WordHunterWoW_QuestEN[479] = { title = "Ambermill Investigations", description = "Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can...\n\nThe conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them.\n\nTake the main road south and the eastern fork into Ambermill.", objectives = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.", progress = "We must hurry, their plans must not come to fruition, or we may lose our hold on Silverpine Forest.", completion = "Dalar has found that the weaving is quite far along, despite the setback.\n\nA wizard of great power is guiding the magic energy. He must be stopped quickly." }
WordHunterWoW_QuestEN[480] = { title = "The Weaver", description = "An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.\n\nYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.", objectives = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.", progress = "Quickly, time runs short, <name>!", completion = "The magic of the wizards dissipates, and the ley energies fade into dormancy. Your efforts have been fruitful, <name>, and we have dealt a major blow to our enemies, and to the overbearing wizards of Dalaran.\n\nWe must be vigilant, however, knowing that source of energy lies so close at hand... Plans must be made for the future." }
WordHunterWoW_QuestEN[481] = { title = "Dalar's Analysis", description = "Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.", objectives = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.", progress = "Yes, <class>? What is it?", completion = "Interesting, more machinations of the Kirin Tor, it would seem. This is a powerful artifact. It was used frequently by powerful wizards of the Kirin Tor to channel magical energies.\n\nThat they are delivering so many to Ambermill indicates that they must be undergoing a project of some magnitude.\n\nI will see if I can pierce their shields and ascertain their intent." }
WordHunterWoW_QuestEN[482] = { title = "Dalaran's Intentions", description = "Of course! How could I have forgotten?\n\nAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.\n\nWe cannot allow this to happen...\n\nIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.\n\nRelay this information to Allister, he will decide a course of action.", objectives = "Speak with Shadow Priest Allister at the Sepulcher.", completion = "Ill news you bring, <name>. If Dalar is correct--and I've no reason to believe he isn't--we must move quickly.\n\nI must confer with him on our plan of attack. But in the meanwhile we will have to delay their progress." }
WordHunterWoW_QuestEN[483] = { title = "The Relics of Wakening", description = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den, tucked in the hill to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.", objectives = "Retrieve the Relics of Wakening.", progress = "<name>, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban'ethil Barrow Den to the west.\n\nFor every minute we delay their fate comes one step closer to eternal doom.", completion = "You have succeeded, young <class>!  Well done.  And just in time I might add." }
WordHunterWoW_QuestEN[484] = { title = "Young Crocolisk Skins", description = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.", objectives = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.", progress = "<name>, right? Do you have my skins?", completion = "Nice work you've done here, <name>. The quality of these skins is superb. I'll have to get them into the curing process as soon as possible. Oh, but before I get to that, there's some other work I need done that I think you might be able to take care of." }
WordHunterWoW_QuestEN[485] = { title = "Find OOX-09/HL!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"", objectives = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-09/HL is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" }
WordHunterWoW_QuestEN[486] = { title = "Ursal the Mauler", description = "Now the time has come to save the Druids of the Talon. If we fail now, {name}, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed. Travel northwest on the road and find the path north into The Cleft. Ursal's den will be there.", objectives = "Kill Ursal the Mauler.", completion = "<name> you have proven yourself a most worthy and able <class>.  A <race> who follows the path of honor as sure as you do is certain to find great glory in this world.\n\nUrsal's death brings safety to our once slumbering druids, but the source of his corruption yet remains within our forests. With time, I trust that you will find this evil and cleanse it for the sake of all of our people. You are destined for great things, young <class>." }
WordHunterWoW_QuestEN[487] = { title = "The Road to Darnassus", description = "The road to Darnassus must be kept safe. Corrupted furbolgs from the Gnarlpine tribe have been attacking travelers relentlessly.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily. We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, {class}. Their den lies up this northern path. Slay these Gnarlpine ambushers and report back to me.\n", objectives = "Slay 8 Gnarlpine Ambushers.", progress = "The road is still not safe, <class>. Travel forth and slay the Gnarlpine ambushers and return to me.", completion = "You have served the good people of Dolanaar and Darnassus well, brave <class>.  As a member of the Sentinel force of Teldrassil, I salute your efforts." }
WordHunterWoW_QuestEN[488] = { title = "Zenn's Bidding", description = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling {class} to perform my bidding.\n\nYou see, {name}, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain... reagents.  Fetch for me nightsaber fangs, strigid owl feathers and swatches of webwood spider silk.\n\nLet's keep this our little secret, {race}.", objectives = "Retrieve 2 Nightsaber Fangs, 2 Strigid Owl Feathers and 2 swatches of Webwood Spider Silk.", progress = "Have you been a busy little bee, <name>?  I've been waiting for you to bring me what I need.", completion = "Ha ha!  Well, done indeed.\n\nWho would have ever guessed that I, Zenn Foulhoof, would have a <race> to do my bidding?  Certainly not me!  But so it goes... this beloved world of ours is full of surprises.\n\nThree cheers for the naive and gullible!" }
WordHunterWoW_QuestEN[489] = { title = "Seek Redemption!", description = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a {race}, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snack.", objectives = "Collect 3 Fel Cones.", progress = "What do you have for me, <name>?  A lovely snack I presume?", completion = "Ah, what a sweet <race>!  I knew you would come in handy!" }
WordHunterWoW_QuestEN[491] = { title = "Wand to Bethor", description = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.\n\nHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.", objectives = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", progress = "<name>.  Have you defeated Thule Ravenclaw?", completion = "...what is this?  Thule had our Woven Wand?  I thought it was lost when our friendship sundered and he sided with the Lich King!\n\nHe must not have invoked its power, for if he had I would have sensed it.  And it is good that he did not use it...\n\nThis is a marvelous find.  You have my gratitude, <name>, and will be rewarded." }
WordHunterWoW_QuestEN[492] = { title = "A New Plague", description = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", objectives = "Bring Johaan's Special Drink to the Captured Mountaineer.", progress = "Why if I had my trusted rifle you'd be as good as dead, <class>.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  I'm sure it's no Rhapsody Malt but I'll take anything to whet the old whistle at this point." }
WordHunterWoW_QuestEN[493] = { title = "Journey to Hillsbrad Foothills", description = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closely!", objectives = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.", progress = "You have something for me?", completion = "Ah, most excellent.  Apothecary Renferrel has my utmost respect.  I am anxious to study his work." }
WordHunterWoW_QuestEN[494] = { title = "Time To Strike", description = "Be silent and pay attention, <class>.\n\nI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!", objectives = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.Be silent and pay attention, <class>.\n\nI was sent to this position in order to survey the town of Hillsbrad. My mission is one of reconnaissance. It is imperative that you send word to High Executor Darthalia in Tarren Mill at once. Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs. Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!", completion = "The raven's cry from the west doth beckon?\n\nSuperb news!  Hillsbrad is ripe for attack.  We can carry out our plan of destruction now.  Varimathras will be pleased." }
WordHunterWoW_QuestEN[495] = { title = "The Crown of Will", description = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.\n\nHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.\n\nThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.", objectives = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.", completion = "You were sent by Shalindra? Very well then, you'll find I don't waste much time with idle chatter.\n\nMug'Thol is an irritant, and we will deal with him quickly, thoroughly, and without incident." }
WordHunterWoW_QuestEN[496] = { title = "Elixir of Suffering", description = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, <name>.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.", objectives = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.", progress = "I see you are back.  I hope you were able to gather the agents I need.  Another deathless day will put me in such a gloomy mood.", completion = "These specimens are perfect.  Well, <name>, you have managed to bring me the slightest hint of joy on yet another miserable day.  Your efforts are appreciated." }
WordHunterWoW_QuestEN[498] = { title = "The Rescue", description = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.", objectives = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", completion = "So the humans thought to turn our warriors into slaves, did they? We'll show them!\n\nIt would seem that they have taken Gol'dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...\n\nWhen we have a lead, I will be sure to tell you, <name>." }
WordHunterWoW_QuestEN[499] = { title = "Elixir of Suffering", description = "It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.\n\nThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.\n\nLet us see if our little potion has achieved its desired effect.\n\nGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.", objectives = "Give Umpi the Elixir of Suffering.", progress = "Ribbit!", completion = "Croak!" }
WordHunterWoW_QuestEN[500] = { title = "Crushridge Bounty", description = "Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well.\n\nWe can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door!\n\nGo north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.", objectives = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains. Bring them to Marshal Redpath in Southshore.", progress = "<name>, are you still hunting ogres?  Do you have the knucklebones I had you gather?", completion = "Very good, <name>.  You must have hacked through a whole mess of ogres to get all these knucklebones.\n\nThat should keep them out of our hair.  At least, for a while." }
WordHunterWoW_QuestEN[501] = { title = "Elixir of Pain", description = "Oh, <name>. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.", objectives = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.", progress = "I remember you, <name>.  You were going to help me out in concocting my latest elixir.  I'll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.", completion = "Superb collecting, <name>." }
WordHunterWoW_QuestEN[502] = { title = "Elixir of Pain", description = "Ah, nothing like the smell of fresh blood in the foothills!\n\nNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.\n\nTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"treat.\"", objectives = "Feed the Elixir of Pain to Stanley.", progress = "Woof?", completion = "You pour some of the elixir into your hand and hold it before Stanley's mouth." }
WordHunterWoW_QuestEN[503] = { title = "Gol'dir", description = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.", objectives = "Free Gol'dir then return to Krusk in Tarren Mill.", progress = "Give me the key, <class>, I will undo the lock myself.", completion = "Thank you, <name>. I led the expedition from Durotar under the Warchief's orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...\n\nWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now." }
WordHunterWoW_QuestEN[504] = { title = "Crushridge Warmongers", description = "Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses...\n\nGo into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.", objectives = "Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.", completion = "Very good.  Here is your reward.\n\nAnd when you were hunting those Warmongers, how did Alterac city look?  It's in bad shape I would guess.  Ogres are not known for their cleanliness.\n\nThankfully, your efforts will help keep them away from Southshore." }
WordHunterWoW_QuestEN[505] = { title = "Syndicate Assassins", description = "I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac.\n\nThe Syndicate has a camps in Sofera's Naze and Corahn's Dagger, north and west of the Horde-occupied Tarren Mill.  Slay the Syndicate members you find in these camps.", objectives = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.", completion = "Thank you, <name>.  Although they may still be lurking about, we hope that some of the thieves and footpads you slew were responsible for the last magistrate's death.  But even if they weren't, the Syndicate is a taint on this land and a stain on the <race> race.  \n\nTheir deaths are welcome to Southshore." }
WordHunterWoW_QuestEN[506] = { title = "Blackmoore's Legacy", description = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.", objectives = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.", completion = "The nerve of those overbearing humans! We'll show them that the orcs shall never submit to their will!\n\nThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other." }
WordHunterWoW_QuestEN[507] = { title = "Lord Aliden Perenolde", description = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, <name>, then retrieve the pendant that the Warchief desires, and return here.", objectives = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.", completion = "No, no please don't hurt me! I never meant your people any harm, he's had me against my will! Please... spare me!" }
WordHunterWoW_QuestEN[508] = { title = "Taretha's Gift", description = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...", objectives = "Return Taretha's pendant to Krusk at Tarren Mill in Hillsbrad Foothills.", progress = "You've returned, <name>. Success to report?", completion = "It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, <name>, no doubt the Warchief will be glad to hear of your success." }
WordHunterWoW_QuestEN[509] = { title = "Elixir of Agony", description = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, <name>: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.", objectives = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.", progress = "Any luck at Nethander Stead?", completion = "Ah, the horrible reek of Mudsnout Blossoms.  At least those filthy Gnolls are good for something." }
WordHunterWoW_QuestEN[510] = { title = "Foreboding Plans", description = "Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison).\n\nBut what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an \"important mission against Southshore.\"", objectives = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.", progress = "<name>, you look anxious.  Is there something you wish to tell me?", completion = "<Maleb reads the documents.>\n\nThese are very troubling, <name>.  From the information in these documents, and from the Syndicate's actions in the past, we must assume that band of cutthroats has waged war on Southshore." }
WordHunterWoW_QuestEN[511] = { title = "Encrypted Letter", description = "One of the letters on this table is encrypted and inscrutable.", objectives = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.", progress = "Yes, sir?  Do you have some business with me?", completion = "What is this?  Hold a moment...let me take a closer look.\n\n...\n\nHm, I have never before seen this form of encryption, but I must admit that my knowledge in that area is by no means complete." }
WordHunterWoW_QuestEN[512] = { title = "Noble Deaths", description = "I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized.\n\nEnter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters.\n\nWe know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears.\n\nBring me those signet rings.", objectives = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.", progress = "Have you been hunting the Syndicate?  Do you have those rings?", completion = "Stripping the Syndicate of its nobility will remove its ability to act decisively, and reduce it to nothing more than a gang of thugs.\n\nYou serve your Alliance well, <name>." }
WordHunterWoW_QuestEN[513] = { title = "Elixir of Agony", description = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.\n\nFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!\n\nHere, take this Mudsnout Composite and run it off to Master Faranell at once, <name>.", objectives = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.", progress = "Can you not see I am busy, <class>?  The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us.  And with the human threat pressing from the south, time becomes my most precious commodity.  This better be important!", completion = "Apothecary Lydon sent you?  Ah, why didn't you say so!\n\nDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.\n\nThe good chap sends Mudsnout Composite!  I know what our friend in Hillsbrad is up to now.  And I like the way he thinks.  The Dark Lady would be most impressed with the progress he is making toward the new plague." }
WordHunterWoW_QuestEN[514] = { title = "Letter to Stormpike", description = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.", objectives = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.", progress = "Dibbs from Southshore sent you, did he?  How is the old bookworm doing?", completion = "Ah, encryption!  A specialty of mine.  Let me see here..." }
WordHunterWoW_QuestEN[515] = { title = "Elixir of Agony", description = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?\n\nLet me contribute my colloid of decay to this devilish brew.\n\nIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!", objectives = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", progress = "So glad to see you back, <name>.  I was growing so terribly bored here.  Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.\n\nHow went the trip to the Undercity?  Were you fortunate enough to slaughter any humans along the way?", completion = "The excitement of this experiment has me feeling giddy!  You have been such a great help, <name>.  Together we will spread death and disease to this land!" }
WordHunterWoW_QuestEN[516] = { title = "Beren's Peril", description = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.", objectives = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.", completion = "If our scouts and agents continue to procure valuable information such as this, we shall have the Lich King's Scourge removed from our lands in no time." }
WordHunterWoW_QuestEN[517] = { title = "Elixir of Agony", description = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.\n\nHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, <name>.", objectives = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", progress = "Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air.  Makes Umpi a little nervous though.\n\nSo were you able to get a keg from the Dwarves?  I swear if I have to stare at this deadly elixir without using it on someone for another day I am going to scream.", completion = "Finally!  Now we are ready for action!" }
WordHunterWoW_QuestEN[518] = { title = "The Crown of Will", description = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.\n\nAfter softening them up, we'll proceed.\n\nUnderstood? Good. Now go.", objectives = "Kill 10 Crushridge Maulers for Melisara in Tarren Mill.", completion = "The snow blooms red with the blood of the ogres, but we cannot cease our efforts until the spirit and numbers of the Crushridge have been crushed and ground into the dirt and snow." }
WordHunterWoW_QuestEN[519] = { title = "The Crown of Will", description = "Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.\n\nBring me their heads, <name>, and then all that will remain is to remove Mug'Thol's head, crown and all.", objectives = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", progress = "I want their heads, <name>, not excuses.", completion = "...and I thought ogres smelled foul enough to begin with.\n\nWhen you bring me Mug'Thol's head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady's wishes." }
WordHunterWoW_QuestEN[520] = { title = "The Crown of Will", description = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.\n\nFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.", objectives = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", progress = "Three heads I have, a fourth I need. It will be Mug'Thol's, or it will be yours, <name>. That I promise.", completion = "You have done your duty well, <name>. Mug'Thol's head shall adorn the highest peak of the ruins of Alterac, and the Deathguard will sweep the remnants of the Crushridge into the ground." }
WordHunterWoW_QuestEN[521] = { title = "The Crown of Will", description = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, <name>, Mug'Thol's fate should be illustration enough.", objectives = "Deliver the Crown of Will to Sharlindra in the Undercity.", progress = "Yes? Do you have something to report?", completion = "So this is the relic the ogre used to duck the will of the Dark Lady...\n\nStrange that something so simple could wield so great a power. And to fall into as clumsy hands as those. Well done, <name>, I will deliver the crown to Lady Sylvanas, and see that she hears of your accomplishment." }
WordHunterWoW_QuestEN[522] = { title = "Assassin's Contract", description = "This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.", objectives = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.", progress = "You look out of breath!  Do you have something to report?", completion = "<Maleb inspects the contract.>\n\nThat explains the latest attack on Southshore.  The Syndicate must be after me, just as they were the last magistrate!" }
WordHunterWoW_QuestEN[523] = { title = "Baron's Demise", description = "The contract you recovered was signed by Baron Vardus, a noble of the former kingdom of Alterac, and one known for a cold heart and brutal practices.  I'm not surprised someone like the Baron was behind this.\n\nFind this man.  Find him, and bring him to justice.  He must be among the Syndicate haunts - perhaps at the ruins of Strahnbrad, or perhaps within the valley north of them.", objectives = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.", progress = "Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity.  I want his head!", completion = "Thank you, <name>.  My head rests a little easier, knowing that villain lost his." }
WordHunterWoW_QuestEN[524] = { title = "Elixir of Agony", description = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.\n\nI think it's time we threw those farmers a party.  Sounds like a grand ol' time!\n\nPlace this tainted keg on the rug in their room.  Plagued brew for all!", objectives = "Place the Tainted Keg on the rug for the captured farmers.", progress = "A musty smell emanates from the rug.", completion = "You rest the tainted keg on the dusty rug." }
WordHunterWoW_QuestEN[525] = { title = "Further Mysteries", description = "I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange...\n\nYou should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know.", objectives = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.", progress = "<name>.  Have you been traveling through the foothills and mountains again?  What news do you bring?", completion = "<Maleb reads the letter.>\n\nThis is translated from a letter you found in a Syndicate encampment?  This was not written by a thief, or even a noble of Alterac.\n\nIt appears The Syndicate has ties to another power, and I shudder to think what that might be." }
WordHunterWoW_QuestEN[526] = { title = "Lightforge Ingots", description = "You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!\n\nYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.Upon completion of this quest you will gain:", objectives = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands." }
WordHunterWoW_QuestEN[527] = { title = "Battle of Hillsbrad", description = "Stand at attention while addressing me, <class>.\n\nI am under direct command of Sylvanas.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.", objectives = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.", completion = "At ease, <class>.  I see you have returned from battle.  My sources tell me you performed well on the Hillsbrad front." }
WordHunterWoW_QuestEN[528] = { title = "Battle of Hillsbrad", description = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.\n\nOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.\n\nProve them wrong, <name>.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.\n\nDismissed!", objectives = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.", completion = "The grip of death is tightening around the town of Hillsbrad.  The battle goes well." }
WordHunterWoW_QuestEN[529] = { title = "Battle of Hillsbrad", description = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.\n\nYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.", objectives = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\n\nRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.", progress = "Were you able to carry out your orders, <class>?  Did you dispose of Verringtan and his assistants?  And where is that iron shipment?", completion = "Mission accomplished, <class>.  And carried out quite skillfully, I might add." }
WordHunterWoW_QuestEN[530] = { title = "A Husband's Revenge", description = "Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you.\n\nI last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.", objectives = "Kill Valdred Moray.\n\nBring his hands to Raleigh Andrean in the Undercity.", progress = "Do you have those hands, <name>?", completion = "Ah, good.  These hands killed my wife, Deliah.  Revenge for her murder was my only care, and you were the instrument of that revenge.\n\nHere, take the ring you returned earlier.  Deliah has been dead to me for so long, her ring is a bauble I no longer care to keep.  Instead, I will keep these hands as a remembrance of my friend's betrayal." }
WordHunterWoW_QuestEN[531] = { title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", objectives = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", progress = "Great job, <name>! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, <name>. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it." }
WordHunterWoW_QuestEN[532] = { title = "Battle of Hillsbrad", description = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.\n\nDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.", objectives = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen. Destroy the Hillsbrad Proclamation. Steal the Hillsbrad Town Registry. Report back to Darthalia in Tarren Mill afterwards.", progress = "What news have you?", completion = "News of your glories in Hillsbrad traveled fast.  You have done well, <class>." }
WordHunterWoW_QuestEN[533] = { title = "Infiltration", description = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.\n\nGo there, <name>, and bring back whatever information you can get your hands on.", objectives = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.", progress = "Have you found anything? I fear Gol'dir's prospects grow worse by the day...", completion = "Finally, we know where Gol'dir is being held. The camp in question is not too far from here, and hopefully they will not be as well prepared as they were when they captured us the first time." }
WordHunterWoW_QuestEN[535] = { title = "Valik", description = "Urrgh... Injured and dying and confronted with the enemy.\n\nNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.", objectives = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.", progress = "Did you bring me something to drink or did you just come back to finish the job?", completion = "Given my impending death, I think I can safely say that this is the sweetest tasting thing ever... Here, take this, won't do me any good when I'm dead.\n\nWell, get on with it!" }
WordHunterWoW_QuestEN[536] = { title = "Down the Coast", description = "Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night.\n\nNot to mention ol' Redpath... Wants me to take care of the murlocs. Ha! \n\nI can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.", objectives = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.", completion = "I hope this will be enough to convince Redpath that I've--ha!--been carrying out his orders and ridding Southshore of the terrible and horrible menace of the dreaded murlocs! For there could be no greater evil than the ravages of overgrown fish!" }
WordHunterWoW_QuestEN[537] = { title = "Dark Council", description = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.\n\nI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.\n\nSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.\n\nWith luck, you'll find these envoys of the Argus Wake there.", objectives = "Kill 4 Argus Shadow Mages.\n\nBring the Head of Nagaz to Magistrate Maleb in Southshore.", progress = "Did you find the envoys of The Argus Wake?", completion = "Well done, <name>.  The Argus Wake does not sound like a group we want running the Syndicate.\n\nAnd although you may have destroyed their leader here, Nagaz was merely the servant of another.  The Argus Wake might run deep through the continent of Azeroth.\n\nOr even the world." }
WordHunterWoW_QuestEN[538] = { title = "Southshore", description = "<name>.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library.\n\nThe old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can.\n\nSouthshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.", objectives = "Speak with Loremaster Dibbs in Southshore.", completion = "Ah yes, I remember Milton.  A bookworm, no doubt.  Bless him.\n\nAnd he's right.  The Ruins of Alterac still hold stores of knowledge in danger of being lost!\n\nOgres now dwell in Alterac, and they don't care much for higher learning." }
WordHunterWoW_QuestEN[539] = { title = "Battle of Hillsbrad", description = "The Hillsbrad Town Registry indicates that the Azurelode Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.\n\nEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azurelode Mine fervently.\n\nThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.", objectives = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.", completion = "The Dark Lady will be pleased when she learns that she has a new mine from which she can arm her soldiers." }
WordHunterWoW_QuestEN[540] = { title = "Preserving Knowledge", description = "Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can!\n\nEnter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.", objectives = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.", progress = "I wish I could search the ruins too, but I fear these bones wouldn't hold me during my climb up the mountains.  However, how does your hunt for knowledge progress, <name>?", completion = "Oh, you got them!  Splendid!  I must begin studying the Arm of Gri'lek immediately!" }
WordHunterWoW_QuestEN[541] = { title = "Battle of Hillsbrad", description = "Dwarves aiding the humans?  Damn those filthy little beasts.\n\nWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.\n\nThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, <class>.  Captain Ironhill, their leader, must die.", objectives = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", completion = "Your actions on the battlefield are worthy of the highest praise." }
WordHunterWoW_QuestEN[542] = { title = "Return to Milton", description = "I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.\n\nHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.", objectives = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.", progress = "<name>, you've returned!  How did your foray into Alterac go?  Did you bring anything back with you?", completion = "My oh my!  Look at these!  I can't believe they survived the ruination of Alterac.  And all those ogres too!\n\nThank you, <name>.  Thank you so much!  You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind." }
WordHunterWoW_QuestEN[543] = { title = "The Perenolde Tiara", description = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.", objectives = "Recover the Perenolde Tiara.", progress = "Salutations, <name>.  Do try to avoid stepping on my pant cuffs.  This outfit is newly tailored.", completion = "Ah, this is splendid.  This will have to be cleaned of course, but you really outdid yourself, <name>.  I will have someone prepare the tiara and place it within our collection posthaste.\n\nAs I'm sure you will agree, our gratitude is as grand as our collection." }
WordHunterWoW_QuestEN[544] = { title = "Prison Break In", description = "I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\n\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.\n\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.", objectives = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.", progress = "Did you find the thieves?  And more importantly, did you find what they stole?", completion = "You have done a great service for the Forsaken, <name>.  These artifacts have been sorely missed.\n\nAnd it is good to hear that Kegan and the other betrayers have found justice." }
WordHunterWoW_QuestEN[545] = { title = "Dalaran Patrols", description = "The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot.\n\nI don't care what the reason was.  I do care that the ruined outskirts of their city may hide valuable magical treasures.\n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently reduced.", objectives = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.", completion = "Very good.  Those ruins should now be safe enough to search, if one is careful.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[546] = { title = "Souvenirs of Death", description = "I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .\n\nWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.\n\nPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.", objectives = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.", progress = "So the lucky <name> returns?  How many humans have you slaughtered today?  Hundreds I do hope!\n\nHave you any skulls for me?", completion = "Precious skulls!  So beautiful!  I owe you as promised, <name>!" }
WordHunterWoW_QuestEN[547] = { title = "Humbert's Sword", description = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.", objectives = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.", progress = "Were you able to retrieve my sword, <name>?  High Executor Darthalia will hang me from the rafters if she discovers my folly.", completion = "You found it!\n\nAh, I feel so complete with my precious sword back in my hand.  Many thanks to you!" }
WordHunterWoW_QuestEN[549] = { title = "WANTED: Syndicate Personnel", description = "By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.\n\nA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.", objectives = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.", completion = "Excellent, <class>. At this rate, the Syndicate pest will be rid from the land in no time." }
WordHunterWoW_QuestEN[550] = { title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, <class>.", objectives = "Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.", progress = "What brings a <class> all the way to the Undercity from the battlefield?", completion = "So you are the infamous <class> who struck such a decisive blow against the Alliance forces in the Hillsbrad Foothills?  Word of your glorious exploits traveled quickly to the Undercity.\n\nYou have quite a future in the Horde's ranks if you continue to show such leadership and expertise in battle.\n\nWhile our primary threat is the Lich King's Scourge army descending from the north, the humans continue to impede our battle plans.  You, however, have shown that the humans can and will fall." }
WordHunterWoW_QuestEN[551] = { title = "The Ensorcelled Parchment", description = "This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:\n\n\n      Nagaz", objectives = "Take the Ensorcelled Parchment to Loremaster Dibbs at Southshore in Hillsbrad Foothills.", progress = "Oh.  You have something you'd like me to look at?  Some scrap of lore gathered from up in the mountains, I hope...", completion = "More encrypted notes?\n\nI wish I had the talents to decrypt all the strange bits of writing that trickle down from Alterac.  But I'm afraid I lack the knowledge." }
WordHunterWoW_QuestEN[552] = { title = "Helcular's Revenge", description = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.", objectives = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.", progress = "Have you recovered Helcular's Rod yet?  There are so many Yeti in this region, it will be very difficult to locate.  But we must have it in order to proceed.", completion = "You found it!  Most excellent, <name>!" }
WordHunterWoW_QuestEN[553] = { title = "Helcular's Revenge", description = "Here, take the Rod of Helcular. You will need it.\n\nHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.\n\nThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!", objectives = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.\n\nDrive the charged rod into Helcular's grave in Southshore.", progress = "Helcular's grave teems with a mystical energy.", completion = "A great rumbling emanates from the ground." }
WordHunterWoW_QuestEN[554] = { title = "Stormpike's Deciphering", description = "Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge.\n\nAnd when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.", objectives = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.", progress = "More interruptions?\n\nAh, this parchment is covered with a very intricate, finely woven spell.  I can untangle it, of course, but it's going to take time.  And time is very valuable to me...\n\nPerhaps I will just purchase it from you?", completion = "A wise decision.  I don't believe there is a scholar other than myself with the skills to translate this scroll.  And if its contents prove interesting, fear not.  I will send for you." }
WordHunterWoW_QuestEN[555] = { title = "Soothing Turtle Bisque", description = "If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind!\n\nTake my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north, I'll whip some up!", objectives = "Bring 10 pieces of Turtle Meat to Chef Jessen in Southshore.", progress = "Any luck finding the ingredients?  I'll tell you, this territory isn't the peaceful place it once was.  Ah, if only this unrest never occurred. . .", completion = "Everyone will be so pleased: Chef Jessen's Soothing Turtle Bisque is served once again!" }
WordHunterWoW_QuestEN[556] = { title = "Stone Tokens", description = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.", objectives = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.", progress = "Do you have the Worn Stone Tokens, <name>?  The Magus is eager to unlock their secrets.", completion = "These will do nicely.  Although it looks like their magic is faded, it would be best if the Magus' initial experiments were on inert specimens such as these.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[557] = { title = "Bracers of Binding", description = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.", objectives = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.", progress = "Hello, <name>.  Elementals are tough quarry, but I know you're up to the task.  Do you have those bracers of binding?", completion = "You found them.  I trust the elementals from which you removed these bracers were amenable?\n\nHm...death has not only stopped my heart, but robbed me of my comedic timing, it seems.\n\nWell thank you, <name>.  You serve the Magus, and hence the Dark Lady, well." }
WordHunterWoW_QuestEN[558] = { title = "Jaina's Autograph", description = "They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too!\n\nDo you know Jaina, <name>?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy!\n\nPlease?Upon completion of this quest you will gain:", objectives = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward." }
WordHunterWoW_QuestEN[559] = { title = "Farren's Proof", description = "Would you believe it, <name>? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.", objectives = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.", progress = "Did you get those heads for me, <name>?", completion = "Oh for the Love of the Light... they're dripping on the ground.\n\nCan't stand touching those things, myself. Fish are all well and good, but when they grow legs and start walking around... Haven't eaten a fish in weeks, let me tell you, and in Southshore, that means you aren't eating much." }
WordHunterWoW_QuestEN[560] = { title = "Farren's Proof", description = "You know, <name>, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?", objectives = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.", progress = "Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?", completion = "Farren's errand boy, are you?\n\nIf you assisted Farren in procuring these heads, then thank you. Southshore needs hard workers and effort to maintain its protection." }
WordHunterWoW_QuestEN[561] = { title = "Farren's Proof", description = "Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.", objectives = "Speak with Lieutenant Farren Orinelle in Southshore.Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.", completion = "The naga, eh? Redpath must have just received the same information as me... Ha! He'll not receive a promotion from my toil. Let me explain." }
WordHunterWoW_QuestEN[562] = { title = "Stormwind Ho!", description = "My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard.\n\nThere's just one small problem... I can't handle the naga, <name>. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, <name>!", objectives = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.", completion = "With the naga put down in Southshore, I'll be a shoe-in to be reassigned. I'll get to see Stormwind again... get away from this Light-forsaken port." }
WordHunterWoW_QuestEN[563] = { title = "Reassignment", description = "It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.", objectives = "Deliver Farren's report to Major Samuelson in Stormwind Keep.", progress = "Greetings, citizen. May the Stormwind city guard be of assistance?", completion = "What's this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month." }
WordHunterWoW_QuestEN[564] = { title = "Costly Menace", description = "Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts.\n\nBut I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult!\n\nYou fancy yourself a hero?  Go and do somethin' about it then!", objectives = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.", completion = "Ain't that great news!  Should-a gone and found me a regular ol' war hero from day one to take care of them beasts.  You'd-a made your pappy proud, <name>." }
WordHunterWoW_QuestEN[565] = { title = "Bartolo's Yeti Fur Cloak", description = "I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!\n\nTravel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little <race>?  \"Bartolo, there is no finer cloak!\"  Yes, yes!  That, I have heard before.\n\nBartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!", objectives = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.", progress = "So you have returned to the great Bartolo.  Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak?  Or maybe you just enjoy basking in the greatness of me, Bartolo!", completion = "Now it is time for the great Bartolo to work his magic!  I require no wizard's staff, no mage's rod.  For I, the great Bartolo, work magic with a mere needle and thread!" }
WordHunterWoW_QuestEN[566] = { title = "WANTED: Baron Vardus", description = "By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate.\n\nHe was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill.\n\nHe is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.", objectives = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.", progress = "Ah, <name>. Perhaps you've come to collect the bounty on the head of Baron Vardus?", completion = "Productive work you do, <name>. With Baron Vardus dead, the number of Syndicate leaders grows smaller. Their resistance and irritation will be short-lived." }
WordHunterWoW_QuestEN[567] = { title = "Dangerous!", description = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.", objectives = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.", completion = "You are quite the bounty hunter, <class>.  Well done." }
WordHunterWoW_QuestEN[568] = { title = "The Defense of Grom'gol", description = "Throm'ka, <class>!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.", objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.", completion = "Your duty was performed with honor, <class>." }
WordHunterWoW_QuestEN[569] = { title = "The Defense of Grom'gol", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", objectives = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.", completion = "Well done.  You have served the Warchief with honor." }
WordHunterWoW_QuestEN[570] = { title = "Mok'thardin's Enchantment", description = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave <class>, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.", objectives = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.", progress = "What news do you bring?", completion = "Your knowledge of the jungle is strong, <name>.  These specimens will be perfect.  I will thank the spirits for sacrificing such fine beasts for the cause of the Horde." }
WordHunterWoW_QuestEN[571] = { title = "Mok'thardin's Enchantment", description = "What I need from you now will be very difficult to obtain.\n\nTo hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work.\n\nYou will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay.\n\nThe sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.", objectives = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.", progress = "Has fortune been on your side, <name>?  Were you able to obtain an aged gorilla sinew?", completion = "A most ideal sinew, <name>.  Your efforts will pay off soon." }
WordHunterWoW_QuestEN[572] = { title = "Mok'thardin's Enchantment", description = "The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.\n\nBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.", objectives = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.", progress = "Did your gathering efforts prove fruitful?", completion = "Most excellent.  I will prepare these at once." }
WordHunterWoW_QuestEN[573] = { title = "Mok'thardin's Enchantment", description = "There is but one final reagent needed to complete the enchantment.\n\nIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.\n\nMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.", objectives = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water. He also wants you to kill 10 Naga Explorers.", progress = "I am almost ready to complete the enchantment.  Have you performed my bidding?", completion = "With this Holy Spring Water the ceremonial choker is ready for enchantment.\n\nWear this with pride, <name>, in the name of the Warchief and in defense of the mighty Horde." }
WordHunterWoW_QuestEN[574] = { title = "Special Forces", description = "Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, <name>.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.", objectives = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.", completion = "<name>.  Sergeant Yohwa trusted your abilities, and I trust her.  The defeat you brought to Kurzen's forces is almost too much to hope for.  I had feared we rebels were alone, and alone we could never stand up against the Colonel's brilliance.\n\nPerhaps hope of our survival yet remains." }
WordHunterWoW_QuestEN[575] = { title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.", objectives = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.", progress = "My equipment is all ready to go, <name>, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?" }
WordHunterWoW_QuestEN[576] = { title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", objectives = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n<name> ho!  Blimey, I can see!!" }
WordHunterWoW_QuestEN[577] = { title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", objectives = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, <name>. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside." }
WordHunterWoW_QuestEN[578] = { title = "The Stone of the Tides", description = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?", objectives = "Find the haunted island for Baron Revilgaz in Booty Bay.", completion = "So the stories were true! Incredible!\n\nHowever, we will need to figure out a way to defeat the curse of the Stone of the Tides, if we are to retrieve it. The curse is magical business, we'll need one of those wizards to help us out." }
WordHunterWoW_QuestEN[579] = { title = "Stormwind Library", description = "", objectives = "" }
WordHunterWoW_QuestEN[580] = { title = "Whiskey Slim's Lost Grog", description = "We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!", objectives = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.", progress = "Sink me!  I'm almost outta booze here!  Cap'n is goin' to weigh anchor and Ol' Slim will be caught dry as the Tanaris Desert.  And once he discovers his port is missing. . . blimey!", completion = "Shiver me timbers!  Ye found the Cap'n's grog!\n\nI owe ye big time, friend.\n\nSeems like a storm is a brewin' outside.  Maybe I'll just keep warm with one o' these here bottles while we wait for it to pass...." }
WordHunterWoW_QuestEN[581] = { title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", objectives = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", progress = "<class>.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, <name>.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them." }
WordHunterWoW_QuestEN[582] = { title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, <name>.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.", objectives = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", progress = "<name>.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, <name>.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe." }
WordHunterWoW_QuestEN[583] = { title = "Welcome to the Jungle", description = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, {class}.\n\nGo and speak with him.  He's a chip off the old block, so perhaps he can give you some hunting pointers.", objectives = "Speak with Hemet Nesingwary Jr.", completion = "Jolly nice to make your acquaintance, <name>.  Haven't seen a <class> around these parts for some time.\n\nI've one purpose in being here: to hunt a great and elusive beast.  Seeing that you're a hero of sorts I am willing to let you take part in the hunt, but you must first prove yourself.\n\nI shall teach the ways of raptor killing to you.  Ajeck will train you with tiger hunting.  And Sir Erlgadin is a master of panther tracking.\n\nProve your skill and I'll let you in on the big hunt." }
WordHunterWoW_QuestEN[584] = { title = "Bloodscalp Clan Heads", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!\n\nBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.\n\nThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.", objectives = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", progress = "The greenish broth within the cauldron bubbles.", completion = "You place the heads of Gan'zulah and Nezzliok within the cauldron..." }
WordHunterWoW_QuestEN[585] = { title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.", objectives = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.", progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with three fine servants!\n\nYou are a credit to your <race> clan, and you have appeased me." }
WordHunterWoW_QuestEN[586] = { title = "Speaking with Gan'zulah", description = "<The head of Gan'zulah speaks.>\n\nCurse you!  And curse your ancestors!!\n\nOnly blood and revenge can cool my rage, so if that is your wish, then... do this:\n\nThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!\n\nMay he tear off your limbs and leave you to rot and be eaten by carrion.", objectives = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\n\nBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.", progress = "Although my own flesh boils off my skull, I can still smell your fear.\n\nHah!  You will never complete my task...", completion = "I do not want to believe it, but I cannot deny what you have done.  And my rage eases, now that Ana'thek is defeated.  \n\nYour might will drive you to great deeds, <name>.  But one day...I will see you in the Nether and we will again match strength.\n\nI will be waiting." }
WordHunterWoW_QuestEN[587] = { title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless <class> like you could convince 'em to share the goods, eh?", objectives = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.", progress = "Any luck finding the goods, matey?", completion = "Good show, <name>!  And just before I need to ship out too!  Can't thank you enough, old friend." }
WordHunterWoW_QuestEN[588] = { title = "The Fate of Yenniku", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, <class>.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.", objectives = "Speak with Kin'weelay.<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast. Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, <class>.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation. But that, I doubt.", completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nBut still, it is hope." }
WordHunterWoW_QuestEN[589] = { title = "The Singing Crystals", description = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\n\nI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.", objectives = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.", progress = "Do you have the shards, <name>?  They are needed for my final ritual, after we have the Mind's Eye.", completion = "You have done well, <name>.  These shards are well formed.  Already I hear them sing to me.\n\nAnd while you were gone, I spoke with the spirits of the jungle.  I know where the Mind's Eye rests...\n\n...And who guards it." }
WordHunterWoW_QuestEN[590] = { title = "A Rogue's Deal", description = "What?\n\nWhat?!\n\nYou want money? I don't owe you any money.\n\nLetter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...", objectives = "Defeat Calvin Montague in Deathknell.", completion = "Incredible! What skill!\n\nThought you'd be easy prey, <name>. Got me good, you did.\n\nHere's the coin I promised... not as much as I said it'd be, but that's on a count o' me lying to ya in the first place." }
WordHunterWoW_QuestEN[591] = { title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", objectives = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.", progress = "Greetings, <name>.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, <name>!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time.  Now, I must perform a ritual to bend the Mind's Eye to our needs..." }
WordHunterWoW_QuestEN[592] = { title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nThen, bring the gem to Nimboya.\n\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.", objectives = "Bring the Filled Soul Gem to Nimboya.", progress = "<name>.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.\n\nOur tribe will remember your name in songs, <name>, and we will etch your tale in stone so that it will live forever." }
WordHunterWoW_QuestEN[593] = { title = "Filling the Soul Gem", description = "", objectives = "Yenniku stands stunned before you, his mind in another place...", progress = "Yenniku stands stunned before you, his mind in another place...", completion = "You place the Soul Gem upon his forehead.  He shudders as his soul is sucked in, leaving his body, a mindless husk, behind." }
WordHunterWoW_QuestEN[594] = { title = "Message in a Bottle", description = "The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.", objectives = "Find the author of the message in a bottle.The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.", completion = "Have you come to free me?" }
WordHunterWoW_QuestEN[595] = { title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving <race> <class> is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nOur ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn.\n\nAll the boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", objectives = "First Mate Crazz wants you to check the cove north of Booty Bay.", completion = "On top of the barrel, you discover a map with some hastily written text on it along with some coins." }
WordHunterWoW_QuestEN[596] = { title = "Bloody Bone Necklaces", description = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.", objectives = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.", progress = "The Bloodscalps will one day be crushed by the Darkspears!  Do you have the necklaces of our doomed foe?", completion = "Ah, very good.  I will boil these, and leech them, and the spirits of their owners will weaken as I render their necklaces to paste!\n\nHere, <name>.  This will repay my debt to you." }
WordHunterWoW_QuestEN[597] = { title = "The Bloodsail Buccaneers", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them.\"", objectives = "Report your findings to First Mate Crazz in Booty Bay.", completion = "Sure, I remember you, <class>.  Back from scouting I see...." }
WordHunterWoW_QuestEN[598] = { title = "Split Bone Necklace", description = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.", objectives = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.", progress = "The Skullsplitters will curse the day they brought us to war!  Is your task complete?", completion = "Your strength is great to have gained these necklaces, <name>.  The Skullsplitters fall to you like young saplings stomped to earth by a Basilisk!\n\nYour deeds are a boon to us." }
WordHunterWoW_QuestEN[599] = { title = "The Bloodsail Buccaneers", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere....", objectives = "Report the planned Bloodsail attack to Fleet Master Seahorn.", completion = "Bloodsail Buccaneers attacking Booty Bay?  They might as well throw themselves off the Overlook Cliffs.  Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service.  The Blackwater Raiders thank you." }
WordHunterWoW_QuestEN[600] = { title = "Venture Company Mining", description = "The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me!\n\nThe Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills.\n\nTake their crystals from them, and show them they don't have the run of the jungle.\n\nAnd... um... bring me those crystals as proof!", objectives = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.\n\nThank you, <name>.  You've done a good deed this day." }
WordHunterWoW_QuestEN[601] = { title = "Water Elementals", description = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.", objectives = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", progress = "Have you had any luck, <name>?", completion = "Hm, I haven't the eye to examine these bracers to see if any of them will be of any use, but I'm sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.\n\nAfter all, I can't very well leave Booty Bay just to chat with those tiresome old mages.\n\nNot that I'm worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it." }
WordHunterWoW_QuestEN[602] = { title = "Magical Analysis", description = "From what I've heard, the mages of Dalaran have succeeded in rebuilding their magical city and moving it to Northrend, leaving behind a massive crater.  Some mages remained here though, who should spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver.  I've dealt with him before, and his knowledge is vast.", objectives = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran Crater.", progress = "If you wouldn't mind, I am rather busy right now.", completion = "The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.\n\nAt least one of these bracers appears to have some magical residue I can analyze.\n\nLet's see what I can see..." }
WordHunterWoW_QuestEN[603] = { title = "Ansirem's Key", description = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.", objectives = "Talk to Catelyn in Booty Bay.", completion = "My dagger? What are you, some sort of comedian?\n\nWhat? Do you just want me to repeat the story of how I've gone from the best knife fighter in Booty Bay to the laughing stock of piratedom!\n\nI lost a knife fight to one of the Bloodsail Buccaneers--bunch of right fiends they are!--and he took my blade as spoils.\n\nIt's not as though I can get by as a knife fighter with insults and a sharp tongue alone..." }
WordHunterWoW_QuestEN[604] = { title = "The Bloodsail Buccaneers", description = "Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.", objectives = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.", progress = "Ahoy, <name>.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, <name>.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape...." }
WordHunterWoW_QuestEN[605] = { title = "Singing Blue Shards", description = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.", objectives = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.", progress = "Do you have those shards yet?  I'll give you a decent cut from the profits!", completion = "Aha!  These will do nicely, <name>.  Yes, quite nicely!\n\nHere is your cut, and...it was a pleasure doing business with you." }
WordHunterWoW_QuestEN[606] = { title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", objectives = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?" }
WordHunterWoW_QuestEN[607] = { title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", objectives = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", progress = "Here here, <name>.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, <name>.  Now it's your turn to get paid..." }
WordHunterWoW_QuestEN[608] = { title = "The Bloodsail Buccaneers", description = "Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  <name>, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....", objectives = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.", completion = "Ah, what a great day for the Blackwater Raiders!  Three cheers to you, <name>!" }
WordHunterWoW_QuestEN[609] = { title = "Voodoo Dues", description = "My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.", objectives = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.", progress = "<name>, did you find those three dogs?  Did you collect their valuables?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, <name>!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with." }
WordHunterWoW_QuestEN[610] = { title = "\"Pretty Boy\" Duncan", description = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.", objectives = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.", progress = "I'd never been beat before, you know, <name>? Sure I'd been cut, can't get in a knife fight without that, but he just smacked me on the side of the head, blacked me out. When I came to my blade was gone.\n\nAs much as my nickname might indicate, I still need a knife to fight, and for me, it has to be that one.", completion = "You beat Duncan? I guess you aren't as wet behind the ears as you looked at first glance.\n\nI suppose that also means I shouldn't challenge you to a fight any time soon!" }
WordHunterWoW_QuestEN[611] = { title = "The Curse of the Tides", description = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!", objectives = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.", progress = "Have you retrieved the Stone of the Tides for me, <name>? I've already cleared out a space and purchased a fine stand for it.", completion = "Amazing! The Stone of Tides! It shall have a place of prominence in my collection of ancient troll artifacts. Did you see how it almost seems as though a tide is trapped within its surface? Magnificent!" }
WordHunterWoW_QuestEN[613] = { title = "Cracking Maury's Foot", description = "Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one...", objectives = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.", progress = "Ahoy, <name>!  Have you yet found Maury's Key?", completion = "You found it!  Thanks a million, <name>.  You've been a big help to me!\n\nHere you go - you earned this!" }
WordHunterWoW_QuestEN[614] = { title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", progress = "Ahoy, <name>! Did you find Gorlash? That chest was my favorite, and it has a hidden compartment that held my greatest treasures!", completion = "You found it! Oh happy day, this is! Thank you, <name>. Getting back my chest cools some of the fire in me.\n\nBut my revenge isn't complete..." }
WordHunterWoW_QuestEN[615] = { title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.Upon completion of this quest you will gain:", objectives = "Speak with Sprogger.After I lost my first ship to those giants, I bought another. Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains. I found them, but...they beat me. They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger. He was my cook on the Smotts' Revenge, and survived the last attack. He can help you find the giant.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[616] = { title = "The Haunted Isle", description = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?", objectives = "Speak with Baron Revilgaz in Booty Bay.", completion = "Interesting. Some time ago, I seem to remember reading a book once that suggested...\n\nAh, of course, a troll legend it was. If what Krazek reports is true, perhaps I will soon be able to add the Stone of the Tides to my collection of ancient artifacts and relics." }
WordHunterWoW_QuestEN[617] = { title = "Akiris by the Bundle", description = "You looking fer work, <name>? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.", objectives = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.", progress = "If ya got no business with me, then move along, <name>.", completion = "Well done, <name>. 10 stalks of akiris reed wasn't too much a challenge after all, huh? No offense to the naga, but hey, everybody's gotta make a living." }
WordHunterWoW_QuestEN[618] = { title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!You will receive:", objectives = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn." }
WordHunterWoW_QuestEN[619] = { title = "Enticing Negolash", description = "", objectives = "This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:\n\n\"Smotts' Revenge\"", progress = "This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:\n\n\"Smotts' Revenge\"", completion = "You pile food and drink upon the raft..." }
WordHunterWoW_QuestEN[620] = { title = "The Monogrammed Sash", description = "This fine sash has the letters \"HS\" embroidered along its hem.Upon completion of this quest you will gain:", objectives = "Return the Monogrammed Sash to its owner." }
WordHunterWoW_QuestEN[621] = { title = "Zanzil's Secret", description = "Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.", objectives = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", progress = "Do you have the samples of Zanzil's Mixture??", completion = "Ah, very good!  Here is your pay.\n\nAnd here is a little something extra... for your discretion." }
WordHunterWoW_QuestEN[622] = { title = "Return to Corporal Kaleb", description = "While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", objectives = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.", progress = "Hello, <name>.  Did you make it to Booty Bay?  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, <name>.\n\nI hope you were okay in Booty Bay.  That place can get pretty rough, and... I heard rumors that the goblins will sometimes drag drunk sailors to their slave boats and take them to who-knows-where... to do who-knows-what..." }
WordHunterWoW_QuestEN[623] = { title = "Akiris by the Bundle", description = "<name>, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.", objectives = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.", progress = "Yeah?", completion = "What?! I got a lot better things to do then talk to the likes of you, <class>. Make it worth my while or get outta my face.\n\nHuh? Bloads sent ya, huh? Well, whaddaya got for me?\n\n\n\nNot bad, not bad at all. Another bundle will make my client quite happy.\n\nI suppose yer next question's gonna be about money, huh, <class>? Of course it is!\n\nHere, take this coin and some advice: get off my docks." }
WordHunterWoW_QuestEN[624] = { title = "Cortello's Riddle", description = "There is an ornate, well-traveled bridge\nEast of Deadwind and south of Redridge\nUnderneath there waits something for you\nSome call it a hint, others a clue\nThere it will lie for endless tomorrows\nBiding its time in the Swamp of Sorrows", objectives = "Solve the riddle!", completion = "The soggy parchment contains the next clue...." }
WordHunterWoW_QuestEN[625] = { title = "Cortello's Riddle", description = "A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest", objectives = "Solve the riddle!A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest", completion = "You find a musty scroll." }
WordHunterWoW_QuestEN[626] = { title = "Cortello's Riddle", description = "To Lordaeron! The great land of turmoil\nWhere brave soldiers with death do toil\nFind your way through the great unrest\nThere you will find the end to this quest\nAlong the coast of the Hinterlands, at the base of the great falls\nUnderneath the water there does your treasure call!", objectives = "Solve the riddle!", completion = "You open the chest to discover...." }
WordHunterWoW_QuestEN[627] = { title = "Favor for Krazek", description = "There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!", objectives = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.", progress = "Hello, <name>.  Did you have luck getting the bloodstone?", completion = "Ah, splendid!  That was a big favor you did for me.\n\nHere is your payment..." }
WordHunterWoW_QuestEN[628] = { title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.", objectives = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.", progress = "I read somewhere that the saltwater crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder saltwater crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!" }
WordHunterWoW_QuestEN[629] = { title = "The Vile Reef", description = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.", objectives = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", progress = "I await the Tablet Shard, <name>.", completion = "This is good.  When I return to Orgrimmar I will place this shard in a sacred place.  It will remind us of the might and honor of Gri'lek.\n\nThank you, <name>.  Your deeds mark a growing friendship with the Darkspear tribe." }
WordHunterWoW_QuestEN[630] = { title = "Message in a Bottle", description = "<name>, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", objectives = "Slay King Mukla and return to Princess Poobah with the Key to free her.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "<name>, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown." }
WordHunterWoW_QuestEN[631] = { title = "The Thandol Span", description = "A tremendous explosion roared through the hills.  'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago.  We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...", objectives = "Rhag Garmason wants you to locate Ol' Rustlocke.A tremendous explosion roared through the hills. 'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span. Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight. Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago. We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...", completion = "You search the tiny, dwarven corpse.  Engraved into the helmet you can clearly read: Ebenezer Rustlocke." }
WordHunterWoW_QuestEN[632] = { title = "The Thandol Span", description = "It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.\n\nReport the grim news to Rhag Garmason and show him what you found.", objectives = "Report back to Rhag Garmason at Dun Modir in Wetlands and show him the parchment you found on Rustlocke's corpse.", progress = "Any sign of Ol' Rustlocke, <name>?", completion = "Oh my, the news is grave...." }
WordHunterWoW_QuestEN[633] = { title = "The Thandol Span", description = "Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.\n\nWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.\n\nIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, <name>!  Return to me when your mission is complete.\n\nYou're our only hope.", objectives = "Destroy the cache of explosives.", completion = "The remaining bridge is saved!  You have done a great service to King Magni and the people of Khaz Modan.\n\nNow if we can only hold out long enough for reinforcements to show..." }
WordHunterWoW_QuestEN[634] = { title = "Plea To The Alliance", description = "I ask of you one more small favor, <class>.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.", objectives = "Seek out Captain Nials at Refuge Pointe in Arathi Highlands.I ask of you one more small favor, <class>. We await the reserves of Ironforge. However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials. Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.", completion = "My condolences go out to Longbraid and his brave soldiers.  The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.\n\nBut Stromgarde has fallen!  Hence our presence here at Refuge Pointe.  We are faced with retaking our own great city.\n\nHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own..." }
WordHunterWoW_QuestEN[635] = { title = "Crystal in the Mountains", description = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.", objectives = "Find the crystal from your vision.\n\nProvided item:", completion = "This crystal pulses, as if a living force is trapped within it." }
WordHunterWoW_QuestEN[637] = { title = "Sully Balloo's Letter", description = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.\n\nThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"", objectives = "Deliver Sully Balloo's Letter to Sara Balloo.", progress = "You look as though you have traveled a great distance and seen much turmoil in your time, <class>.  These times we live in are trying on the soul.  What news do you bring to me now?", completion = "You say you saw my Sully pinned beneath the icy waters?  Say it isn't so!\n\nLet me read what he wrote...." }
WordHunterWoW_QuestEN[638] = { title = "Trollbane", description = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.", objectives = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.", completion = "How you doing, <class>? The task set before us by Vol'jin will be a difficult one, and any assistance you might provide will be appreciated and necessary." }
WordHunterWoW_QuestEN[639] = { title = "Sigil of Strom", description = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.", objectives = "Get the Sigil of Strom for Zengu in Hammerfall.", progress = "Have you located the first sigil yet? It is most likely carried on the person of one of the Syndicate agents in Stromgarde.", completion = "Excellent, mon. That's a good start to collecting the sigils we'll need to remove Trol'kalar from Trollbane's tomb." }
WordHunterWoW_QuestEN[640] = { title = "The Broken Sigil", description = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into five pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.", objectives = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", progress = "Throm'ka, <class>. Zengu informed me that you required my assistance?", completion = "Ah, you need me to reconstruct this sigil? It shouldn't be too difficult... all the pieces seem to be here and the magical structure will be easy to reform.\n\nYou might want to close your eyes." }
WordHunterWoW_QuestEN[641] = { title = "Sigil of Thoradin", description = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.", objectives = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", progress = "<name>! Do you have the second sigil?", completion = "We're halfway to being able to remove Trol'kalar from Trollbane's tomb. We are not exactly sure where the third sigil is, as its holders seem to move around Arathi quite a bit, but I have faith that you'll be able to find it." }
WordHunterWoW_QuestEN[642] = { title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, <name>, aid me!", objectives = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free..." }
WordHunterWoW_QuestEN[643] = { title = "Sigil of Arathor", description = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?\n\nWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.", objectives = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.", progress = "Valorcall will not be easy to track down, <name>. Mounted on horseback, he can cover ground quickly. Nonetheless, we must have his sigil.", completion = "Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol'kalar for ourselves." }
WordHunterWoW_QuestEN[644] = { title = "Sigil of Trollbane", description = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.", objectives = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.", progress = "You've returned, <name>. Is the line of Ignaeus Trollbane broken?", completion = "Quite a day this is, <class>. The blood of Trollbane will no longer haunt my people, and the sigils needed to take Trol'kalar are in our possession. Soon, very soon, we will strike against the hated trolls of Zul'Gurub." }
WordHunterWoW_QuestEN[645] = { title = "Trol'kalar", description = "What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.\n\nTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.", objectives = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.", progress = "Etchings in the stone upon the face of the tomb of Trollbane match the glowing lines of the Sigil of Ignaeus...", completion = "Matching the lines on the face of Trollbane's tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol'kalar is released from the stone hands' grip." }
WordHunterWoW_QuestEN[646] = { title = "Trol'kalar", description = "The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.", objectives = "Deliver Trol'kalar to Zengu in Hammerfall.", progress = "<name>! Have you taken the sword?", completion = "For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul'Gurub will be no more.\n\nYour assistance has been great, <name>, and the Darkspear trolls are indebted to you.\n\nI will be sure that the sword is delivered to Nimboya at Grom'gol." }
WordHunterWoW_QuestEN[647] = { title = "MacKreel's Moonshine", description = "Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.\n\nThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.\n\nOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.\n\nBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!", objectives = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.", progress = "What's the good word, <race>?", completion = "Ah, nothing like Foggy MacKreel's Moonshine to warm you up on a brisk day!  And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend!  Many thanks indeed!" }
WordHunterWoW_QuestEN[648] = { title = "Rescue OOX-17/TN!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, near the Caverns of Time!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-17/TN to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-17/TN!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!\n\nPlease, take your choice of any of these items I have.  Hopefully, you will make good use of one of them.  Thank you again for your generous assistance, my robots and I are in your debt!" }
WordHunterWoW_QuestEN[649] = { title = "Ripple Recovery", description = "I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple!\n\nIt's a drink, you dummy.\n\nAn abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.", objectives = "Talk to Malton Droffers in Orgrimmar.", completion = "Oh yeah, about the ripple dad wants!  He wants to sell the ripple to a tavern here in Orgrimmar, but we'll get more money if it is in its original packaging.  I know someone who can do that, and he's in the Hinterlands where the ripple is.  But he's, um, a high elf.\n\nWell, he's a good high elf, as he's not a part of the Alliance.  Well, he's not so much a good high elf as he is a drunken high elf.  He loves, and I mean LOVES the hooch." }
WordHunterWoW_QuestEN[650] = { title = "Ripple Recovery", description = "The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here!\n\nGilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.", objectives = "Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands.", completion = "Ah, so you know Malton?  He is an old drinking companion of mine.  You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol.  Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.\n\nAlas, something tells me that your visit here is not to learn of alcohol's redeeming values, now is it." }
WordHunterWoW_QuestEN[651] = { title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", objectives = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "<Myzrael speaks through the stone.>\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble <class>, <name>.  My rescuer!" }
WordHunterWoW_QuestEN[652] = { title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n<name>, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", objectives = "Find and kill Fozruk. Bring the Rod of Order to the Keystone in the Arathi Highlands.", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you..." }
WordHunterWoW_QuestEN[653] = { title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, <name>.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.\n\nSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.", objectives = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", completion = "The Lady told me of your coming, <class>.  You are welcome in my abode for you, like I, serve a higher cause." }
WordHunterWoW_QuestEN[654] = { title = "Tanaris Field Sampling", description = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.\n\nI will have it shipped immediately.\n\nAccording to Chief Engineer Bilgewhizzle, you now have some time to collect the data you need in the Tanaris desert.\n\nReturn to him when you have completed the task.", objectives = "Acquire untested samples for 8 basilisks, 8 hyenas, and 8 scorpions. Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.", progress = "Well, did you get everything you needed?", completion = "All right then, it will take me just a second to remove the power source.  After that, you can do with it whatever you like now without having to worry about losing the data inside." }
WordHunterWoW_QuestEN[655] = { title = "Hammerfall", description = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...", objectives = "Speak with Tor'gan in Hammerfall.It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...", completion = "Ah, Gor'mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.\n\nGor'mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall." }
WordHunterWoW_QuestEN[656] = { title = "Summoning the Princess", description = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??\n\nCrazy logic, eh?\n\nTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.\n\nDo that, and she will again be trapped.", objectives = "Go to the Shards of Myzrael, summon her and defeat her.\n\nGather her Eldritch Shackles and bind them to the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface." }
WordHunterWoW_QuestEN[657] = { title = "Hints of a New Plague?", description = "<Quae begins to go through the folder.>\n\nThis IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue.\n\nWe had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.", objectives = "Speak to Kinelory near Go'Shek Farm in Arathi Highlands.", completion = "If it brings Phin peace, I'll destroy every single one of the Forsaken personally. He's done so much for us since the plague. We never thought we'd find friends or family again.\n\nWhen you're prepared, come let me know. We'll get started right away." }
WordHunterWoW_QuestEN[658] = { title = "Hints of a New Plague?", description = "So, Phin sent you to check on us? Not surprised--he worries too much.\n\nWe've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago.\n\nShe talks a lot, but I can always trust her senses when we're in dangerous areas.\n\nYou wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsbrad.", objectives = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.", progress = "We appreciate your help in looking for that courier, <name>.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Excellent! \n\nLet's see what this is about..." }
WordHunterWoW_QuestEN[659] = { title = "Hints of a New Plague?", description = "Hail, and well met, <name>. I lead a group of adventurers investigating odd happenings in this area.\n\nMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.\n\nI believe the undead are involved, and we're looking for signs to prove as much.\n\nTwo of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned.", objectives = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.", completion = "Try and stay as quiet as possible, traveler.\n\nOrcs don't take too well to being spied on, and there is more to this farm than meets the eye." }
WordHunterWoW_QuestEN[660] = { title = "Hints of a New Plague?", description = "All right, <name>. I'm ready if you are.\n\nShall we?", objectives = "Protect Kinelory until she returns to Quae.", completion = "You've done a great service for us, <name>. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy." }
WordHunterWoW_QuestEN[661] = { title = "Hints of a New Plague?", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?", objectives = "Find Phin Odelic at Southshore in Hillsbrad Foothills.I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?", completion = "So, the two troublemakers are all right after all? Haha, I'm glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.\n\nBut... it's more important I thank you properly for your help. Here. Take this along with my group's thanks.\n\nWith any luck, we'll figure out what the Forsaken are up to, and put an end to it." }
WordHunterWoW_QuestEN[662] = { title = "Deep Sea Salvage", description = "O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!\n\nThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.\n\nWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!", objectives = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.", progress = "How goes the search and recovery mission, <name>?  We really need to get those Logs and Charts back from the Maiden's Folly and Spirit of Silverpine.\n\nIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.\n\nThat is if we ever get out of this mess...", completion = "Knowing this information is secure will bring some ease to the command in Booty Bay.  Well done, <name>." }
WordHunterWoW_QuestEN[663] = { title = "Land Ho!", description = "Lolo sees a tiny <race>! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.", objectives = "Talk to Captain O'Breen at Faldir's Cove in Arathi Highlands.", completion = "Ahoy, matey.\n\n'Twas a horrible mess. Seahorn will have my ship if he finds out what went down.\n\nOne of the Professor's contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden's Folly to follow suit.\n\nThen the sea rumbled. The tides lowered and the two ships crashed into the reef.\n\nIt's not just a reef. Something's down there....\n\nHelp my crew out and you'll be rewarded handsomely." }
WordHunterWoW_QuestEN[664] = { title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", objectives = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", completion = "Nice work out there, <name>.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace." }
WordHunterWoW_QuestEN[665] = { title = "Sunken Treasure", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", objectives = "Escort Professor Phizzlethorpe to the cave and back.", completion = "The goggles work perfectly now! Well done, <name>." }
WordHunterWoW_QuestEN[666] = { title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, <name>, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", objectives = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, <name>! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!" }
WordHunterWoW_QuestEN[667] = { title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, <name>?", objectives = "Protect Shakes O'Breen during the attack.", completion = "We survived the attack!\n\nWe could not have done it without you, <name>.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny <race>...." }
WordHunterWoW_QuestEN[668] = { title = "Sunken Treasure", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, <name>, take these to O'Breen.", objectives = "Take the Elven Gems to Captain O'Breen at Faldir's Cove in Arathi Highlands.", progress = "Ahoy, <class>.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!" }
WordHunterWoW_QuestEN[669] = { title = "Sunken Treasure", description = "Fleet Master Seahorn will want to hear about our find at once.\n\nBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.\n\nYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.", objectives = "Take the Sample Elven Gem to Fleet Master Seahorn at Booty Bay in Stranglethorn Vale.", progress = "What brings you to Booty Bay, <class>?", completion = "Ah, leave it to good old Shakes O'Breen! I knew that he was the right Captain for the mission!" }
WordHunterWoW_QuestEN[670] = { title = "Sunken Treasure", description = "Say, <name>, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.\n\nThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.\n\nCan I trust you to deliver this message safely and in confidence?", objectives = "Deliver Seahorn's Letter to Shakes O'Breen at Faldir's Cove in Arathi Highlands.", progress = "So was Seahorn impressed? I bet you his smile reached from Booty Bay to Ratchet.", completion = "Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders." }
WordHunterWoW_QuestEN[671] = { title = "Foul Magics", description = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?", objectives = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.", progress = "Once-cursed blood still runs through my veins, <name>. If someone... something is summoning demons, it must be stopped.", completion = "It will take some time for me to ascertain the true intentions of the Syndicate, but their obvious association with dark, demonic magic troubles me. I will tell you when I know more." }
WordHunterWoW_QuestEN[672] = { title = "Raising Spirits", description = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.", objectives = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.", progress = "I will create an amulet that will give Gor'mul some of the strength of the raptors. Perhaps that will awaken some flame within him...", completion = "Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet." }
WordHunterWoW_QuestEN[673] = { title = "Foul Magics", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", objectives = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, <name>. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse." }
WordHunterWoW_QuestEN[674] = { title = "Raising Spirits", description = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.", objectives = "Give the Raptor Talon Amulet to Gor'mul at Hammerfall in Arathi Highlands.", progress = "What hope is there when the hand of a coward can slay the mightiest of the mightiest? What hope, I ask you!", completion = "What is this? Polished bone. What use have I for polished bone? Will a trinket restore the Horde to its glory?" }
WordHunterWoW_QuestEN[675] = { title = "Raising Spirits", description = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...", objectives = "Speak with Tor'gan at Hammerfall in Arathi Highlands.<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...", completion = "It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor'mul to his once proud self. The amulet's power was not great enough to show him our newfound power." }
WordHunterWoW_QuestEN[676] = { title = "The Hammer May Fall", description = "Weaklings... all of them. You, <class>, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.", objectives = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.", completion = "So, you think you're strong enough to help Hammerfall? So be it.\n\nTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you're strong enough to aid us. Either way, you're here now and I am in need of more soldiers in our fight against the constant attacks.\n\nIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you're ready. There's no shortage of fighting to be had." }
WordHunterWoW_QuestEN[677] = { title = "Call to Arms", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", objectives = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed." }
WordHunterWoW_QuestEN[678] = { title = "Call to Arms", description = "Your strength is evident, <name>. Now to see how you fare against a real enemy.\n\nThe Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far.\n\nSlay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.", objectives = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.", completion = "You are as strong as a kodo, and your lust for battle does your people proud." }
WordHunterWoW_QuestEN[679] = { title = "Call to Arms", description = "The head of the beast is ready to be taken off... with great force, <name>. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty.\n\nFind and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.", objectives = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.", completion = "You do your people proud, <name>. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands." }
WordHunterWoW_QuestEN[680] = { title = "The Real Threat", description = "You serve my husband well, <class>, but he does not know why Hammerfall is under attack.\n\nOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.\n\nMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.\n\nMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.", objectives = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.", progress = "Near the Tower of Arathor--that is where you will find Or'Kalar. His death will stop the attacks on Hammerfall and protect my husband's life.\n\nI see in your eyes that you think me weak--even dishonorable--for my silence. Some day you will learn what it is to love as I do. Perhaps then you will understand a different kind of strength and honor.\n\nIn the meantime, do as I ask, and slay Or'Kalar.", completion = "You have done me a great service, <name>. Know that my husband's life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage." }
WordHunterWoW_QuestEN[681] = { title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nWe need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us.\n\nGo to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get through.", objectives = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\n\nReturn to Captain Nials at Refuge Pointe.", completion = "Very good, <name>.  With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.\n\nPerhaps our cause yet has hope." }
WordHunterWoW_QuestEN[682] = { title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", objectives = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.", progress = "Have you retrieved any Stromgarde Badges, <name>?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, <name>.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one." }
WordHunterWoW_QuestEN[683] = { title = "Sara Balloo's Plea", description = "<name>, I have but a small request to ask of you.\n\nTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.\n\nFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.", objectives = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.", progress = "So you are <name> the <class>? News of your contributions to the Alliance has traveled quite far, you know?\n\nOn what business do you come before me today?", completion = "It will take but a moment for me to peruse this letter..." }
WordHunterWoW_QuestEN[684] = { title = "Wanted! Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning Warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", objectives = "Bring Marez's head to Captain Nials at Refuge Pointe.", progress = "Greetings, <class>.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, <name>.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us." }
WordHunterWoW_QuestEN[685] = { title = "Wanted! Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", objectives = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, <name>.  I am happy to pay it." }
WordHunterWoW_QuestEN[686] = { title = "A King's Tribute", description = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten.\n\nSend word to him now, <class>. You shall be custodian of my bidding.", objectives = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten.\n\nSend word to him now, <class>. You shall be custodian of my bidding.", completion = "So King Magni Bronzebeard himself sent ye?\n\nMy, my! This must be important!" }
WordHunterWoW_QuestEN[687] = { title = "Theldurin the Lost", description = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.", objectives = "Find Theldurin the Lost.", completion = "Hello.  Hello, hello hello hello hello HELLO!\n\nI'm sorry - wait, no I'm not!  Don't be rude!\n\nOh no...that was crazy talk.\n\nBut...sometimes being crazy is my only solace." }
WordHunterWoW_QuestEN[688] = { title = "Myzrael's Allies", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, <name>.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.", objectives = "Speak with Zaruk at Hammerfall in Arathi Highlands.", completion = "Welcome, <class>.  The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss..." }
WordHunterWoW_QuestEN[689] = { title = "A King's Tribute", description = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?\n\nBah, will there ever be peace on Azeroth?\n\nNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.", objectives = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.", progress = "<name>, <name>, <name>! Tell me you have enough Alterac Granite for me to begin my masterpiece in honor of Sully Balloo.", completion = "Perfect! Better than I could have imagined!\n\nAnd I have quite an imagination you know..." }
WordHunterWoW_QuestEN[690] = { title = "Malin's Request", description = "Greetings, <name>. You have the look of an adventurer about you, and I have a task that needs some tending to.\n\nArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind.\n\nThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?", objectives = "Find Skuerto at Refuge Pointe in the Arathi Highlands.", completion = "So, Malin sent ye? I don't care if Muradin rose up from the dead and whisked ye here on a dragon. I'm busy! Talk to Kryten if you need somethin'." }
WordHunterWoW_QuestEN[691] = { title = "Worth Its Weight in Gold", description = "Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", objectives = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", progress = "Have you had any luck so far, <name>?\n\n\n\nIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they've completed their rites of passage. There's no way to tell which shadow hunters will have the knife until you do battle.", completion = "Incredible! I can see why Malin asked you to come join us--very well done indeed!\n\nAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.\n\nI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you're ready.\n\nIt looked as though he might have had a bit of a scuffle with the ogres. Don't mention that to him, though; he's very sensitive about criticisms to his skills at scouting." }
WordHunterWoW_QuestEN[692] = { title = "The Lost Fragments", description = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!\n\nOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!\n\n...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.\n\nBut if you can gather those fragments, maybe we can fix it...", objectives = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", progress = "Did you find those fragments?!?!  You'll need the Scroll of Myzrael if you want to trap her again, before it's too late!", completion = "Ah, you found them!  Good work, <name>! These might be the only chance we have against the evil of Myzrael!\n\nJust let me find my scrap-ratchet and see if I can re-attach these fragments..." }
WordHunterWoW_QuestEN[693] = { title = "Wand over Fist", description = "Hey, <name>. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", objectives = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", progress = "Our goal is the wand, <name>. Focus on that for now.", completion = "Brilliant, <name>. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest." }
WordHunterWoW_QuestEN[694] = { title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to activate the tower's defenses if you're gonna stand a chance against 'em an' still make it to the items alive. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant 'em so they'll work as a key.", objectives = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", progress = "<name>, hello again. Have you found an azure agate yet?", completion = "You amaze me, <name>. Well done again.\n\nGive me a moment to cast the proper spell to enchant the gem, an' you'll be ready." }
WordHunterWoW_QuestEN[695] = { title = "An Apprentice's Enchantment", description = "Here you are, <name>. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. \n\nGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.", objectives = "Speak to Skuerto at Refuge Pointe in Arathi Highlands.\n\nProvided item:", completion = "Good, good.\n\nIf there are no other delays, how about we get started?" }
WordHunterWoW_QuestEN[696] = { title = "Attack on the Tower", description = "Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.\n\nAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.\n\nBe careful, an' good luck.", objectives = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, <name>. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been." }
WordHunterWoW_QuestEN[697] = { title = "Malin's Request", description = "Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, <name>, of that I've no doubt.\n\nTravel safely.", objectives = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.", progress = "Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.", completion = "<Archmage Malin opens the letter, and his eyes grow wide.>\n\nBy the Light, you've done it. How wonderful. Trelane will be so pleased. I'm sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.\n\nThank you, <name>. Please, take this to help you in your journeys." }
WordHunterWoW_QuestEN[698] = { title = "ack of Surplus", description = "I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.\n\nThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?\n\nThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.", objectives = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.", progress = "Lok'tar, <class>. Traveling through the swamps isn't a risk taken lightly. You're brave to test your mettle here.", completion = "Ah! Wonderful. Fresh meat for the fire tonight. Thank you, <name>.\n\nYou've helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.\n\nIt's a pleasant surprise to have you bring us a shipment; Dar's not the most attractive orc anyone's laid eyes upon, but at least his attitude reeks far less than his smell." }
WordHunterWoW_QuestEN[699] = { title = "ack of Surplus", description = "With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.\n\nThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.", objectives = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.", progress = "Good mead, a warm fire, an army of orcs and an arsenal of weapons... that's all we really need out here along the coast. I don't regret my position out here safeguarding Stonard, but it would be nice if we could one day get a burrow, or at least a tower.", completion = "Glad to see you're alive and well, <name>.\n\nThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we'll be.\n\nI'll get started on your weapon as soon as possible. It will only take a short time. I've become quite adept and quick at their production." }
WordHunterWoW_QuestEN[700] = { title = "A King's Tribute", description = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested.", objectives = "Report to King Magni Bronzebeard.Ah, such fine stone comes from Lordaeron. Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested.", completion = "The granite seems but a small token compared to a great dwarf's life. But no dwarf shall last on this planet for eternity.\n\nLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future.  Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives." }
WordHunterWoW_QuestEN[701] = { title = "Guile of the Raptor", description = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.", objectives = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.", progress = "My preparations are made, all I require are the raptor hearts.", completion = "Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor'mul with the fiery strength and intelligence of the raptor." }
WordHunterWoW_QuestEN[702] = { title = "Guile of the Raptor", description = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.", objectives = "Give Tor'gan's Orb to Gor'mul at Hammerfall in Arathi Highlands.", progress = "Returned again have you? Indeed there is nothing more I could wish for now than more of Tor'gan's pity.\n\nWhat have you for me this time? Perhaps a piece of brightly colored string? Or a length of rope to end this misery of mine...", completion = "At least it is something interesting you bring to me this time. A strange power it emits..." }
WordHunterWoW_QuestEN[703] = { title = "Barbecued Buzzard Wings", description = "Oh yes, my barbecued buzzard wings are a favorite!  The sauce is rich and the meat is tangy.  And the smell will bring the hungry running from miles away!\n\nI have everything I need to cook up a batch.  Everything...except the buzzard wings!\n\nIf you want some then get me the buzzard wings.  Bring me enough, and I might even share the recipe with you!", objectives = "Bring 4 Buzzard Wings to Rigglefuzz.", progress = "Hello, <name>.  Did you bring me my wings?", completion = "Ah, I'll get started on those wings right away.  I can almost taste them already!\n\nAnd here's the recipe in case you want to make them yourself!" }
WordHunterWoW_QuestEN[704] = { title = "Agmond's Fate", description = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.", objectives = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", progress = "Did you find those urns, <name>?  We must find the link between them and the troggs!", completion = "Well done!  With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.  \n\nYou have done a great deed for the Prospectors, <name>.  Your efforts will not be forgotten.  And neither will Agmond." }
WordHunterWoW_QuestEN[705] = { title = "Pearl Diving", description = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn!", objectives = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.", progress = "Did you get my pearls?  I'm almost out of flash bombs!", completion = "These will work great!  I just need to smash them into powder...then mix them with a little of this and a little of that.\n\nWatch out, scavengers!  Prepare to be flashed!" }
WordHunterWoW_QuestEN[706] = { title = "Fiery Blaze Enchantments", description = "As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron.\n\nI can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!", objectives = "Acquire a Black Drake's Heart for Sigrun Ironhew.", progress = "How goes the hunt, <class>?", completion = "Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!" }
WordHunterWoW_QuestEN[707] = { title = "Ironband Wants You!", description = "<name>.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband.", objectives = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", completion = "So Stormpike sent you, did he?  Good.\n\nI have a big task for you..." }
WordHunterWoW_QuestEN[708] = { title = "The Black Box", description = "The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time.\n\nTurning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words:\n\n\"Engine #19 - Ironforge Siege Brigade\"You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Corroded Black Box to the Hall of Arms in Ironforge." }
WordHunterWoW_QuestEN[709] = { title = "Solution to Doom", description = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.", objectives = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", progress = "Did you find the tablet?  It must hold secrets!  Secrets to save us!", completion = "Oh, fortune is with us!  Thank you!  We may yet be saved!" }
WordHunterWoW_QuestEN[710] = { title = "Study of the Elements: Rock", description = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.\n\nWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.\n\nThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?", objectives = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.", progress = "This area's perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?", completion = "These shall do nicely, <name>. Thank you. Hmm, a bit more sand than I'd anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil." }
WordHunterWoW_QuestEN[711] = { title = "Study of the Elements: Rock", description = "<name>, you've already proven more able than all my apprentices combined.\n\nThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.\n\nTake your time; I'll need a while to test these smaller pieces you brought me.", objectives = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.", progress = "I'm most pleased, <name>. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I'll be able to control will put anything summoned prior to this to shame.", completion = "<name>, simply amazing! I would have thought it'd take half a dozen tauren to bring all these to me." }
WordHunterWoW_QuestEN[712] = { title = "Study of the Elements: Rock", description = "<name>, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.\n\nMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.\n\nBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.", objectives = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", progress = "The stone slabs you found were ideal, <name>. Lucien will be taking the extra ones back to Kharanos when we're done here. After all, they could prove useful again.\n\nFor instance, they'd be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...", completion = "<name>, have you ever considered becoming a research assistant? No? I'm not sure what I'll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package." }
WordHunterWoW_QuestEN[713] = { title = "Coolant Heads Prevail", description = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.\n\nIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.\n\nI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.\n\nBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.", objectives = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", progress = "Have you found the oil I need? It would be so helpful if you were able to find some.", completion = "Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don't last a century, then I'll give all my belongings to Servo.\n\nAll the mages of the Assembly will be in such awe after I finish this, <name>. You just wait and see." }
WordHunterWoW_QuestEN[714] = { title = "Gyro... What?", description = "<name>, you've done your job well beyond all standards.\n\n<Lotwil's obviously distracted by his work.>\n\nIf we ever meet in Kharanos, feel free to come apply for work.\n\nWhoops! Quick, grab the... yes, that. Thanks.\n\nNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.\n\nIf you could just go grab one and bring it to me, I should be ready to complete this.", objectives = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", progress = "Yes, yes, yes. Just a moment.\n\n<Lotwil continues to work on some kind of contraption.>", completion = "HA!\n\n<Lotwil grabs the gyrochronatom from you.>\n\nPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you've helped me create. It'll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We'll see..." }
WordHunterWoW_QuestEN[715] = { title = "Liquid Stone", description = "I'm thinking those items you acquired for Lotwil are going to be the least of our worries, <name>. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out?\n\nI need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off.\n\nIn return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.", objectives = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.", progress = "He's getting closer to finishing. How are things going on your end?", completion = "YES!\n\nI mean, thank you, <name>. These will be helpful while traveling through the Badlands." }
WordHunterWoW_QuestEN[716] = { title = "Stone Is Better than Cloth", description = "I know how cheap Lotwil can be, <name>, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.\n\nI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.\n\nI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.", objectives = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.", progress = "I wouldn't wait too long to get that bracer, <name>.\n\nWho knows what's going to happen next?", completion = "Here you go, <name>. Try these on." }
WordHunterWoW_QuestEN[717] = { title = "Tremors of the Earth", description = "It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken.\n\nThe drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them.\n\n<name>... assure that their dreams are eternal.", objectives = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.", progress = "Strong magics and powers held the drakes' prison for so long, but we cannot allow any possibility that Blacklash and Hematus may be released.", completion = "No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased." }
WordHunterWoW_QuestEN[718] = { title = "Mirages", description = "In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean.\n\nAnyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food.\n\nWe're in a bit of a pickle here, suppose you could help us out?", objectives = "Retrieve the Supply Crate for Sigrun Ironhew.", progress = "The desert's a bad place to be hungry, my friend, let me tell you that.\n\nHey... what's that over there...", completion = "Thanks so much, <name>. While you were gone, I... er... swallowed a mouthful of sand. It...\n\nWell, enough of that, we'll go out and get some food tonight. Eat like kings!" }
WordHunterWoW_QuestEN[719] = { title = "A Dwarf and His Tools", description = "Hey, <name>. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan.\n\nThey just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life.\n\nThe site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick.\n\nThink you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.", objectives = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.", progress = "Not sure what the Shadowforge were lookin' for, but they definitely had a purpose.", completion = "Ye're me savior, <class>. I'm glad someone could teach those Shadowforge a lesson or two. Thanks for yer help." }
WordHunterWoW_QuestEN[720] = { title = "A Sign of Hope", description = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol, \nThey're taking me to Uldaman. Send help.\n-Hammertoe\"", objectives = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", completion = "Hammertoe's alive?! This is amazin', <name>!" }
WordHunterWoW_QuestEN[721] = { title = "A Sign of Hope", description = "<name>, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!", objectives = "Find Hammertoe Grez in Uldaman.<name>, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!", completion = "Yes? Ah'm sorry... <cough> Feel so weak. Can ye come closer, <class>?\n\nRyedol sent ye? Muradin be praised, that boy's not as slow in the head as I once thought." }
WordHunterWoW_QuestEN[722] = { title = "Amulet of Secrets", description = "Ye're brave... <cough>... to come into Uldaman fer me, <class>.\n\nIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.\n\nDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, <name>. Please... get that amulet.\n\nThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.", objectives = "Find Hammertoe's Amulet and return it to him in Uldaman.", progress = "The Shadowforge clan... <cough> is dangerous. Be careful. <cough> You must find the amulet.", completion = "Ha! <cough cough>\n\nAh knew you'd find me amulet, <name>.\n\n Well done indeed, <name>." }
WordHunterWoW_QuestEN[723] = { title = "Prospect of Faith", description = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, <name>. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>", objectives = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", progress = "I'd say it was a bad day, but this is the Badlands: every day's a bad day.", completion = "Hammertoe's amulet? I think my spirits were higher when I thought he was dead. Knowin' fer sure only makes the pain worse. This amulet was his life's work. I can't let his death be in vain." }
WordHunterWoW_QuestEN[724] = { title = "Prospect of Faith", description = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.", objectives = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", progress = "Ah, yes. Another traveler seeking something from the dwarves.\n\nSir, I'm truly sorry, but I've no time to answer meaningless questions right now.", completion = "Oh! Well, this is a different matter entirely. You probably don't realize the gravity of this matter yet, do you?\n\nI care deeply about Hammertoe's demise, but if he sent you here with his amulet, then he understood what's at stake.\n\nWe will have to take time to mourn his death later.\n\nLet me show you one of the reasons this amulet is so valuable." }
WordHunterWoW_QuestEN[725] = { title = "Passing Word of a Threat", description = "<name>, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.", objectives = "Find Advisor Belgrum and give him his note.", progress = "Hmm? Yes, <class>.", completion = "Ah, word from Historian Karnik. Excellent.\n\nI always have time for his business.\n\n<Advisor Belgrum opens the note and begins to read.>" }
WordHunterWoW_QuestEN[726] = { title = "Passing Word of a Threat", description = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n<name>, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.", objectives = "Speak to Historian Karnik.<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n<name>, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.", completion = "You're treating this matter with an urgency I'd expect from the king himself, <name>.\n\nAll right, then. I know what'll bring the Shadowforge down.\n\nTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress." }
WordHunterWoW_QuestEN[727] = { title = "To Ironforge for Yagyin's Digest", description = "The Tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!", objectives = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", progress = "Hello.  Welcome to my shop, but watch what you touch.\n\nKnowledge can be deadly.", completion = "Oh.  Greetings, brother.\n\nAnd praise to the dwellers beneath." }
WordHunterWoW_QuestEN[728] = { title = "To the Undercity for Yagyin's Digest", description = "The tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!", objectives = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.", progress = "Ah, we have an eager <class>, I see.  Are you here to learn from my collection?  Good!\n\nBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.", completion = "Be discrete with your signs, <class>. There are those who do not believe the righteousness of our pledge.\n\nAnd there are those who would see us fail if they knew of us.\n\nWe must always be careful.  And watchful.  And patient." }
WordHunterWoW_QuestEN[729] = { title = "The Absent Minded Prospector", description = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious ...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is okay!", objectives = "Travel south and check on Prospector Remtravel.What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is okay!", completion = "Hollee, is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.\n\nHey, you're not Hollee! Don't suppose you've seen my stone brush?\n\nNever mind that now! I promised the League I'd send the mysterious fossil I found. Where did Hollee go?\n\nSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...\n\nAnd who are you... 'tis no matter, so long as you're here to help.\n\nLet me know when you're ready to start looking." }
WordHunterWoW_QuestEN[730] = { title = "Trouble In Darkshore?", description = "How nice it is to see a <class> interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.", objectives = "Travel to Auberdine and look for signs of the dwarven excavation team.How nice it is to see a <class> interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.", completion = "I'm so glad Chief Archeologist Greywhisker sent for us...." }
WordHunterWoW_QuestEN[731] = { title = "The Absent Minded Prospector", description = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?\n\nBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.\n\nLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.\n\nSo are you ready yet?", objectives = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.", completion = "Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can't believe he insisted on staying there with all of those horrible creatures lurking about." }
WordHunterWoW_QuestEN[732] = { title = "Tremors of the Earth", description = "I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine.\n\nI cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance.\n\nA band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you more.", objectives = "Retrieve the Sign of the Earth for Garek.", progress = "The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress.  I have heard that sometimes they travel through Camp Boff.  If you are lost, you might try your search there.", completion = "Good tidings you bring bearing the Sign, <name>. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing's ruthless lieutenants, the twins Blacklash and Hematus." }
WordHunterWoW_QuestEN[733] = { title = "Scrounging", description = "It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...\n\nAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.\n\nThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.", objectives = "Get 7 pieces of Scrap Metal for Sigrun.", progress = "Well, I've made do with what I could, but... it's not much. Have you found any more supplies?", completion = "It's a start, <name>, and it'll have to do until we hear word from Ironforge or the Explorers' League.\n\nNow, if only I could find some salt somewhere for my quenching barrel..." }
WordHunterWoW_QuestEN[734] = { title = "This Is Going to Be Hard", description = "Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, <name>. I need a cog #5. Bring it to me, will you?", objectives = "Speak to Lucien Tosselwrench in the Badlands.Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, <name>. I need a cog #5. Bring it to me, will you?", completion = "Cog #5, huh? Yeah, this isn't going to be good." }
WordHunterWoW_QuestEN[735] = { title = "The Star, the Hand and the Heart", description = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.\n\nI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.\n\nI require three items of power.  Bring them to me and I will give you the digest.\n\nI will not speak their names.  Ears may be on us.  But here, I will write them down.", objectives = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.", progress = "Do you have the relics for which I asked?", completion = "You are resourceful, <class>.  If it truly is your charge to begin a new chapter of our order, then I believe you will run it well." }
WordHunterWoW_QuestEN[736] = { title = "The Star, the Hand and the Heart", description = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, <brother/sister>.\n\nBut you must help me too.\n\nI require three items of power.  Bring me these and the digest will be yours.\n\nI cannot utter the names of these items, but I will write them down.\n\nGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.", objectives = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.", progress = "How goes your mission, <class>.", completion = "I am impressed!  You possess great skill, or great fortune, to have gained these relics.  Either way, you are an asset to us." }
WordHunterWoW_QuestEN[737] = { title = "Forbidden Knowledge", description = "I have the digest for you, <name>.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  \n\nThis book holds many truths...\n\n...And the truth can burn.", objectives = "Bring Yagyin's Digest to Theldurin.", progress = "Ho!  You were gone a long time.  Did you get the digest?", completion = "You got it!  Oh, hope glimmers!\n\nYour efforts may yet save us, <name>.  A monument they should make of you!  A shrine they should build!  May your name be praised until your grandchildren have grandchildren!\n\nUnless...THEY are freed and rise to the surface.   If that happens then you can forget about children.\n\nIf THEY are freed, then we're all worm food." }
WordHunterWoW_QuestEN[738] = { title = "Find Agmond", description = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.", objectives = "Find Agmond.", completion = "This skeleton must be the unfortunate remains of Agmond.  His body is broken and battered, and his bones picked clean." }
WordHunterWoW_QuestEN[739] = { title = "Murdaloc", description = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.", objectives = "Slay Agmond's killer, Murdaloc.\n\nSlay 12 Stonevault Bonesnappers.\n\nReport to Prospector Ironband in Loch Modan.", completion = "This is sobering news, <name>.  But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come!  Although he was killed by those cursed troggs I'm sure he took a lot of them down with him." }
WordHunterWoW_QuestEN[741] = { title = "The Absent Minded Prospector", description = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.\n\nHere, <name>, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", objectives = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", progress = "What can I do for you, <race>?", completion = "Oh my! Leave it to Prospector Remtravel to discover such a find!" }
WordHunterWoW_QuestEN[742] = { title = "The Ashenvale Hunt", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", objectives = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", completion = "Welcome to the new frontier, <name>. Ashenvale is a land of opportunity, one where a young <class> like yourself is able to find boundless chances to prove their mettle. Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt. Listen close, and I will gladly share with you what you need to know." }
WordHunterWoW_QuestEN[743] = { title = "Dangers of the Windfury", description = "Thank you for taking the time to speak to me, {name}. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.", objectives = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.", progress = "The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.", completion = "You have done well, <name>. You seem well prepared to travel onward. Let the wind always be at your back." }
WordHunterWoW_QuestEN[744] = { title = "Preparation for Ceremony", description = "{name}, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", objectives = "Collect 6 Azure Feathers and 6 Bronze Feathers.", progress = "This headdress will certainly be a wonderful gift for my brother.", completion = "Thank you for your help, <name>.\n\nMy part in my brother's ceremony is almost complete. Giving him his headdress and witnessing the ceremony are all my duty requires of me." }
WordHunterWoW_QuestEN[745] = { title = "Sharing the Land", description = "<name>, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", objectives = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.", completion = "<name>, it is good you've taken my task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it." }
WordHunterWoW_QuestEN[746] = { title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", objectives = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.", progress = "Hello, <name>.  Do you have the Broken Tools?  The dwarves' digging will enrage the kodos of Mulgore.  This defilement must be stopped!", completion = "Thank you, <name>.  This will calm the beasts of Mulgore.  And, spirits willing, it will teach the dwarves that hollowing the land is not the path to knowledge." }
WordHunterWoW_QuestEN[747] = { title = "The Hunt Begins", description = "You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind.\n\nUp here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.", objectives = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.", progress = "Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.", completion = "The <race> of Narache thank you, <name>. You show much promise." }
WordHunterWoW_QuestEN[748] = { title = "Poison Water", description = "Goblins and their servants have tainted our sacred water wells!  We cannot allow this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, <name>.", objectives = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.", progress = "Do you have the paws and talons, <name>?", completion = "You have done well, <name>.  I will take these and bind their power into a totem of cleansing." }
WordHunterWoW_QuestEN[749] = { title = "The Ravaged Caravan", description = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.", objectives = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.", completion = "All sides of the crate are stamped with the sign of the Venture Co. Mining Division. Notes printed carefully on the side of the carton indicate that the contents are due for processing at one of their central plants." }
WordHunterWoW_QuestEN[750] = { title = "The Hunt Continues", description = "A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south.\n\nOur children need clothing and our tents need mending.", objectives = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.", progress = "If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.", completion = "The <race> of Narache thank you for these provisions, <name>. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday." }
WordHunterWoW_QuestEN[751] = { title = "The Ravaged Caravan", description = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.", objectives = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.", progress = "Hail, <name>. Have you learned anything new about the Venture Co.'s plans and operations in our homeland?\n\nIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.", completion = "It does indeed appear that the Venture Co. is attempting to rob us of our natural resources. It is good to know this is true, and now it seems, we must do something about it." }
WordHunterWoW_QuestEN[752] = { title = "A Humble Task", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?", objectives = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", completion = "You traveled all this way just to help an old woman? My my, aren't you a keeper?" }
WordHunterWoW_QuestEN[753] = { title = "A Humble Task", description = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.\n\nBut you look like an eager <class>. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.\n\nRemember that even the most humble task can gain the recognition of elders.", objectives = "Take a Water Pitcher from the water well.\n\nReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.", progress = "You look as though you have returned from the plains. Do you have any word from Greatmother Hawkwind?", completion = "You carried this pitcher back at the Greatmother's bidding, I see.\n\nYour willingness to help others and provide for the <race> of Camp Narache leads me to believe you would make the tribe proud in Thunder Bluff someday." }
WordHunterWoW_QuestEN[754] = { title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins!\n\nThis will not be an easy task, but you must do it if we are ever to use its waters again.\n\nFortune to you, <name>.", objectives = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.", completion = "News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.\n\nYou have done a great thing for the land, <name>.  And you have done a great thing for the <race> people." }
WordHunterWoW_QuestEN[755] = { title = "Rites of the Earthmother", description = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, <name>. I believe one day you will be heralded in Thunder Bluff as a <class> of greatness.\n\nBefore that you must embark on the Rites of the Earthmother, of which there are three.\n\nThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.\n\nYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.", objectives = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.", completion = "Chief Hawkwind sent you? Embarking on the Rites of the Earthmother is no small task..." }
WordHunterWoW_QuestEN[756] = { title = "Thunderhorn Totem", description = "To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", objectives = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.", progress = "<name>, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, <name>.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe goblins will never learn the difference between contending with the land, and living in harmony with it." }
WordHunterWoW_QuestEN[757] = { title = "Rite of Strength", description = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.\n\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\n\nBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\n\nShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.", objectives = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.", progress = "Have you completed the Rite of Strength, <name>? I require proof of your valor against the enemy of our tribe, the Bristlebacks.", completion = "You have passed the first test of the Rites of the Earthmother. The tribe will be proud." }
WordHunterWoW_QuestEN[758] = { title = "Thunderhorn Cleansing", description = "The totem is ready, <name>.  And again, it is your task to perform the ritual of cleansing.\n\nGo to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me.\n\nMay the spirits guide you.", objectives = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.", completion = "Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.\n\nFor their gratitude, they wish to give you this..." }
WordHunterWoW_QuestEN[759] = { title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", objectives = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.", progress = "<name>.  Do you have the teeth I asked for?", completion = "Very good, <name>.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride." }
WordHunterWoW_QuestEN[760] = { title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young <name>.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the Grimtotem's poisons!  Let clean water flow once again!", objectives = "Use the Wildmane Cleansing Totem at the Wildmane Water Well.", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, <name>.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever." }
WordHunterWoW_QuestEN[761] = { title = "Swoop Hunting", description = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.", objectives = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.", progress = "Have you found the swoops, <name>.  Do you have their quills?", completion = "I know that gathering these quills was not an easy task, <name>.  In doing this, you prove that you are a <class> of merit.  It is good to have you at Bloodhoof Village." }
WordHunterWoW_QuestEN[762] = { title = "An Ambassador of Evil", description = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, <class>. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands now.", objectives = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", progress = "Time is of the essence, <name>. Ragnaros will not wait for us to prepare.", completion = "<name>, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.\n\nI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.\n\nBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard." }
WordHunterWoW_QuestEN[763] = { title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, <name>.\n\nTravel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Baine. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", objectives = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.", progress = "What brings you to my village, <class>?", completion = "Word from my good friend, Chief Hawkwind! Ah, I can see by his carvings you are of a special breed." }
WordHunterWoW_QuestEN[764] = { title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", objectives = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the <race> lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest." }
WordHunterWoW_QuestEN[765] = { title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", objectives = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.", progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, <name>." }
WordHunterWoW_QuestEN[766] = { title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard.\n\nHurry, time is of the essence.", objectives = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.", progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, <name>. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels." }
WordHunterWoW_QuestEN[767] = { title = "Rite of Vision", description = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.\n\nOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.", objectives = "Speak with Zarlman Two-Moons in Bloodhoof Village.", completion = "I sensed you would be coming to me, <class>. I can always recognize one who is trying to pass the Rites of the Earthmother." }
WordHunterWoW_QuestEN[768] = { title = "Gathering Leather", description = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.", objectives = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.", progress = "Hello again.  Have you been hunting?  Do you have skins for me?", completion = "Ah, these are very nice pieces.  They'll make fine leather goods.\n\nHere, <name>.  Take this in trade..." }
WordHunterWoW_QuestEN[769] = { title = "Kodo Hide Bag", description = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.", objectives = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.", progress = "Do you have my supplies, <name>?", completion = "Ah, good.  Thank you, <name>.  My heart swells with pride to see youths interested in the craft of leatherworking." }
WordHunterWoW_QuestEN[770] = { title = "The Demon Scarred Cloak", description = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Camp Sungraze should know of Ghost Howl's demise....", objectives = "Find someone who knows of Ghost Howl.\n\nProvided item:", completion = "I can barely believe my old eyes!  You defeated the great wolf Ghost Howl?  I look upon you with new respect, young <class>.  You are a hunter of extreme skills!\n\nLet me offer you something.  My days of hunting are over, but I would be honored if you used one of my weapons in your hunts.\n\nMay it strike true, and bring you renown.\n\nAnd let us hope that Ghost Howl's spirit has finally found peace." }
WordHunterWoW_QuestEN[771] = { title = "Rite of Vision", description = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.\n\nI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.\n\nThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.", objectives = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.", progress = "Once you have gathered enough well stones from around the water wells and Ambercorn from beneath the trees, I will prepare the Water of the Seers for you.", completion = "I see you have learned to gather from our sacred land, <name>. It will take but a moment for me to brew the Water of the Seers." }
WordHunterWoW_QuestEN[772] = { title = "Rite of Vision", description = "I now present you with the Water of the Seers.\n\nWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.\n\nAt that point, it is up to you to follow it to your destiny....", objectives = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.\n\nProvided item:", completion = "Be not afraid, <name>. You have successfully passed the Rite of Vision." }
WordHunterWoW_QuestEN[773] = { title = "Rite of Wisdom", description = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, {name}.", objectives = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.", completion = "You have shown great diligence in your yearning to pass the Rites of the Earthmother, <name>.\n\nWe, the Ancestral Spirits, represent the mighty <race> who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you." }
WordHunterWoW_QuestEN[775] = { title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any <race> worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", objectives = "Speak with Cairne Bloodhoof in Thunder Bluff.You will now be revered within our great city. Any <race> worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", completion = "Hail, young <class>. I see you found your way to my doorstep." }
WordHunterWoW_QuestEN[776] = { title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, <name>. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", objectives = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", progress = "Have you tracked down Arra'chea yet?", completion = "Well done! A fine kill that was.\n\nI will send a gathering party to collect the carcass so we can retrieve the hide and meat.\n\nYou have done a great deed for your people, <name>." }
WordHunterWoW_QuestEN[777] = { title = "This Is Going to Be Hard", description = "Okay, here you go.\n\nI'm going to be over here... behind cover.\n\nFeel free to join me.", objectives = "Bring Cog #5 to Lotwil Veriatus.", progress = "<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>\n\nThe cog, <name>, the cog!", completion = "Ah, perfect. Stand back while I prepare to make more history!\n\n<Lotwil continues to work feverishly.>" }
WordHunterWoW_QuestEN[778] = { title = "This Is Going to Be Hard", description = "Haha! Done! The shackles are done!\n\nIt's time, Lucien. It's time, Servo!\n\nAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, <name>?\n\nI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.", objectives = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.", progress = "Not quite the outcome I was expecting. Could you get my shackles back?", completion = "Thank you, <name>. That was quite an ordeal, wasn't it?\n\nI'm not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.\n\nPerhaps a little token of appreciation for all your hard work..." }
WordHunterWoW_QuestEN[779] = { title = "Seal of the Earth", description = "", objectives = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken." }
WordHunterWoW_QuestEN[780] = { title = "The Battleboars", description = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.", objectives = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.", progress = "The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?", completion = "Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks." }
WordHunterWoW_QuestEN[781] = { title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!You will receive:", objectives = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache." }
WordHunterWoW_QuestEN[782] = { title = "Broken Alliances", description = "From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!\n\nWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!", objectives = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.", progress = "Tho'grun's betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.\n\nIf you've not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.", completion = "With Tho'grun dead, his corpse picked clean by the desert winds and scavenging buzzards, the ogres will be put into disarray. Though a small victory, this will lead to a much larger one\n\nThe Sign of the Earth is now in our possession, and we can open the black drakes' prison in Lethlor.  We shall free them from endless imprisonment, albeit to their doom!" }
WordHunterWoW_QuestEN[783] = { title = "A Threat Within", description = "We're in a real mess here, young <class>. Deathwing and his Twilight armies have launched a full attack upon Azeroth. The king has called for all able-bodied citizens of the Alliance to lend a hand.\n\nThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close. We're enlisting the aid of anyone willing to defend their home.\n\nIf you're here to answer the call, then speak with my superior, Marshal McBride. He's outside the abbey.", objectives = "Speak with Marshal McBride.", completion = "Ah, good.  Another volunteer.  We're getting a lot of you these days.\n\nI hope it's enough.\n\nThe <race> lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.\n\nIt is a many-fronted battle we wage, <name>.  Gird yourself for a long campaign." }
WordHunterWoW_QuestEN[784] = { title = "Vanquish the Betrayers", description = "Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago.\n\nThe human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.\n\nProve your honor and travel south to Tiragarde Keep to eliminate the human invaders.", objectives = "Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.", completion = "Word of your bravery travels fast, <class>. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar." }
WordHunterWoW_QuestEN[785] = { title = "A Strategic Alliance", description = "Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.\n\nThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.\n\nThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.\n\nSeek out Lar and assist as needed.Upon completion of this quest you will gain:", objectives = "Seek out Lar Prowltusk on the western flank of Sen'jin Village.Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.\n\nThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.\n\nThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.\n\nSeek out Lar and assist as needed.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[786] = { title = "Thwarting Kolkar Aggression", description = "Lower your voice, <class>. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag.\n\nLast night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar.\n\nWe mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans.\n\nLast I saw, they had divided them up amongst three of their leaders.", objectives = "Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.", completion = "The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.\n\nAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.\n\nYou have served your people well, <class>." }
WordHunterWoW_QuestEN[787] = { title = "The New Horde", description = "Throm'ka, <class>. I am Eitrigg, charged by Thrall to oversee the training of recruits.\n\nThe Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned.\n\nGornek will have further instructions for you.Upon completion of this quest you will gain:", objectives = "Report to Gornek in the Den.Throm'ka, <class>. I am Eitrigg, charged by Thrall to oversee the training of recruits.\n\nThe Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned.\n\nGornek will have further instructions for you.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[788] = { title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you would find a good match with the mottled boars you'll find to the north of here.", objectives = "Kill 8 Mottled Boars then return to Gornek at the Den.", completion = "Hmmm, not bad, <name>. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection." }
WordHunterWoW_QuestEN[789] = { title = "Sting of the Scorpid", description = "Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me eight of their tails as proof of your prowess in battle.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", objectives = "Get 8 Scorpid Worker Tails for Gornek in the Den.", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, <name>. You have done well, and I will watch your progress with interest." }
WordHunterWoW_QuestEN[790] = { title = "Sarkoth", description = "<class>! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", objectives = "Kill Sarkoth and bring his claw back to Hana'zua.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger." }
WordHunterWoW_QuestEN[791] = { title = "Carry Your Weight", description = "Age has rendered me useless in battle. Now I make myself useful in other ways.\n\nFrom this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less.\n\nTo pass the time I fashion goods to help younger, more able warriors defend our homeland.\n\nFor you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.", objectives = "Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.", progress = "I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.\n\nThe honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.\n\nBut my position as watchman and provider has given me a new sense of worth.", completion = "Most excellent, <name>. Any good <class> will surely find a use for this bag on the battlefield.\n\nI salute your vigor and willingness to die in the name of the Horde!" }
WordHunterWoW_QuestEN[792] = { title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young <class>.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nA group that calls itself the Burning Blade has a coven here in the Valley of Trials.  They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", objectives = "Kill 8 Vile Familiars.\n\nReturn to Zureetha Fargaze outside the Den.", completion = "You have done well, <name>.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead." }
WordHunterWoW_QuestEN[793] = { title = "Broken Alliances", description = "The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth.\n\nBe wary though, <name>, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me.\n\nTo reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.", objectives = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.", progress = "There are few enemies more deadly than dragonkind, and there were few dragons that fought as ferociously as Blacklash and Hematus.", completion = "The black dragonflight continues to ally with the renegade Blackrock orcs, and both must be brought into line, or removed. With Blacklash and Hematus dead, we can turn our attentions westwards, towards Blackrock Spire." }
WordHunterWoW_QuestEN[794] = { title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic.\n\nIt is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven.\n\nBut be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered.\n\nGo, <name>.  You will find the coven in a cave, to the north and west.", objectives = "Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.", progress = "Is your task complete, <name>?  Do you have the Burning Blade Medallion?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them." }
WordHunterWoW_QuestEN[795] = { title = "Seal of the Earth", description = "", objectives = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken." }
WordHunterWoW_QuestEN[804] = { title = "Sarkoth", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to the Den unassisted. Please, <name>, return to the Den and tell Gornek of my situation. Perhaps he can help me.", objectives = "Bring the news of Hana'zua's plight to Gornek at the Den.", completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, <name>. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened." }
WordHunterWoW_QuestEN[805] = { title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.\n\nGo, <name>, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", objectives = "Speak with Master Gadrin in Sen'jin Village.", completion = "Hm... your report comes at a bad time.  The Burning Blade is not seen here in Sen'jin, but their evil has taken seed off the coast, on the Echo Isles.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too." }
WordHunterWoW_QuestEN[806] = { title = "Dark Storms", description = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!\n\nI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.\n\nFind and defeat Fizzle, and bring me his dead claw!", objectives = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.", progress = "Did you find Fizzle, <name>?  He, and rest of the Burning Blade, must be scoured from our lands!", completion = "Aha!  You got him!\n\nYou do your clan proud, <name>.  And because of you, Durotar is free of one more agent of evil." }
WordHunterWoW_QuestEN[808] = { title = "Minshina's Skull", description = "I hear the voice of my brother, Minshina, calling to me in my dreams.\n\nHe was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.\n\nBut death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.\n\nPlease, <name>. Find the circle and retrieve Minshina's skull. Bring it to me.\n\nFree him!", objectives = "Retrieve Minshina's skull from the circle of power on the Echo Isles.\n\nBring it to Master Gadrin in Sen'jin Village.", progress = "Do you have my brother's skull, <name>?  Is he finally free?", completion = "Thank you, <name>.  You have saved Minshina.  You have saved my brother's spirit from slavery!" }
WordHunterWoW_QuestEN[809] = { title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!\n\nGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.", objectives = "Speak with Ak'Zeloth in the Barrens.", completion = "Neeru wants the Demon Seed destroyed, does he?  Strange...\n\nVery well.  If he wishes the seed gone, then I will tell you how to remove it." }
WordHunterWoW_QuestEN[812] = { title = "Need for a Cure", description = "<name>... your timing is perfect. I just hope I can compliment your haste as well.\n\nI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...\n\nKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, <name>. I won't be able to last much longer. He should be in the Cleft of Shadow.", objectives = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.", progress = "I'm almost glad I can't return to Sen'jin as I am now. My weakness and stupidity would surely be mocked.", completion = "<name>, you've saved my life. Thank you.\n\nPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won't be usin' it anytime soon. Kor'ghan is gonna march me through more of his rituals until I prove myself. More killin' boars, more gatherin' scorpid tails..." }
WordHunterWoW_QuestEN[813] = { title = "Finding the Antidote", description = "Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs.\n\nBring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him.\n\nMake haste, <name>. One of our own needs your help.", objectives = "Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.", progress = "Remember, no matter what creature you hunt, you would do well to study it and understand its behavior. That knowledge could save your life.", completion = "Here is the antidote, <name>. Take it to Rhinag as soon as you can, and be cautious." }
WordHunterWoW_QuestEN[815] = { title = "Break a Few Eggs", description = "Bah! I almost forgot I need to get breakfast ready.\n\n<name>, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.\n\nThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.", objectives = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.", progress = "Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!", completion = "You might be weak, but at least you're not clumsy, <name>.\n\nHere, take this and get outta my way. I've got cooking to do." }
WordHunterWoW_QuestEN[816] = { title = "Lost But Not Forgotten", description = "<name>, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.\n\nAs strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.\n\nIf you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.", objectives = "Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.", progress = "I pray that Kron will return to me, but I'm almost certain I know his fate already.", completion = "Oh, my son... my beautiful son.\n\nUncertain of my son's fate, I have tormented myself since he left. Now that I know what's happened, perhaps I can finally begin to mourn.\n\nThank you, <name>. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it." }
WordHunterWoW_QuestEN[817] = { title = "Practical Prey", description = "Many of the hides we use come from Durotar tigers, <name>. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.\n\nThe time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.\n\nBring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.", objectives = "Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.", progress = "I remember my first tiger hunt, <name>. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.\n\nMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.", completion = "I am pleased, <name>. Because of your help, our people will be protected, and not go cold as the seasons change.\n\nThank you." }
WordHunterWoW_QuestEN[818] = { title = "A Solvent Spirit", description = "Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.\n\nAre you worthy? Yes, of course you are... of course you think you are.\n\nI need a few things. Will you get them for me?\n\nI need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.", objectives = "Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.", progress = "Time is the true test of your strength and will. Lose patience or give in to weakness, and your true self will be shown.", completion = "Well done, young one... well done indeed." }
WordHunterWoW_QuestEN[819] = { title = "Chen's Empty Keg", description = "A small placard on one of the ends of the keg says,\n\n\"Chen Stormstout-\n\nMay your spirit be raised and always raise your spirits.\"", objectives = "Find someone who knows about Chen's Empty Keg.", progress = "Yes?", completion = "Well, I'll be...\n\nThis was one of Chen Stormstout's kegs. He traveled with Rexxar a long time ago. I haven't seen or heard about him in a kodo's age. I appreciate you bringing this to me, <name>." }
WordHunterWoW_QuestEN[821] = { title = "Chen's Empty Keg", description = "Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.\n\nBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.\n\nYou can find these ingredients throughout the Barrens.", objectives = "Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.", progress = "How's the search going?", completion = "Haha... I never thought I'd make more of this stuff ever again.\n\nYou've stirred in me a great sense of nostalgia, <name>. Kind of reminds me of the last time I blacked out from too much trogg ale. Thank you. The memories warm my stomach." }
WordHunterWoW_QuestEN[822] = { title = "Chen's Empty Keg", description = "Good stuff, that stormstout, huh?\n\nI have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more.\n\nBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos.\n\nLike I said, this stuff has kick; it's the trogg ale that I mentioned to you before.", objectives = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.", progress = "You working hard at finding those ingredients, <name>?", completion = "Haha! I knew you couldn't resist some of this brew. Come back again anytime you want some more, <name>. Just bring me more of the ingredients I had you collect." }
WordHunterWoW_QuestEN[823] = { title = "Report to Orgnil", description = "We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.\n\nThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.\n\nRazor Hill lies to the north.", objectives = "Speak with Orgnil Soulscar in Razor Hill.", completion = "Yes?  You have something to report?  Well then, let's have it!" }
WordHunterWoW_QuestEN[824] = { title = "Je'neu of the Earthen Ring", description = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.", objectives = "Bring the Befouled Water Globe to Je'neu Sancrea in Blackfathom Deeps.\n\nProvided item:", completion = "This globe... it is most disturbing.  Many of the more powerful elementals receive their power and energy through such devices.  To find one like this nearly intact is one thing - to find it so tainted is another.\n\nI will see that this globe is studied properly by the Earthen Ring.  Perhaps we can bring an end to this corruption of the elements.  Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring." }
WordHunterWoW_QuestEN[825] = { title = "From The Wreckage....", description = "One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.\n\nIt is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.\n\nSwim through the wreckage, <name>, and retrieve for me the tools of the Alliance.", objectives = "Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.", progress = "Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.\n\nWith our new gained knowledge, the Horde only stands to grow in strength.", completion = "Your recovery mission was a success, <class>. I will see to it that these tools get to Orgrimmar with the next caravan.\n\nNicely done." }
WordHunterWoW_QuestEN[826] = { title = "Zalazane", description = "The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home.\n\nFrom there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.\n\nHe must be stopped.\n\nDefeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.Upon completion of this quest you will gain:", objectives = "Defeat Zalazane.\n\nKill 8 Voodoo Trolls and 8 Hexed Trolls.\n\nBring Zalazane's Head to Gadrin." }
WordHunterWoW_QuestEN[827] = { title = "Skull Rock", description = "<name>.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", objectives = "Gather Searing Collars from the cultists in Skull Rock.\n\nBring them to Margoz at his camp.", progress = "Have you yet entered Skull Rock, <name>?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret..." }
WordHunterWoW_QuestEN[828] = { title = "Margoz", description = "One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the northeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, <name>, I still want you to crush those cultists!", objectives = "Speak with Margoz.", completion = "Welcome, <name>.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a <class> of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed." }
WordHunterWoW_QuestEN[829] = { title = "Neeru Fireblade", description = "The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.", objectives = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", progress = "My most humble greetings, <class>.  How might I help my <race> brother today?", completion = "Ah, and where did you get this?  Good Margoz in Razor Hill sent you to me, did he?\n\nWell, let me take a closer look..." }
WordHunterWoW_QuestEN[830] = { title = "The Admiral's Orders", description = "You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.\n\nThis looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.", objectives = "Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.", progress = "There is a look of concern on your face, <class>. What have you there?", completion = "This does not bode well at all. You were wise to bring this information to my attention." }
WordHunterWoW_QuestEN[831] = { title = "The Admiral's Orders", description = "Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.\n\nAdmiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.\n\nHis reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.\n\nWe need to get these orders to Vol'jin in Orgrimmar immediately! He can be found in Thrall's chamber.", objectives = "Deliver Admiral Proudmoore's Orders to Vol'jin in Thrall's chamber in Orgrimmar.", progress = "Can you not see that I am busy? This had better be pressing....", completion = "Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.\n\nYou have served the Horde honorably, young <class>.\n\nNow excuse me, I must counsel Thrall on these matters at once...." }
WordHunterWoW_QuestEN[832] = { title = "Burning Shadows", description = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?", objectives = "Take this eye to Neeru Fireblade in Orgrimmar.", progress = "You have something vital to report.  I can sense it behind your eyes.", completion = "<Examines the Eye of Burning Shadow.>\n\nIntriguing.  The voice you heard mentioned my name?  I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out.  Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.\n\nI must study this pendant.  I must study and, and must ponder the meaning of its message.\n\nThank you for bringing this to my attention, <name>.  You have done your people a great service." }
WordHunterWoW_QuestEN[833] = { title = "A Sacred Burial", description = "Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\n\nBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.\n\nThey must be driven off with force, {name}.", objectives = "Kill 8 Bristleback Interlopers at Red Rocks.", progress = "The Bristleback Interlopers must be driven away from our sacred burial ground, <name>.", completion = "Well done. You have sent those foul Bristlebacks a clear message. They will think twice before attempting to meddle in this holy spot again." }
WordHunterWoW_QuestEN[834] = { title = "Winds in the Desert", description = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment, which they PROMISED would get through, was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.", objectives = "Retrieve 5 Sacks of Supplies.", progress = "I'm great at what I do, don't get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?", completion = "Hey, now isn't that just the thing! You've got our supplies back for us. That's great. I'll be able to get back to work just as soon as I can find someone to haul these sacks for me." }
WordHunterWoW_QuestEN[835] = { title = "Securing the Lines", description = "Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"\n\nI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Harpies plague our supply routes.  If we kill the harpies, the caravans are safe.\n\nOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" You in, {name}?  Good... I recommend starting in the canyon to the east.", objectives = "Kill 12 Durotar Harpies. Any type of harpy will suffice.", completion = "I think I can breathe easy now, knowing that the harpies won't be bothering our supply caravans anymore. And not one moment too soon, either. I hear I'm being sent some fun little toys with the next shipment!\n\nYou're pretty good at what you do, <name>, you ought to track down my boss in Ratchet. I'll bet he could find some work for you.\n\nOh, and don't worry, I wouldn't forget to pay you for the service you provided me." }
WordHunterWoW_QuestEN[836] = { title = "Rescue OOX-09/HL!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, some big rocks that obscure visibility! That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "Escort OOX-09/HL to safety, then report to Oglethorpe Obnoticus in Booty Bay.", completion = "Oh, YOU'RE the great savior of OOX-09/HL!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance <name>, my robots and I are in your debt!" }
WordHunterWoW_QuestEN[837] = { title = "Encroachment", description = "When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas.\n\nIt has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of Kalimdor.", objectives = "Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.", completion = "I will pass along word that the quilboars have been removed from their lairs, and that their structures may be set to fire. The removal of the Razormane from Durotar brings us closer to fully securing the borders of our new homeland." }
WordHunterWoW_QuestEN[838] = { title = "Scholomance", description = "On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.", objectives = "Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.", completion = "Yes, <class>, the High Executor mentioned you might be the one to trust in the matter of the key.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.\n\nThis task will not be easy, but such tasks seldom are.  You most assuredly look like the type to know this as fact." }
WordHunterWoW_QuestEN[840] = { title = "Conscript of the Horde", description = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.", objectives = "Give Kargal Battlescar at the Barrens outpost your recruitment letter.", progress = "What do you want, pup? If you're not here for recruitment, I don't have time for you.", completion = "Oh, so Takrin sent you?\n\n<Kargal warily eyes your recruitment letter and shoves it unceremoniously into his vest>\n\nI'll sign this when you've earned it. I've got reports from down south that this whole continent is being torn apart. Meanwhile, we've got supply caravans backed up to the river and outposts under siege from here to Stonetalon. You want to prove your worth to the horde? Start by proving it here." }
WordHunterWoW_QuestEN[841] = { title = "Another Power Source?", description = "Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!\n\nTimes are tough all around, <name>, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...", objectives = "Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.", progress = "Well, have you got the ten water pouches?", completion = "Very well, here is another power source.  I highly recommend you using it properly this time, unless you are eager to spend ten more water pouches for another water source." }
WordHunterWoW_QuestEN[842] = { title = "Crossroads Conscription", description = "<Kargal withdraws a battered recruitment letter from his vest and makes his mark on it. He hands it to you solemnly.>\n\nWell pup, you've proven yourself to be a formidable asset. Consider yourself drafted. We need your like at the Crossroads, assuming you can make it there alive. Just follow the road West of here, then South when you hit the junction. If you really want to help your new Horde, talk to Halga and hitch a ride with our next caravan. Deliver this letter to Sergra Darkthorn when you arrive.", objectives = "Deliver your signed recruitment letter to Sergra Darkthorn at the Crossroads. If you haven't already, you can hitch a ride there with the next caravan by talking to Halga Bloodeye at Far Watch Outpost.", progress = "Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?", completion = "Alright, <name>. You want to earn your keep with the Horde? Well there's plenty to do here, so listen close and do what you're told.\n\n I see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain." }
WordHunterWoW_QuestEN[843] = { title = "Gann's Reclamation", description = "In solitude I wander these roads.\n\nThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.\n\nAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.\n\nDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.", objectives = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.\n\nBring Khazgorm's Journal to Gann Stonespire.", progress = "Many innocent tauren lost their lives or were forced off their ancestral birthplace when the dwarves of Bael Modan arrived. My land must be reclaimed!", completion = "Khazgorm met the fate he earned. I feel no remorse for the fool. He was an infidel on these lands.\n\nMay his death serve as a warning to all those who threaten to disrupt our way of life.\n\nNow let me take a moment to study the dwarf's journal...." }
WordHunterWoW_QuestEN[844] = { title = "Plainstrider Menace", description = "Are you familiar with plainstriders? Useless animals. Can't fly. Gamey. Brain the size of my knuckle. Too dim to get out of the way of a moving cart. I've broken more axles thanks to their thick skulls... Sometimes I think the quilboar intentionally frighten flocks of them into the path of our caravans just prior to an ambush.\n\nMake me proud, {class}. Cut a swath through those filthy birds to keep the roads free, and bring me their beaks as proof. ", objectives = "Collect 7 Plainstrider Beaks.", progress = "Have you collected the plainstrider beaks?", completion = "Very good, <name>. That's one less thing to worry about on the road." }
WordHunterWoW_QuestEN[845] = { title = "The Zhevra", description = "If you wish to serve my beloved horde, you'll have to prove your strength to me, pup. You can cut your teeth by hunting zhevra. They may not be the strongest of beasts in the Barrens, but stay clear of their kick or you'll regret it.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.", objectives = "Slay Zhevra Runners to collect 4 Zhevra Hooves.", progress = "How many zhevra have you slain?", completion = "Not bad, <name>. Those zhevra hold a lot of strength in their legs. I've seen them knock even a tauren on its haunches!\n\nIt looks like you have some strength in you too." }
WordHunterWoW_QuestEN[846] = { title = "Revenge of Gann", description = "It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.\n\nI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.\n\nCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!", objectives = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.", progress = "I see you are back, <name>.\n\nWhile Khazgorm's death might delay the digging in my ancestral lands some, it will by no means bring a total end to the destruction.\n\nThe Keep at Bael Modan is an increasing military threat. Built to defend the dig site, it is now poised for offensive force as well.\n\nIf you have the ingredients I requested, I can fashion a charge that will make the hasty dwarves reconsider their actions here in the Barrens.", completion = "I see you are quite industrious, <class>.\n\nNo doubt we shall soon have a fitting surprise for those dwarves." }
WordHunterWoW_QuestEN[847] = { title = "Guile of the Raptor", description = "This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.", objectives = "Speak with Tor'gan at Hammerfall in Arathi Highlands.This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.", completion = "When the enchantment wears off, I will speak with Gor'mul. My thanks to you for your help in returning Gor'mul to the land of the living. I have no doubt he thanks you greatly as well." }
WordHunterWoW_QuestEN[848] = { title = "Fungal Spores", description = "The oases of the Barrens hide a mystery. Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near the Forgotten Pools to the northwest. Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.", objectives = "Collect 5 Fungal Spores from mushrooms at the Forgotten Pools.", progress = "Do you have the spores, <name>? My associates and I are eager to study this phenomenon...", completion = "Ah, yes. These are good specimens. Potent.\n\nI am Forsaken, and we honor our contracts. Here is your reward, <name>." }
WordHunterWoW_QuestEN[849] = { title = "Revenge of Gann", description = "Following Khazgorm's plans it should be no problem to fashion an explosive charge\n\nAh, there we go.\n\nNow, <name>, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.\n\nNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.\n\nMake me proud by completing this heroic task and you shall be rewarded.", objectives = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.", completion = "You have done well, <name>! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe." }
WordHunterWoW_QuestEN[850] = { title = "Kolkar Leaders", description = "The centaurs have plagued the tauren for years. And recently, the Kolkar centaurs of the Barrens have grown into a real threat. Normally they were disorganized in these lands, but new leaders have risen among them. Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane. He camps west of these Forgotten Pools.\n\nDefeat him, then return to me.", objectives = "Slay Barak Kodobane and collect his head.", progress = "Hello, <name>. Do you have Kodobane's head for me?", completion = "Well done, <name>. Kodobane is just one strand of a tangled thread - there are other Kolkar leaders to kill elsewhere in the Barrens. Seek out my companions at the other oases if you wish to press the assault." }
WordHunterWoW_QuestEN[851] = { title = "Verog the Dervish", description = "Verog may be hard to find, but judging by the info you gathered, his mate Wyneth is always in his command tent just west of here. If we kill her, Verog will come running.\n\nRegthar sent us here to scout, but he also said we should seize any opportunity to upset the centaur chain of command if we can. Lure out Verog and kill him!", objectives = "Kill Wyneth in order to lure out Verog the Dervish, then slay him and grab his head.", progress = "Did you find Verog, <name>?", completion = "You did it! That'll really upset the balance of power down here. Verog left no clear successor, so I expect this crew of brutes will fall on each other like hungry dogs. I'll stay here and keep an eye on what happens next.\n\nVerog answered directly to the Kolkar Chief - killing him is a good start, but there's more work to be done." }
WordHunterWoW_QuestEN[852] = { title = "Hezrul Bloodmark", description = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him. Bring me Hezrul's Head, and I will mount it from this outpost, so that they may know fear.\n\nHezrul leads his people from the Lushwater Oasis, to the south.", objectives = "Slay Hezrul Bloodmark and collect his head.", progress = "Is Hezrul defeated, <name>?", completion = "I commend you, <name>. These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless.  In defeating them, your valor is proven." }
WordHunterWoW_QuestEN[853] = { title = "Apothecary Zamah", description = "I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.\n\nShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.\n\nDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.", objectives = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.", progress = "You have something from Apothecary Helbrim?", completion = "Ah, the spores from the Barrens that Helbrim was gathering.  He garnered your aid in delivering them?  Good.\n\nAnd the emulsion is still potent, so you must have wasted no time in the delivery.  Well done, <class>." }
WordHunterWoW_QuestEN[854] = { title = "Journey to the Crossroads", description = "I have foreseen your arrival, young <class>. Though perhaps you are not so young anymore.\n\nI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.\n\nIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.", objectives = "Speak with Thork at the Crossroads in the Barrens.I have foreseen your arrival, young <class>. Though perhaps you are not so young anymore.\n\nI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.\n\nIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.", completion = "It is good to see that more of our <race> allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you." }
WordHunterWoW_QuestEN[855] = { title = "Centaur Bracers", description = "The centaur leadership relies on a core of trusted, disciplined warriors to keep the others in line. If we reduce their numbers, the Kolkar will have no might with which to support their rage. And so, I have a bounty task for you.\n\nAround the Lushwater Oasis to the south, slay Kolkar Marauders and Stormseers to collect their bracers. Return when you have a heap of these trophies and the Horde will reward you well.", objectives = "Collect 10 Centaur Bracers from Kolkar Marauders and Stormseers.", progress = "How goes your hunting, <name>?", completion = "Nicely done. I'm sure you've struck fear into the surviving centaurs, <name>. With their greatest warriors slain, they will either stop their advances or lash out at us in a foolhardy strike.\n\nI hope for the latter." }
WordHunterWoW_QuestEN[857] = { title = "The Tear of the Moons", description = "The power was mine! In my very hands! And I want it back! Back I say!\n\nThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.\n\nIt should have been mine! Mine I say!\n\nGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!\n\nOthers wanted it and they had to be stopped! That fiend Twinbraid drove me off.\n\nNow I want it back. Back I say!", objectives = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.", progress = "Where is the Tear of the Moons? I need it now! Need I say!", completion = "At last, the power is mine again! Mine I say!" }
WordHunterWoW_QuestEN[858] = { title = "Ignition", description = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.\n\nWe need to get out of here on the double! Search the upper level of the derrick, Supervisor Lugwizzle should have a key for this shredder.\n\nHelp me out here!", objectives = "Get the Ignition Key from Supervisor Lugwizzle.", progress = "Quick, we need to get out of here before someone gets suspicious!", completion = "Yep, this looks like the right key. Let me just make sure I know how to work this thing...\n\nHmm... rotation control... This regulates speed and stability... fine arm movement control. Just look at this! I can't believe the Venture Company could design something this much better than ours. I've got to get this back to the outpost!" }
WordHunterWoW_QuestEN[860] = { title = "Sergra Darkthorn", description = "If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.\n\nSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.\n\nSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.", objectives = "Speak with Sergra Darkthorn at the Crossroads.If you wish to walk the hunter's path, then your journey leads to the Barrens. Its beasts are strong-willed and fierce. You will learn much by hunting there, and your spirit will grow.\n\nSpeak with Sergra Darkthorn. She will be your first guide in the Barrens.\n\nSergra is at the Crossroads. To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks. And have care as you travel--the Barrens holds great danger for the unprepared and unwary.", completion = "You want to hunt in the Barrens?\n\nYour eyes are eager, and young.  They're not yet squinted from tracking your prey across this land's dry plains.\n\nBut worry not. We'll toughen your body and your mind.  And we'll teach you that there is more to hunting than finding and killing your quarry.\n\nPrepare yourself.  Your journey begins.  Now." }
WordHunterWoW_QuestEN[861] = { title = "The Hunter's Way", description = "You are eager to explore, I can tell.  I too had the lust to wander, once...\n\nWander, and hunt.  For hunting is a tauren's greatest honor.\n\nIf you truly wish to follow the ways of the hunter, show me your skill and resolve. Bring me the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young <class> on the path of the hunt.", objectives = "Collect 4 Flatland Prowler Claws.", progress = "How goes the hunt, <name>?", completion = "Well done, young one." }
WordHunterWoW_QuestEN[862] = { title = "Dig Rat Stew", description = "A <class> like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long.\n\nTell you what, I'll fix you up a nice stew. Just need a few dig rats.\n\nSeems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats.\n\nYou can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!", objectives = "Bring 8 Dig Rats to Grub east of the Crossroads.", progress = "Whack enough dig rats yet, <name>?", completion = "Normally I don't like to eat these rodents when they're so.... so... ripe. Like to let them rot for a few weeks to really bring out the flavor. But you look so hungry.\n\nLet me fix you some Dig Rat Stew. Ah, there we go.\n\nHere you go!" }
WordHunterWoW_QuestEN[863] = { title = "The Escape", description = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?", objectives = "Protect Wizzlecrank and the stolen goblin shredder on the way out of the Sludge Fens.", completion = "He wrecked it!?\n\n<Sputtervalve mutters angrily to himself before continuing>.\n\nHopefully we'll be able to get something of value from the wrecked shredder prototype... my business depends on it! I'll start tearing that sucker apart and we'll see what makes it tick.\n\nOh, let me give you something for your trouble, too." }
WordHunterWoW_QuestEN[864] = { title = "Return to Apothecary Zinge", description = "\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"\n\nThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.", objectives = "Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.", progress = "Welcome back.  At least, welcome back if you have returned with a sealed testing kit.  Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.", completion = "I will analyze this data immediately.  Perhaps Keever's insanity will prove to be my genius after all.\n\nAs for you...  you are useful to me, and I reward quite well those who remain useful.  Take this item, this coin, and most importantly my thanks along with them.\n\nCheck back with me from time to time - I wager that our working together on this project is not at an end." }
WordHunterWoW_QuestEN[865] = { title = "It's Gotta be the Horn", description = "The raptors of the Barrens are smarter than raptors in other lands. I think all those smarts are hiding in their horns! If so, then I could grind their horns into powder and use it to make \"smart drinks.\" I'll make a fortune!\n\nHere's where you come in: I want the horn from the smartest raptor around. \"King Reaperclaw\" leads a whole pack of intelligent raptors up on the bluffs north of Ratchet. Bring me his horn! And don't get ripped to ribbons like everyone else I've sent!", objectives = "Acquire King Reaperclaw's Horn.", progress = "Did you get King Reaperclaw's horn, <name>? I need to test my first smart drink!", completion = "Great, you got it! Let's grind this up and mix it with some wine, and..." }
WordHunterWoW_QuestEN[866] = { title = "Root Samples", description = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.", objectives = "Collect 8 Root Samples from herbs around North Barrens.", progress = "Hello, <name>.  Did you get those root samples?", completion = "Yes yes, these are very nice!  I will grow specimens from these roots and study them.  I hope to find new properties from them.  Hidden, valuable properties...!\n\nAnd don't worry -- if I do then you'll be the first to know.  Because I'll need someone to gather more!" }
WordHunterWoW_QuestEN[867] = { title = "Harpy Raiders", description = "Since you're here, {class}, perhaps you can help me with a small problem. The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nThe most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nTake out Witchwing harpies of any kind in the Northwest and bring me 6 Witchwing Talons. That should be a good start...", objectives = "Collect 6 Witchwing Talons from Witchwing harpies.", progress = "Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons.", completion = "Oh, these are nice. Real nice... Good job, <name>. I look forward to seeing more of your work in the future." }
WordHunterWoW_QuestEN[868] = { title = "Egg Hunt", description = "Hey, <name>. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.\n\nOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.\n\nTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.", objectives = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.", progress = "Be careful with the eggs you find, <name>. If they break, they be no good to me.", completion = "You please me, <name>. The eggs and the tool. Well done.\n\nAnd for your reward..." }
WordHunterWoW_QuestEN[869] = { title = "To Track a Thief", description = "Animal tracks surround the wreckage, tracks made by enormous curved claws. They appear to be raptor tracks.\n\nYour first instinct is that raptor-riders assaulted the caravan, but the impressions aren't deep and there are no non-animal tracks to be seen.\n\nThe tracks head northeast of here toward the east side of Thorn Hill. The answer to this mystery must lie in its shadow.", objectives = "The tracks lead to the east side of Thorn Hill. Follow them and see what you find.", completion = "Before you lies an entire community of raptors, ducking in and out of hovels, snarling at one another, and working together to construct primitive huts. Collections of shiny things surround their nests. Mystery solved!" }
WordHunterWoW_QuestEN[870] = { title = "The Forgotten Pools", description = "Have you felt the tremors, {class}? Something has cleaved this land in two. But we druids can sense other tremors, as well.\n\nLife is stirring in lands once dry and lifeless. The oases around the Crossroads are suddenly blooming. I can sense a power leaking its way to the surface, but from where? Is it related to the disaster that shattered the Barrens?\n\nWe must find the source. Travel to the Forgotten Pools, northwest of the Crossroads. Search its waters for a source of power, then return here.", objectives = "Search the bottom of the Forgotten Pools northwest of the Crossroads.", completion = "You found a fissure in the earth, with power emanating from it? Strange. Something is causing that oasis to bubble over suddenly with life.\n\nCome, <class> - there is something else I'd like you to investigate with me." }
WordHunterWoW_QuestEN[871] = { title = "In Defense of Far Watch", description = "All the quilboars are our enemies, {name}. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply caravans that roll through here from Orgrimmar. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart just south of here, where they've been raiding our camps near the river. Seek them out, and slay them.", objectives = "Kill 8 Razormane Plunderers and 3 Razormane Hunters.", completion = "You have done well, <name>. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored." }
WordHunterWoW_QuestEN[872] = { title = "The Far Watch Offensive", description = "Pigmen running amok right on the border of Durotar? Not on my watch! It is as they say, {name}: The best defense is crushing all who oppose you.\n\nOne of my scouts followed the quilboar after the last caravan raid, so we know where to strike. Kreenig Snarlsnout is the mastermind behind the attacks along the river. Crush him, {class}. Defeat him and disembowel his forces so that the attacks on this camp cease.\n\nSearch for a quilboar-infested cavern along the river, just south of our stables.", objectives = "Kill 5 Razormane Defenders, 5 Razormane Thornweavers, and Kreenig Snarlsnout. Take Snarlsnout's Tusk.", progress = "Cut off the head of their leader, and chaos ensues, <name>. Learn this lesson well. It will aid you in the future.", completion = "Well done, <name>. Without Kreenig to orchestrate the raids, my grunts should be able to keep Far Watch secure. Your people should be proud to count you among them." }
WordHunterWoW_QuestEN[873] = { title = "Isha Awak", description = "The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.\n\nBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.\n\nIf you are ready, then swim out and search for Isha Awak, the Deep Doom.\n\nHis spirit dwells in his heart, and to hear its beat is to know your fate.", objectives = "Bring the Heart of Isha Awak to Mahren Skyseer.", progress = "Fear not the waters, <race>.", completion = "You now are one with Isha Awak, <name>.  His spirit is with you.  He lurks in your eyes...\n\nEyes that, one day, will learn to see." }
WordHunterWoW_QuestEN[874] = { title = "Mahren Skyseer", description = "You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway <him/her>.\n\nNot even the sea.\n\nFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.\n\nBut be wary in your search for her, for the Barrens' coast is held by humans.", objectives = "Speak with Mahren Skyseer.You have hunted the beasts of the Barrens. Your spirit is strong. But a hunter must always be prepared. A true hunter can stalk prey down any path. Mountains and swamps will not sway <him/her>.\n\nNot even the sea.\n\nFind my sister, Mahren. She hunts the great water beasts along the coast. She will be your teacher in their ways.\n\nBut be wary in your search for her, for the Barrens' coast is held by humans.", completion = "My brother sent you, did he?  Then you must have proven yourself to him.  If you have earned the respect of Jorn, then you have my respect as well.\n\nAre you ready to tread farther down the hunter's path?" }
WordHunterWoW_QuestEN[875] = { title = "Harpy Lieutenants", description = "The only way to stop the harpy raiders is to destroy their chain of command. The harpies are led by fearless lieutenants, Witchwing Slayers. If the Slayers fall, the rest will follow.\n\nGo to the Dry Hills and cut down the Witchwing Slayers. Make sure they die painfully, {name}. We want those harpy wenches to know the idiocy of picking fights with the Horde.", objectives = "Kill 6 Witchwing Slayers in the Dry Hills of the Northern Barrens.", progress = "Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.", completion = "Excellent work my friend. I think you'll go far within the Horde." }
WordHunterWoW_QuestEN[876] = { title = "Serena Bloodfeather", description = "The harpies you've killed mentioned their matron, Serena Bloodfeather. Judging from their vile hatred toward the Horde, she must hold some kind of deep-seated grudge. You decide to hunt down Serena Bloodfeather and end matters once and for all.", objectives = "Slay Serena Bloodfeather and collect her head.", progress = "You're not getting anything until I see Serena's head.", completion = "HA! Well done, <name>! Very well done... I wasn't sure you were up to the task, but you've proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well." }
WordHunterWoW_QuestEN[877] = { title = "The Stagnant Oasis", description = "Can what's happening to the south happen here? Judging by what you found at the Forgotten Pools, these oases may be the key. Let's perform an experiment.\n\nHere, take these seeds I've collected from the summit here. They are dead and infertile, but carry them down to the Stagnant Oasis just below us. If there is a fissure there, then place the seeds within it... and observe. Report your findings back to Tonga at the Crossroads.", objectives = "Use the dried seeds to investigate the fissures in the Stagnant Oasis.", progress = "Did Jerrik have any ideas? You look like you've been rummaging around in the mud...", completion = "Your findings are amazing! Jerrik was wise to send you there. We now know that whatever rests under these oases can create life from nothing! No doubt this is causing the havoc to the south, but my primary concern right now is preserving the balance up here.\n\nWe must study this more..." }
WordHunterWoW_QuestEN[878] = { title = "Tribes at War", description = "You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.\n\nIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.", objectives = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.", completion = "Yes, yes... filled with joy because finally <snort> the Bristleback know my tribe's pain, <race>. That is how I should feel, but that  is not the case.\n\nYou aid your people and they honor you. Mangletooth aids his people, and what do they do? They turn their backs on him. They forget him and leave him to rot in cage!\n\nI aid them even from locked behind bars and they send no one to save me!" }
WordHunterWoW_QuestEN[879] = { title = "Betrayal from Within", description = "Three of my tribe came out of the Kraul to lead the raids against the Horde, <race>. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>\n\nNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, <race>, like they have killed me.", objectives = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.", progress = "How goes your hunt, <race>? \n\nThork thinks he knows the truth about who leads the raids against his people,  but he shall learn how wrong he is if you are successful.\n\nMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing.", completion = "It is done then. Better it ends this way, says Mangletooth. <snort> They should have <snort> made sure I was dead when they turned their backs on me instead of leaving <snort> me here in this forsaken cage.\n\nThere is but one task left for you to finish, <race>." }
WordHunterWoW_QuestEN[880] = { title = "Altered Beings", description = "It will be important to study both plant and animal life impacted by the oases and the unusual energies you've discovered. The Stagnant Oasis below us is home to a species of snapjaw turtles. Recently their population has exploded. Moreover, the once peaceful animals are growing aggressive, as I learned the hard way before trekking up here.\n\n<Jerrik holds up a bandaged finger.>\n\nI suspect they've been altered by the oases. Collect their shells and take them to Tonga at Crossroads for further study. ", objectives = "Collect 6 Altered Snapjaw Shells from Snapjaws in the Stagnant Oasis.", progress = "What else have you brought me?", completion = "Thank you, <name>. Studying the beasts of an area can tell much about the area itself. We shall see what tale these shells tell, and possibly unravel the mystery of what's happening in the barrens.\n\nPlease accept my gratitude for your aid... and perhaps you can use these coins. I find that I do not need them." }
WordHunterWoW_QuestEN[881] = { title = "Echeyakee", description = "Whitemist, or 'Echeyakee' in the tauren tongue, is the king of the savannah cats. He hunts with such stealth, they say he's like a thin, white mist on the earth. He kills so fast his prey have no time for fear or pain.\n\nThe tauren say he is both mercy and death.\n\n{name}, I now set you on the path to hunt Echeyakee. His lair is just northwest of here, on the north side of a small mountain, among the bones of giant Kodo.\n\nGo. Blow this horn when you reach his lair. Blow the horn, and he will come.", objectives = "Blow your horn at Echeyakee's lair to summon him. Slay or subdue him.", completion = "You've beaten Echeyakee, and though his days of hunting are over... his spirit is with you. He will show you the strength found in subtlety, and the honor in mercy.\n\nI underestimated you, <class>. The Horde is fortunate to have you in its ranks." }
WordHunterWoW_QuestEN[882] = { title = "Ishamuhale", description = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.\n\nAnd you will learn of his nature, <name>, for your path now follows the taloned tracks of Ishamuhale.\n\nBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.\n\nBe ready when he comes.", objectives = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.", progress = "<name>, have you bested Ishamuhale?", completion = "This fang is merely a token, but what it represents is profound.\n\nIshamuhale's strength is in you, <name>.  May you use it with temperance.  That is your burden.\n\nThat is your honor." }
WordHunterWoW_QuestEN[883] = { title = "Lakota'mani", description = "The Hoof of Lakota'mani is a symbol of the strength of the great kodo.", objectives = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.", progress = "<name>, when you approached I saw a new power in your stride.  Tell me -- has your spirit met with the great Lakota'mani?", completion = "Lakota'mani is called \"Earthshaker\" in our language, and his steps are like gathered thunder.  He is with you now, and his courage mingles with yours.  Together there is no conflict you cannot face.\n\nWalk tall, <name>.  Walk tall, Earthshaker." }
WordHunterWoW_QuestEN[884] = { title = "Owatanka", description = "When touched, sparks fly from the tailspike of Owatanka.", objectives = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.", progress = "<name>, there is a new power behind your eyes!  You have met with the mighty Owatanka, have you not?", completion = "The thunder lizard Owatanka is called \"Bluebolt\" by the tauren, for within him resides a speed that belies his size.  It is said that lightning struck Bluebolt long ago and, fed from the sky's rage, the great beast's energy is without limit.\n\nMay his energy flow through you, <name>.  For you now keep pace with Owatanka." }
WordHunterWoW_QuestEN[885] = { title = "Washte Pawne", description = "The feather of Washte Pawne is painful to the touch.", objectives = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.", progress = "There is new resolve within you, <name>.  A resolve born from pain...\n\nAre you burdened with the death of Washte Pawne?", completion = "The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.\n\nBut Washte Pawne, called \"Spirit Biter\" in Taurahe, can bring neither... or both.\n\nThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs.  The sting you felt is the pain of regret.\n\nBut I can see you have conquered this.  You have learned that regret turns to wisdom, and that through pain one gains strength.\n\nYou have learned much, <name>." }
WordHunterWoW_QuestEN[886] = { title = "The Barrens Oases", description = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, <name>, for the Barrens is a harsh land.", objectives = "Speak with Tonga Runetotem at the Crossroads.The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga. He will be at the Crossroads. To reach there, take the road east out of Bloodhoof village. Enter the Barrens, then turn north when the road forks. Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, <name>, for the Barrens is a harsh land.", completion = "My brethren in Thunder Bluff were wise to send you, young <class>.  For the mystery of the Barrens is one that I alone cannot unravel.\n\nWith your aid, let us hope we can find answers to our questions." }
WordHunterWoW_QuestEN[887] = { title = "Southsea Freebooters", description = "Gazlowe promised me a promotion if I can help him with Ratchet's pirate issues. The problem is these new buccaneers that sailed in and took over Fray Island, south of here. They're not just after our goods - they've got grudges to settle! The other night they even went after one of our war galleons.\n\nI've got plans in the works to deal with the situation, but Gazlowe wants to see quick results. Head over to Fray Island and start lopping off some heads, will you?", objectives = "Kill 8 Southsea Cutthroats or Privateers on Fray Island.", completion = "Superb! Gazlowe will reward me handsomely for this. And I'll reward you. Less handsomely, of course. A goblin's got to make a living, you know?" }
WordHunterWoW_QuestEN[889] = { title = "Spirit of the Wind", description = "", objectives = "Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.\n\nIt will not last long, but it should be enough to help you travel throughout the Barrens.", progress = "Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.\n\nIt will not last long, but it should be enough to help you travel throughout the Barrens.", completion = "Good. Go with Agamaggan's spirit as your guide, <race>. Return to me if you desire more of Agamaggan's magics." }
WordHunterWoW_QuestEN[890] = { title = "he Missing Shipment", description = "I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?\n\nHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.", objectives = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.", progress = "Wares to send on the next ship, <name>?", completion = "Ah, Gazlowe sent you, did he? Just a moment, let me take a look here and check my own logs and make sure I didn't have Gazlowe's shipment sent to the wrong place.\n\nBet he's waiting for those boots from Drizzlek..." }
WordHunterWoW_QuestEN[891] = { title = "A Captain's Vengeance", description = "Yet another ship from my fleet has been lost to those overzealous humans from Theramore!\n\nTheir new Rear Admiral has parked himself right off the coast here. He's boarding or sinking any vessel that doesn't heave-to at his whim.\n\nTravel south along the Merchant Coast to his camp. Bring me the medals of the marines and deck hands. Execute his top Lieutenants, Pyre and Buckland. Lay waste to them as they have laid waste to my fleet!", objectives = "Collect 10 Theramore Medals from Theramore Marines and Deck Hands. Kill Lieutenants Pyre and Buckland.", progress = "Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.", completion = "I see you've made the righteous Rear Admiral suffer as I have. Perhaps this blow will weaken the resolve of Northwatch. His supply of fresh recruits seems inexhaustible, but the loss of his top Lieutenants will weaken him for some time." }
WordHunterWoW_QuestEN[892] = { title = "he Missing Shipment", description = "Everything looks square from my records, <name>. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.\n\nNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.", objectives = "Return Gazlowe's Ledger to Gazlowe in Ratchet.", progress = "So, what did Dizzywig have to say?", completion = "No dice, eh? I guess it must have been the Freebooters then... Dizzywig's on the level, I'm sure he wouldn't cheat me like that. After all, he is on the payroll.\n\nLooks like I've got some goods to get back, <name>. What do you say?" }
WordHunterWoW_QuestEN[893] = { title = "Weapons of Choice", description = "The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.\n\nIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!", objectives = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.", progress = "I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.\n\nI have had more menial tasks, and I do so willingly if it aids the orc people.", completion = "Excellent, excellent specimens indeed.\n\nThe quilboar are further along than I had expected.\n\nHere, <class>, take this and get out of my way. I'd better take a closer look at these weapons. We may have underestimated our enemy, and that's the kind of mistake we can't afford to make." }
WordHunterWoW_QuestEN[894] = { title = "Samophlange", description = "The Venture Company have a small research facility west of here, just past the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", objectives = "Access the control console at the Venture Company research site.\n\nProvided item:", completion = "A variety of buttons, levers, and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel." }
WordHunterWoW_QuestEN[895] = { title = "WANTED: Cap'n Garvey", description = "WANTED!\n\n    \"Cap'n\" J. Garvey of\n     the Maiden's Dagger\n\nCharged with piracy on the open seas, kidnapping, extortion, arson, slavery, et al. Garvey recently arrived in these waters leading a crew of Southsea Freebooters and was last seen assaulting Fray Island. Bring proof of death in an identifiable condition!\n\n-- Gazlowe", objectives = "Bring the head of Cap'n Garvey to Gazlowe in Ratchet.", progress = "What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?", completion = "Ahhhh! That sort of business. You know, these pirates are always looking out for their own. No sooner is Baron Longshore in a stockade than this Garvey fellow comes looking for vengeance... You don't suppose anyone will come looking to avenge Garvey, do you? Maybe I should put you on retainer." }
WordHunterWoW_QuestEN[896] = { title = "Miner's Fortune", description = "Hey <race>, you interested in treasure? I knew that would get your attention.\n\nWord from the river dock here is that one of the miners in the Venture Company's Boulder Lode mine just northeast of here discovered an emerald the size of your fist.\n\nI know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale. You in?", objectives = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers.", progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut - fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, <name>." }
WordHunterWoW_QuestEN[897] = { title = "The Harvester", description = "This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.", objectives = "Bring the Harvester's Head to Jorn Skyseer.", progress = "You seemed troubled, <name>.  How go your lessons in the Barrens?  Did you find something that disturbs you?", completion = "I can tell nothing of the nature of this beast, for its spirit has fled.  But as you guessed, it does not belong in the Barrens.  I fear it may herald a grim future for our people...\n\nBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature." }
WordHunterWoW_QuestEN[898] = { title = "Free From the Hold", description = "Finally! Someone to rescue me!\n\nI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.\n\nMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.\n\nEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.", objectives = "Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.", completion = "And to think, we thought Firebough was long dead!\n\nYour heroics have earned you a place of honor with the Thalo'dan Privateers, <name>." }
WordHunterWoW_QuestEN[899] = { title = "Consumed by Hatred", description = "They murdered my wife. They burned my homestead. Since that awful night I have traveled these lands, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched.\n\nYou, {class} - you could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.", objectives = "Collect 30 Quilboar Tusks.", progress = "The quilboar will pay for this, <name>. I swear it.", completion = "<class>, you take my task seriously, and for that I thank you.\n\nAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves." }
WordHunterWoW_QuestEN[900] = { title = "Samophlange", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", objectives = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off." }
WordHunterWoW_QuestEN[901] = { title = "Samophlange", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", objectives = "Get the Console Key from Tinkerer Sniggles.", progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal." }
WordHunterWoW_QuestEN[902] = { title = "Samophlange", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", objectives = "Return the Samophlange to Sputtervalve at Nozzlepot's Outpost in Northern Barrens.", progress = "Oh, you're back, <name>! Do you have the samophlange?", completion = "This is... er... interesting... yes. A device this complex is best analyzed by a team of skilled engineers in a clean room, painstakingly reverse engineering each component in a controlled environment.\n\nBut who has that kind of time?\n\nLet's just fire this thing up and see what it does..." }
WordHunterWoW_QuestEN[903] = { title = "Hunting the Huntress", description = "If you want to really demonstrate your bravery to me, let me send you after something that really bites. The savannah huntresses of the Barrens are as sly as they come. Tough, resourceful, quick... and deadly. They've been hassling our scouts recently around the outskirts of the town, especially to the northeast.\n\nBe wary as you hunt them, {name}, or you may find yourself no longer the predator, but instead the prey.", objectives = "Collect 5 Huntress Claws from Savannah Huntresses.", progress = "How goes your hunt, <name>?", completion = "Ah, I see you've been busy. I hope you learned a lot from this prey, <name>. You'll need the strength and cunning of beasts like these to serve my beloved Horde." }
WordHunterWoW_QuestEN[905] = { title = "Into the Raptor's Den", description = "The hunt deepens, {name}. Now you must find and defeat your prey within its lair.\n\nHunt the Sunscale raptors to the south, where they have built a warren amongst the hills just off of the road. Slay them and remove the feathers they wear. Place the feathers on the sunscale raptor nests to show their brethren you do not fear them!\n\nBe cautious, {class}. Raptors hunt in packs and will swarm you if you are not cautious.", objectives = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Sunscale Nests.", progress = "Have you been to the nests, <name>?", completion = "So you've been to the nests and placed the feathers of your prey within them. That took a fair portion of courage, no doubt about it.\n\nDo you feel a little tougher, <name>? Because you look tougher now then when you first came here.  I guess the Barrens is doing its job." }
WordHunterWoW_QuestEN[906] = { title = "Betrayal from Within", description = "Take Lok's head to Thork in the Crossroads, <race>. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>\n\nI will continue to bless you with Agamaggan's power for as long as I remain in this cage, <race>. Until then, farewell.", objectives = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.", progress = "Yes, what is it?", completion = "You found the Razormane leader and killed him yourself, <name>? Amazing.\n\nI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.\n\nI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, <name>." }
WordHunterWoW_QuestEN[907] = { title = "Enraged Thunder Lizards", description = "Now, <name>, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.\n\nYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.", objectives = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.", progress = "Are the thunder lizards defeated, <name>?", completion = "It is good to see you return with proof of victory.  And it is good to know you have done so with your bones unbroken." }
WordHunterWoW_QuestEN[908] = { title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n<name>, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." }
WordHunterWoW_QuestEN[909] = { title = "Baron Aquanis", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.Upon completion of this quest you will gain:", objectives = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." }
WordHunterWoW_QuestEN[910] = { title = "Down at the Docks", description = "I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!\n\nWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!Upon completion of this quest you will gain:", objectives = "Take your ward to the docks of Ratchet in the Barrens." }
WordHunterWoW_QuestEN[911] = { title = "Gateway to the Frontier", description = "They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there <name>!\n\nWould you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!Upon completion of this quest you will gain:", objectives = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale." }
WordHunterWoW_QuestEN[912] = { title = "Stonesplinter Trogg Disguise", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[913] = { title = "Cry of the Thunderhawk", description = "The thunderhawk, <name>, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.\n\nDo this, and your time with me will near its end.", objectives = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.", progress = "Is it done? Have you slain the thunderhawk?", completion = "You, like the thunderhawk, should be proud.  You have bested every foe we set you before, and have done so with strength, courage and honor.\n\nBut your path, <name>, continues.  In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.\n\nNow, it is time to move on." }
WordHunterWoW_QuestEN[914] = { title = "Leaders of the Fang", description = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, <name>.  You will find them lurking deep within the Wailing Caverns.", objectives = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", progress = "Memories of my nightmares haunt me, <name>.  Have you defeated the leaders of the fang and acquired their gems?", completion = "You have done it, <name>.  You killed the leaders of the Druids of the Fang.  My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.\n\nI thank you, <name>.  I thank you for myself, for the druids of Thunder Bluff, and for the land." }
WordHunterWoW_QuestEN[915] = { title = "You Scream, I Scream...", description = "ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!\n\nI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule's Strawberry Ice Cream on top??!?!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule's brand ice cream." }
WordHunterWoW_QuestEN[916] = { title = "Webwood Corruption", description = "I came to Shadowglen to study the webwood spiders that dwell in the Shadowthread cave. I was told that with Teldrassil's recent blessing, they should be far less aggressive. It seems I was mislead.\n\nI recently retrieved some of their venom sacs, and was disturbed to find a very unhealthy corruption in them. Suffice to say, I'm concerned what could occur if we let corrupted wildlife like this run rampant.\n\nI want you to reduce their population to buy some time.", objectives = "Kill 12 Webwood Spiders.", progress = "Did you gather the venom sacs, <name>?", completion = "Thank you, <name>.  When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders.  It is my belief that it will have properties linked to the recent growth of our new world tree." }
WordHunterWoW_QuestEN[917] = { title = "Webwood Egg", description = "Actually, come to think of it, maybe you can help me a bit more. I came here to retrieve a webwood egg from deep inside the cave, but the spiders would have none of it. If you could retrieve the egg and bring it back to Dirania, we would both be very appreciative.", objectives = "Retrieve a Webwood Egg.", progress = "Have you been inside the Shadowthread Cave, <name>?  Did you find a spider egg?", completion = "Ah, very good.  I will have this egg and the venom transported to Darnassus, then return there when my studies are done here.  I expect to find out a great deal from these specimens, <name>.  You have been a great help to me." }
WordHunterWoW_QuestEN[918] = { title = "Timberling Seeds", description = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.\n\nSo it is disturbing to see how angry the timberlings are, particularly considering that things should be healing.\n\nI want to help hunt down the source.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?", objectives = "Retrieve 6 Timberling Seeds.", progress = "Do you have the seeds?  I am eager to plant them.", completion = "You got them. This is good! I'm hoping that careful study might lead me to understand where the timberling corruption stems from.\n\nI will plant these seeds in special soil I have prepared.  I believe the seeds will sprout into timberlings who are much more docile.\n\nPerhaps later you can see the results!" }
WordHunterWoW_QuestEN[919] = { title = "Timberling Sprouts", description = "Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.\n\nWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!", objectives = "Collect 10 Timberling Sprouts.", progress = "Hello, <name>.  Have you found any sprouts near the waters?", completion = "That's a lot!  I'm afraid they're spreading at a dangerous rate.  I hope I can solve the riddle of what is tainting them.\n\nThank you for your help, <name>.  The land is a cleaner place from your efforts." }
WordHunterWoW_QuestEN[920] = { title = "Tenaron's Summons", description = "<name>, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.\n\nWe may live long lives, but it's best you not keep him waiting too long.", objectives = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.<name>, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.\n\nWe may live long lives, but it's best you not keep him waiting too long.", completion = "Ah, <name>. I was hoping you'd be prompt in answering my summons. I have an important task that I would like you to perform." }
WordHunterWoW_QuestEN[921] = { title = "Teldrassil: Crown of Azeroth", description = "It is time for you to set out to seek your destiny, <name>. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.\n\nThere is a task you must perform. Go to the moonwell north of Aldrassil and retrieve a phial of its water. While there, you will witness a glimpse of our magics and learn of our past.\n\nWhen you are done there, bring the water to Tenaron Stormgrip. You will find him up the western ramp at the top of Aldrassil.", objectives = "Fill the Crystal Phial.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus." }
WordHunterWoW_QuestEN[922] = { title = "Rellian Greenspyre", description = "{name}, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid that resides at Wellspring Hovel, and when last we spoke he revealed his interest in my work with the Timberlings. He had some ideas himself, and he will appreciate a specimen seed to work with.\n\nThank you, {name}. I hope that, some day, you will see the fruit of my labors.\n\nYou will find Wellspring Hovel along the road heading west out of Dolanaar, on the way to Darnassus.", objectives = "Bring a Timberling Seed to Rellian Greenspyre at Wellspring Hovel.", progress = "Hello...\n\nAnd how may I help you?", completion = "Ah, a timberling seed?  I wanted to try growing one of these to help Denalan with his studies.\n\nBut I'm afraid I've discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent's taint. They are beyond my talents to repair.\n\nDenalan is very skilled with things that grow. He may find a cure for future timberlings. He may be their only hope." }
WordHunterWoW_QuestEN[923] = { title = "Mossy Tumors", description = "There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help. Those that wander Wellspring Lake to the north are the most tainted. They must be removed!\n\nDestroy the Timberlings you find there, and gather the mossy tumors growing upon them. Bring the tumors to me so that they may be burned.", objectives = "Retreive 5 Mossy Tumors.", progress = "Have you been to Wellspring Lake, <name>?  Have you been hunting the timberlings there?", completion = "Well done! These tumors are the symptom of the timberling's disease. They are filled with a poison that we must cleanse from our new land.\n\nI will dispose of these tumors. Thank you, <name>." }
WordHunterWoW_QuestEN[924] = { title = "The Demon Seed", description = "The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.\n\nI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.\n\nTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.\n\nAnd hurry--the stone's power will consume itself in time.", objectives = "Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.", completion = "Your task is complete.  You have destroyed the Demon Seed as Neeru bid.  But this is not the end...\n\nThe destruction of the Demon Seed sent waves of power through the ether, waves of staggering force.  I felt them, and I am sure other beings did as well.  Others who will wonder why their toy was broken...\n\nBut regardless of future troubles, I have something for you.  Neeru sent it as payment.  And he bid me thank you.\n\nSo, thank you." }
WordHunterWoW_QuestEN[925] = { title = "Cairne's Hoofprint", description = "They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!\n\nDo you know Cairne, <name>?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!\n\nPlease?Upon completion of this quest you will gain:", objectives = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward." }
WordHunterWoW_QuestEN[926] = { title = "Flawed Power Stone", description = "", objectives = "These stones are infused with magical energy, but purposefully flawed.  They are very unstable and once removed from the table they will consume themselves quickly.You will receive:" }
WordHunterWoW_QuestEN[927] = { title = "The Moss-twined Heart", description = "The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.\n\nPerhaps Denalan will want to see this heart.", objectives = "Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.", progress = "<name>!  You have something for me?", completion = "...What is this?  A timberling heart??  It's covered with a foul moss!\n\nThank you for bringing this to me, <name>.  I will examine the heart and, if fortune shines, determine the nature of the moss about it." }
WordHunterWoW_QuestEN[928] = { title = "Teldrassil: Passing Awareness", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, <name>. There are dangerous beasts in the forests of late.", objectives = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", progress = "Greetings, <class>. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.\n\nI think we'd best get started." }
WordHunterWoW_QuestEN[929] = { title = "Teldrassil: The Refusal of the Aspects", description = "Let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.\n\nTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. Pay heed to the lessons of the moonwells, lest we find ourselves furthering our shortcomings.", objectives = "Fill the Jade Phial.", progress = "Hello again, <name>. Have you completed your task?", completion = "It is only natural that our race, once immortal and revered, would struggle with regarding ourselves in the humbled manner that we likely should. We must remember to embrace our connection with nature, and with Elune, and push aside our mortal shortcomings." }
WordHunterWoW_QuestEN[930] = { title = "The Glowing Fruit", description = "Hanging from beneath the fronds of this glowing plant is a large, round fruit.\n\nDenalan would want to study this fruit, you are certain.", objectives = "Bring the glowing fruit to Denalan at Lake Al'Ameth.", progress = "<name>, you look like you have something to tell me.  Do you have news concerning the timberlings?", completion = "You found this on Teldrassil?  Intriguing... this fruit is exotic.  Perhaps its seeds were brought here from far off.  Perhaps even as far as Azeroth!  And there's something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.\n\nThank you, <name>.  Now if you'll excuse me, I must study this further..." }
WordHunterWoW_QuestEN[931] = { title = "The Shimmering Frond", description = "The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.\n\nYou believe that Denalan would want a specimen of this.", objectives = "Bring a Shimmering Frond to Denalan. He can usually be found at Lake Al'Ameth, but sometimes travels to Wellspring Hovel.", progress = "You have something for me?", completion = "Where did you get this?  I haven't seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!  It's amazing that a specimen made its way to Teldrassil.  And it's grown to such a size!\n\nThank you, <name>.  Forgive my shortness of words, but there is a test I would like to perform on this frond..." }
WordHunterWoW_QuestEN[932] = { title = "Twisted Hatred", description = "I must warn you, {name}, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.\n\nHe is called Lord Melenas. He resides in the nearby cave of Fel Rock, to the north, where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.\n\nYou must find him within his nearby cave just to the north of here, and bring me his head.", objectives = "Retrieve the head of Lord Melenas.", progress = "Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, <name>. His continued existence is an embarrassment to us all.", completion = "With Lord Melenas laid to rest I can finally move on to other matters. Thank you, <name>." }
WordHunterWoW_QuestEN[933] = { title = "Teldrassil: The Coming Dawn", description = "There is one last moonwell that I would like you to visit.  It is directly south of here, on the shores of the Pools of Arlithrien. Be wary as you seek out the well, and keep your weapons close at hand. I sense a growing corruption from the boughs of southern Teldrassil.\n\nWhen you have the water, I want you to bring it to a familiar face that you'll see at the pools. She wishes to battle the corruption, and has asked for you personally.", objectives = "Fill the Tourmaline Phial.", progress = "It is good to see you again, <name>. I see you have succeeded in collecting the waters of the moonwells on behalf of Corithras Moonrage. I hope you have learned much along the way.", completion = "Indeed, I have spoken to Corithras on my way here, and he has gifted me with the waters you have been gathering. They may well prove useful sooner than we'd imagined.\n\nStrangely, the growing corruption we've felt is actually a good sign. Teldrassil has been burdened with this taint for a long time, and thanks to the blessing of the dragon aspects, only now is it coming to the surface in a form that we might strike against." }
WordHunterWoW_QuestEN[934] = { title = "Crown of the Earth", description = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.Upon completion of this quest you will gain:", objectives = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar." }
WordHunterWoW_QuestEN[935] = { title = "The Waters of Teldrassil", description = "Our tasks are done here for now. This water proved to be of great importance, but it wasn't originally meant for me. Go ahead and bring it back to Corithras at the crossroads, I'm sure he'd like you to deliver it to its original destination.", objectives = "Bring the Filled Vessel to Corithras Moonrage at the crossroads in front of Darnassus.", progress = "It is good to see you again. I sense that Tarindrella's task went smoothly with you by her side.", completion = "Thank you for returning to me so swiftly. I have but one last task to ask of you. Shall we?" }
WordHunterWoW_QuestEN[936] = { title = "Assisting Arch Druid Runetotem", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", objectives = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", completion = "Greetings, <class>; I am glad you are interested in assisting our research. There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous. Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before." }
WordHunterWoW_QuestEN[937] = { title = "The Enchanted Glade", description = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.\n\nWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.\n\nIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.", objectives = "Acquire 6 Bloodfeather Belts.", progress = "Their slashing talons and piercing beaks may prove a difficult match for your own abilities, <name>, but I have faith that you will not fail in this task.", completion = "I am impressed by what you have accomplished here in so short a time, <name>. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you." }
WordHunterWoW_QuestEN[938] = { title = "Mist", description = "The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.\n\nShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.", objectives = "Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.", progress = "Mist... It was my fault! The witches caught me off guard... I should not have let them take you...", completion = "Oh, thank you, <name>! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude." }
WordHunterWoW_QuestEN[939] = { title = "lute of Xavaric", description = "You study the simple wooden flute you picked up after defeating Xavaric.\n\nThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...\n\nYou shake your head, sure that your mind is playing tricks on you.\n\nIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.", objectives = "Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood.", progress = "What is it, <class>? You look concerned.", completion = "I sense the suffering of ancient ones, <name>...\n\nHolding these items is almost unbearable..." }
WordHunterWoW_QuestEN[940] = { title = "Teldrassil", description = "The forest whispers of your feats of valor, <name>. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.\n\nDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.", objectives = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.", progress = "Hmm... You come with the spirit of the forest strongly within you, <class>. What business do you have with the Arch Druid of the Kaldorei?", completion = "I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.\n\nI fear my work on Teldrassil shall never be completed, and our immortality never restored.\n\nNonetheless, you have done the Oracle Tree's task well, and should be rewarded for your diligence." }
WordHunterWoW_QuestEN[941] = { title = "Planting the Heart", description = "I have removed that foul moss from the heart, but it remains tainted...\n\nTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.", objectives = "Plant the Tainted Heart in Denalan's Planter.", progress = "This planter is filled with soil, specially prepared by Denalan.", completion = "You place the heart within the planter, and it quickly digs itself in!\n\nA few seconds later it wriggles back out, cleansed.  It pulses slightly... beckoning for you to take it." }
WordHunterWoW_QuestEN[942] = { title = "The Absent Minded Prospector", description = "This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.\n\nLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.\n\nThe ship to Menethil departs from Stormwind.", objectives = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.", progress = "What ya got there, friend?", completion = "Oh my! You say this came from the distant lands of Kalimdor?\n\nAmazing! Simply amazing!" }
WordHunterWoW_QuestEN[943] = { title = "The Absent Minded Prospector", description = "Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.\n\nWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.\n\nBring me both the Stone of Relu, and the original fossil he holds.", objectives = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.", progress = "With the Stone of Relu I will be able to release the hidden secrets of my fossil as well as Remtravel's fossil from Darkshore, <name>.", completion = "Most excellent, <name>!\n\nNow to see if I can use the stone to decipher the powers of the fossils." }
WordHunterWoW_QuestEN[944] = { title = "The Master's Glaive", description = "It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.\n\nThe Master's Glaive, to the south, is a place where such an old lord fell.\n\nGo there and look for more Twilight's Hammer cultists.\n\nTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.", objectives = "Gather information, then use the Phial of Scrying to create a Scrying Bowl. Use the bowl to speak with Onu.", completion = "The Twilight's Hammer is at the Master's Glaive?\n\nUnfortunate.\n\nThe old lord impaled by the glaive is long dead, but that does not mean slivers of his power do not still remain.\n\nThe Twilight's Hammer must be seeking this power." }
WordHunterWoW_QuestEN[945] = { title = "Therylune's Escape", description = "Help!\n\nI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!\n\nCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.", objectives = "Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe.", completion = "My sister was where??  Therylune doesn't mind getting herself dirty, but still!  That's a long way to wander, and the Master's Glaive is an unwholesome place...\n\nWell thank you, <name>.  It was very nice of you to let me know she's all right." }
WordHunterWoW_QuestEN[947] = { title = "Cave Mushrooms", description = "I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains.\n\nI would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore.\n\nPlease, <name>, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.", objectives = "Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.", progress = "Do you have my mushrooms, <name>?  Have you been to the cave?", completion = "Many thanks, <name>.  These mushrooms are fine specimens!\n\nAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?\n\nThe Ancients are wise, but I had hoped that, this time, they were wrong." }
WordHunterWoW_QuestEN[948] = { title = "Onu", description = "Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.\n\nThe Ancients are patient and wise, <name>.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.", objectives = "Speak with Onu at the Grove of the Ancients.Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you. The grove lies to the south, nestled near the mountains.\n\nThe Ancients are patient and wise, <name>. But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.", completion = "<name>.  You are here.\n\nGood.\n\nWe have matters...to discuss.  You and I." }
WordHunterWoW_QuestEN[949] = { title = "The Twilight Camp", description = "The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.\n\nSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.\n\nFor we must learn their intentions before a plan is made.", objectives = "Find a clue in the Twilight's Hammer camp at the Master's Glaive.", completion = "This book is hand printed in an ancient language, and illustrated by a master artist." }
WordHunterWoW_QuestEN[950] = { title = "Return to Onu", description = "Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.\n\nTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.", objectives = "Bring Onu the recovered Insane Scribbles.", progress = "<name>.  You return.", completion = "A chaotic, primal magic surrounds this parchment of scribbles.  I sense the work of the old ones in it.\n\nLet us hope it reveals the purpose of the Twilight's Hammer in Darkshore..." }
WordHunterWoW_QuestEN[951] = { title = "Mathystra Relics", description = "The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world.\n\nTravel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.", objectives = "Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.", progress = "<name>.  Has your rooting through the Ruins of Mathystra been fruitful?", completion = "Thank you.  These relics are from a time when Mathystra shone.  That once great bastion of the elves has faded, but shards of its magic remain.  Let us hope we can unlock the secrets of that place before our enemies...\n\nBe vigilant, <name>." }
WordHunterWoW_QuestEN[952] = { title = "Grove of the Ancients", description = "If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.\n\nYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.", objectives = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.", progress = "Ah. <class>. How may Onu assist you?", completion = "Ah. Thank you, <name>. It is strange, though. The Arch Druid always seems in such a hurry. The forest knows that all shall come to pass in the appointed time. Shan'do Stormrage understood that." }
WordHunterWoW_QuestEN[953] = { title = "The Fall of Ameth'Aran", description = "To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics.\n\nI was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled.\n\nPlease, if you can, venture to the ruins and decipher the tablets in my place.", objectives = "Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.", completion = "We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.\n\nThank you, <name>. With your help, my work here is finished, and I will be able to deliver a full report to the Circle." }
WordHunterWoW_QuestEN[954] = { title = "Bashal'Aran", description = "The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.\n\nEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.\n\nI would like you to investigate it.", objectives = "Find the source of the strange blue aura in the ruins of Bashal'Aran.The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.\n\nEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.\n\nI would like you to investigate it.", completion = "Ahh... To what could I possibly owe the exceedingly special honor of a <race> such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.\n\nBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment." }
WordHunterWoW_QuestEN[955] = { title = "Bashal'Aran", description = "If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.\n\nI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.", objectives = "Acquire 8 Grell Earrings for Asterion in Bashal'Aran.", progress = "Once I have the earrings, I will cast the spell to search for the whereabouts of the seal that binds me. For centuries I have thought on the freedom destroying the seal would bring to me... Perhaps those centuries have taken a toll upon my mind that I might never recover...", completion = "Indeed... The grells of Bashal'Aran do not possess that which I am searching... however they have come into contact with it recently. Recently... I would reckon that by your time, not mine. Recent for me stretches into the veil of the past, almost another Age..." }
WordHunterWoW_QuestEN[956] = { title = "Bashal'Aran", description = "If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.\n\nI feel strongly that this must be true, <name>. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.", objectives = "Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.", progress = "The pillars of this shrine are as the bars of a prison to me, <name>. No strength I still possess might break them, and no magic I wield might destroy them...\n\nFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...", completion = "It... it is hard for me to even believe that what I hold now is that which has held me for so long. Let us waste no time, <name>. When the seal is destroyed, I might walk the forests of the earth freely again." }
WordHunterWoW_QuestEN[957] = { title = "Bashal'Aran", description = "It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.\n\nBe wary in the ruins, <name>...", objectives = "Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.", completion = "I am freed, <name>! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.\n\nI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance." }
WordHunterWoW_QuestEN[958] = { title = "Tools of the Highborne", description = "<class>. A task I would ask of you.\n\nHave you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced.\n\nI have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.", objectives = "Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.", progress = "If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.", completion = "Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again." }
WordHunterWoW_QuestEN[959] = { title = "Trouble at the Docks", description = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?", objectives = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.", progress = "The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.\n\nIf you're brave enough and patient enough to seek out Mad Magglish and get that port back, I'll see to it you get a nice reward.", completion = "Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.\n\nThank you, <name>. Nicely done, I say!" }
WordHunterWoW_QuestEN[960] = { title = "Onu is meditating", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[961] = { title = "Onu is meditating", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[962] = { title = "Serpentbloom", description = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, <name>. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.", objectives = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.", progress = "I am eager to see if you can gather enough Serpentbloom from the Wailing Caverns. I've sent many to do my bidding but none have returned.", completion = "Ah, splendid specimens. You have done well, <name>." }
WordHunterWoW_QuestEN[963] = { title = "For Love Eternal", description = "In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya.\n\nI would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.", objectives = "Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.", progress = "With a great sorrow in my heart, I followed the Shan'do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.", completion = "Thank you, <name>. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief..." }
WordHunterWoW_QuestEN[964] = { title = "Skeletal Fragments", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, <name>.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", objectives = "Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "Kill many and kill often, <class> - we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, <name>!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder." }
WordHunterWoW_QuestEN[965] = { title = "The Tower of Althalaxx", description = "Hail, young <race>. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.\n\nTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.\n\nIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.", objectives = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.Hail, young <race>. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.\n\nTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.\n\nIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.", completion = "Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it." }
WordHunterWoW_QuestEN[966] = { title = "The Tower of Althalaxx", description = "A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.\n\nDelgren suspected such a company might be gathering at the tower, but did not know why.\n\nA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!", objectives = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.", progress = "Have you found any more of their scrolls? I should be able to piece together a larger picture of the cult if you can find them.", completion = "Many thanks, <name>. This should shed some light on this warlocks' gathering...\n\nHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.\n\nThere is no more time to delay. Warning must be delivered to Delgren immediately." }
WordHunterWoW_QuestEN[967] = { title = "The Tower of Althalaxx", description = "My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.\n\nDelgren must know of the cult's operations immediately.\n\nYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.", objectives = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.", progress = "You have some business with me, <class>?", completion = "If you don't mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let's see what he has to say...\n\nThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.\n\nAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies." }
WordHunterWoW_QuestEN[968] = { title = "The Powers Below", description = "Although terribly worn and scratched, the title of this book can still be read upon its cover:\n\nThe Powers Below\n\nInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.\n\nOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"\n\nIf Bonegrip sells books like this, perhaps he'll buy this one back.", objectives = "Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.", progress = "Hello, sir.\n\nMay I interest you in one of my tomes?", completion = "Ah, a copy of The Powers Below.  An interesting text, this is.  And some might find it useful...\n\nBut this one's in sad shape.  And look here!  There are notes in the margin of almost every page!\n\nHm...I know this copy.  I sold it to Bolgar last year.  Are you...a friend of his?  Yes, I thought you were.  You have that same fire behind your eyes!\n\nWell, by definition, a friend of Bolgar's is a friend of mine.  And we take care of our own, yes?" }
WordHunterWoW_QuestEN[969] = { title = "uck Be With You", description = "Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\n\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\n\nBring back 4 frostmaul shards, and my lucky charm will be yours.", objectives = "Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook.", progress = "Bring back da shards, and I be tellin' you more!", completion = "Ahh, yes... I will make da charm for ya now. Just you wait!" }
WordHunterWoW_QuestEN[970] = { title = "The Tower of Althalaxx", description = "Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.\n\nBring it to me, and I will be able to decipher the secrets held within.", objectives = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.", progress = "Have you acquired that soul gem?", completion = "Hmm, some dark magic enchants this soulstone. Let's see what's trapped inside, shall we?" }
WordHunterWoW_QuestEN[971] = { title = "Knowledge in the Deeps", description = "It is my duty to collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in to the west. That place is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript. Do this, and I will not forget it. Not even in these end days.", objectives = "Bring the Lorgalis Manuscript to Sentinel-trainee Issara at the Blackfathom Camp.", progress = "The journey to Ashenvale is long, and your task is not easy.  But if you get me the manuscript, <name>...then your reward will be great.", completion = "You found the manuscript!  What a joyous day this is!  Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!\n\nYour service to us is more than you know, <name>.  But I hope that this gift shows you the gratitude we extend to our allies." }
WordHunterWoW_QuestEN[972] = { title = "Water Sapta", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[973] = { title = "The Tower of Althalaxx", description = "Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.\n\nHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.", objectives = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.", progress = "You look a bit shaken up, <name>. Are you well?", completion = "It was a grand thing you did today, <name>. You should be quite proud of yourself for having faced down a warlock of such power.\n\nNow, let's see what we can learn from Ilkrud's writings." }
WordHunterWoW_QuestEN[974] = { title = "Finding the Source", description = "The hot springs here are a source of mystery to me. Where does the heat come from?\n\nLooking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!", objectives = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one.", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I'll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm..." }
WordHunterWoW_QuestEN[975] = { title = "ache of Mau'ari", description = "Now, before I give ya dis charm, I better explain how ta use it.\n\nIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?\n\nYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.\n\nWait here while I fix your charm.", objectives = "Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.", completion = "Here it is, <name>. Remember, ya have ta carry it with you. Why don't ya head back to da wilds, an' see what ya be findin' there?" }
WordHunterWoW_QuestEN[976] = { title = "Supplies to Auberdine", description = "Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.\n\nIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.", objectives = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.", completion = "You have done well today, <class>. The items we sent to aid Auberdine will be of immediate use in dealing with the dark threats that infest the forest.\n\nTake these with my heartfelt thanks." }
WordHunterWoW_QuestEN[977] = { title = "re We There, Yeti?", description = "Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!\n\nThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.\n\nRemember, I only want the best looking ones -- no beat up or broken horns, please!", objectives = "Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.", progress = "I've just about finished attaching the fur, <name>. Please, hurry back with those horns!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!" }
WordHunterWoW_QuestEN[978] = { title = "Moontouched Wildkin", description = "Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.\n\nDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, <name>. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.", objectives = "Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village.", progress = "Where could these powers have originated from? I think we are on the right track to find the answer, <name>.", completion = "Now I can compare the feathers... Let's see..." }
WordHunterWoW_QuestEN[979] = { title = "Find Ranshalla", description = "Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, <name>.\n\nA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?", objectives = "Find Ranshalla in eastern Winterspring.Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, <name>.\n\nA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?", completion = "Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn't mind company." }
WordHunterWoW_QuestEN[980] = { title = "The New Springs", description = "Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.\n\nWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.\n\nThanks again for helping me with my thermometer! See you later!", objectives = "Travel to Winterspring and speak with Donova Snowden.", completion = "Hi there, <name>. Yes, what Krakle told you is true..." }
WordHunterWoW_QuestEN[981] = { title = "The Tower of Althalaxx", description = "For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.", objectives = "Talk to Delgren the Purifier at Maestra's Post.For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.", completion = "I knew you would be up to the task, <name>.\n\nI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, <name>, as well as this gift." }
WordHunterWoW_QuestEN[982] = { title = "Deep Ocean, Vast Sea", description = "Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends.\n\nBoth captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.", objectives = "Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village.", progress = "The captains of those ships were good night elves, and they deserve a better fate than they were given.  Perhaps tending to their personal effects will be the best way to put their spirits to rest.", completion = "You've done us here in Auberdine a great service, lad.  We'll make sure that their effects are properly taken care of.\n\nAs for you, please have this.  It is the least I can do for someone with the bravery to set things right." }
WordHunterWoW_QuestEN[983] = { title = "Buzzbox 827", description = "Hey! Help me with my latest invention, the buzzbox. You can talk to people far away!\n\nMaybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance.\n\nEach one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pay ya...", objectives = "Collect 6 Crawler Legs and place them in Buzzbox 827.", progress = "Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.", completion = "As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.\n\n\"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn't want to fix another one, would ya?\"" }
WordHunterWoW_QuestEN[984] = { title = "How Big a Threat?", description = "Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.\n\nI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?", objectives = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.", completion = "This is terrible news indeed, <name>.\n\nWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[985] = { title = "How Big a Threat?", description = "You've already proven adept at scouting our enemy, <name>. Do you have what it takes to fight them as well?\n\nNot all adventurers prefer straightforward combat to the art of stealth and evasion.\n\nIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.", objectives = "Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.", completion = "Wash the blood from your garments, <name>, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss." }
WordHunterWoW_QuestEN[986] = { title = "A Lost Master", description = "<name>, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.\n\nTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.", objectives = "Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.", progress = "I can't in good conscience permit you to seek Volcor until I've crafted that cloak for you.", completion = "These will do nicely, <name>. I shall set to work on the cloak immediately.\n\nGive me a few moments, then return to me.\n\nOh, one more thing: after you've used the enchantment on the cloak you'll be limited in your interactions with others. If you can help it, do no more than speak to others. Much more than that could dispel the illusion." }
WordHunterWoW_QuestEN[990] = { title = "Trek to Ashenvale", description = "<name>, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.\n\nHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.", objectives = "Find Raene Wolfrunner in Ashenvale.<name>, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.\n\nHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.", completion = "Ah, a <class> from Darkshore. Selarin has done well to send you here so quickly, <name>. I wish your trip here wasn't under such dire stress. Perhaps with your help we can improve matters.\n\nI would start my visit by speaking to the other citizens of Astranaar. Some could surely use your aid." }
WordHunterWoW_QuestEN[991] = { title = "Finding Teronis", description = "A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod, which he knew to be resting at a shrine on an island in the lake.\n\nUnfortunately, we know that the lake has been invaded by some evil force. Please, <name>, find my friend.", objectives = "Find Teronis at Lake Falathim in Ashenvale.A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod, which he knew to be resting at a shrine on an island in the lake.\n\nUnfortunately, we know that the lake has been invaded by some evil force. Please, <name>, find my friend.", completion = "Teronis' body lies broken atop the island. For some unknown reason, the murlocs have left it alone.\n\nThe deep slashes across his corpse obviously came from the weapons and claws of the murlocs." }
WordHunterWoW_QuestEN[992] = { title = "Gadgetzan Water Survey", description = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!\n\nWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.\n\nTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!", objectives = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", progress = "Welcome back, Junior Surveyor <name>!  Have you completed your assignment yet?", completion = "What's this?  You were ambushed by some sort of bad mojo creepy-crawly?  Oh, this does not bode well for the Gadgetzan Water Company, no indeed...\n\nI guess I should have told you about the reports coming in on some crazy bug-creatures that appear to be sucking up all the water in the desert.  At first, I thought it was just a crock.  We have enough trouble with the nomads as is; I thought it was just more of their shenanigans.  Well, now we know at least!" }
WordHunterWoW_QuestEN[993] = { title = "A Lost Master", description = "The cloak is complete, <name>. The time has come to find Volcor. I can only hope we are in time.\n\nThe cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw.\n\nIf what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.", objectives = "Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.", completion = "Wonderful! Terenthis found someone to help me.\n\nAnd look, a moonstalker cloak...<cough> Oh... that hurts. Thank you, <name>.\n\nThe furbolgs wounded me before I managed to evade them. Give me a moment, and I should be fine to talk some more." }
WordHunterWoW_QuestEN[994] = { title = "Escape Through Force", description = "All right, <name>, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.\n\nTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.", objectives = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.", completion = "<name>! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond." }
WordHunterWoW_QuestEN[995] = { title = "Escape Through Stealth", description = "All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.\n\nRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.", objectives = "Escape the Furbolg cave and meet Terenthis in Auberdine.", completion = "<name>! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond." }
WordHunterWoW_QuestEN[996] = { title = "Corrupted Windblossom", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[997] = { title = "Denalan's Earth", description = "Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...\n\nMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.\n\nCan you take the package to him?", objectives = "Bring the package of Rare Earth to Denalan at Lake Al'Ameth.", progress = "You have something for me?", completion = "Ah, it's here!  I have waited for this rare earth for quite some time.  I hope it's still fresh...\n\nThank you for bringing it to me, <name>.  You are a <race> who is generous with his time." }
WordHunterWoW_QuestEN[998] = { title = "Corrupted Windblossom", description = "", objectives = "You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom. It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
WordHunterWoW_QuestEN[999] = { title = "When Dreams Turn to Nightmares", description = "", objectives = "" }
WordHunterWoW_QuestEN[1000] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", objectives = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, <class>.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well." }
WordHunterWoW_QuestEN[1001] = { title = "Buzzbox 411", description = "A tiny voice crackles from deep within the machine.\n\n\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach\n\nSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...\n\nJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"", objectives = "Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.", progress = "The machine's hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.", completion = "The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.\n\n\"Crawler wine is the best...\" *hic*\n\n\"What? Oh, you fixed it already? Wow, you're a fasht one. Sho, would ya like to fix another?\"\n\nYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds." }
WordHunterWoW_QuestEN[1002] = { title = "Buzzbox 323", description = "The Buzzbox gives a burst of static as you hear Wizbang begin to speak.\n\n\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"\n\nWizbang mumbles something incoherent before you hear a loud gulping sound.\n\n\"Thish one needs Moonstalker Fangs... 6 of 'em.\"", objectives = "Collect 6 Moonstalker Fangs and place them in Buzzbox 323.", progress = "Though you have yet to place the 6 Moonstalker Fangs inside, you believe you hear the sounds of static and incoherent gnome ramblings coming from within. Could someone else have fixed the machine already?", completion = "The Buzzbox suddenly leaps into action, and you can hear the distinct sounds of teeth being ground to dust coming from within.\n\n\"Sho, ya made it! Thatsh exshellent newsh... Sho... Why doncha move along? Oh! Unless you want another job!\"" }
WordHunterWoW_QuestEN[1003] = { title = "Buzzbox 525", description = "Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.\n\n\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"\n\nYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.\n\n\"4!\"", objectives = "Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.", progress = "You hear singing coming from Buzzbox 525.\n\n\"Though crawler wine's shweet, and thresher ale fine, and moonstalker moonshine ish grand. There's nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!\"\n\nThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.", completion = "\"Sho yash gotsh the scalps in? That'sh sho great... Wha? Well, yesh I shuppose ya have realized that I can speaksh to ya without the materials in the machine. But I was telling the truth when I shaid they were broken!\n\nSee, in addition to being communimacation toolsh, the Buzzboxes also brew and distill fine liquor. Shorry for any deceptshion, but the nightelves do not apprecimerate my liquor trade in their townsh. I put shomething special in thish box to show my gratitude for yer effortsh. Enjoy!\"" }
WordHunterWoW_QuestEN[1004] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", objectives = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, <class>.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well." }
WordHunterWoW_QuestEN[1005] = { title = "What Lurks Beyond", description = "", objectives = "" }
WordHunterWoW_QuestEN[1006] = { title = "What Lies Beyond", description = "", objectives = "" }
WordHunterWoW_QuestEN[1007] = { title = "The Ancient Statuettes", description = "I would charge you with a task, <class>.\n\nI was on my boat, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws! I fled and the rest, as they say, is history.\n\nI am an archaeologist of sorts, and I am attempting to the recover artifacts of the lost city.\n\nWill you head out onto the Zoram Strand to the southwest and recover any ancient statuettes you come across? They are the reason I have braved the dangers of the Zoram Strand.", objectives = "Collect 10 Ancient Statuettes.", progress = "Have you found the statuette, <name>?", completion = "You found it!  Thank you, <name>!\n\nThe old city of Zoram holds many secrets, and this statuette may be the key to many of them." }
WordHunterWoW_QuestEN[1008] = { title = "The Zoram Strand", description = "There is evil lurking on our northwestern coast, known as the Zoram Strand.\n\nIt is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths!\n\nReturn to me when your mission is complete.", objectives = "Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.", progress = "We cannot allow the naga to invade our coasts, <name>.  It is vital that you go to the Zoram Strand and complete your mission.", completion = "Very well done, <name>.  Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves.  We know this, for we share a history with them.\n\nIt is a history I care not to repeat." }
WordHunterWoW_QuestEN[1009] = { title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to their ancient locks.\n\nThat key is a ring, the Ring of Zoram. It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on her isle on the northern edge of the Zoram Strand. Please, <name>, retrieve the ring for me!", objectives = "Obtain the Ring of Zoram.", progress = "It is said that the Ring of Zoram is the key to any lock within the city.  Do you have it, <name>?", completion = "You found the ring!  Thank you, <name>.  Please take this as payment, and know that your deeds today will remain forever in my memory." }
WordHunterWoW_QuestEN[1010] = { title = "Bathran's Hair", description = "There is a plant that grows in the old ruins of Bathran's Haunt across the road to the east. The plant is called Bathran's Hair and is known to cure ailments of the spirit.\n\nNow the Horde are there harvesting the plant for their own evil schemes.\n\nThere is a sick child in Astranaar, and we believe that her illness is more than just physical. I promised my master that I would help seek a cure, but I am no fighter.\n\nWill you go to Bathran's Haunt and gather the plants?", objectives = "Collect 8 Bathran's Hair.", progress = "Have you gathered the Bathran's Hair, <name>?  The child's health grows weaker by the hour...", completion = "Ah, you have the hair!  Now I will mix a cure for the child, and pray my concoction works.\n\nAnd... Forsaken are at Bathran's Haunt?  Very troubling to hear, that is.  Very troubling indeed..." }
WordHunterWoW_QuestEN[1011] = { title = "Forsaken Diseases", description = "The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!\n\nThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.", objectives = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.", progress = "Did you find the camp, <name>?  Do you have a bottle of disease?", completion = "Very good, <name>.  Now... by testing the contents of this bottle, the goals of the Forsaken will be revealed!" }
WordHunterWoW_QuestEN[1012] = { title = "Insane Druids", description = "The druids are dead, killed by their leaders who were driven insane by the Horde tainting the Forest Heart! I can feel the corruption even from here and I dare go no further.\n\nWhile I am too well attuned to Ashenvale and the Forest Heart, you... you could descend into the barrow den and do what must be done. I've laid down breadcrumbs for you in there.\n\nThough it tears me apart, I must ask that you put to rest the druids' once great leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", objectives = "Slay the insane druids: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", completion = "I felt the anguish of the Dor'danil Barrows lessen, and knew you had completed your task.\n\nIt was grim work you did, <name>, for the spirits you destroyed were merely victims of the Forsaken's evil.  But with their destruction, let us hope the other maddened spirits find peace." }
WordHunterWoW_QuestEN[1013] = { title = "The Book of Ur", description = "<name>, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...", objectives = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", progress = "Did you find the book, <name>?", completion = "Very good.  This book will add nicely to my collections of the workings of Ur.  His knowledge was great, but his conscience held him from true power.  And so when the Scourge came and his strength was tested, it failed.\n\nWe of the Forsaken cannot afford such weakness, if we are to survive...\n\n...If we are to conquer." }
WordHunterWoW_QuestEN[1014] = { title = "Arugal Must Die", description = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, <name>. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!", objectives = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", progress = "With Arugal's death we stand to increase the Dark Lady's stronghold on Lordaeron.", completion = "Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, <name>. Your tenacity shall be rewarded." }
WordHunterWoW_QuestEN[1015] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", objectives = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, <class>? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" }
WordHunterWoW_QuestEN[1016] = { title = "Retaking Mystral Lake", description = "We could easily have held Silverwind Refuge from the Horde had they not taken control of our water elemental defenders on Mystral Lake.\n\nOne of their shaman summoned in Tideress, and old and angry water spirit of the forest who befouled our elementals and turned them against us. With the lake and the Horde pressing in on us, we had no choice but to retreat to the spire here.\n\nGo east. Take the lake back so that we will have a chance to retake the refuge some day.", objectives = "Slay 12 Befouled Water Elementals and Tideress.", progress = "Since you must destroy the bracers to kill the elementals, it will probably be difficult to find the specific ones that contain the information the divining scroll needs. You can trade bracers with others in order to obtain the ones you need, or perhaps you have the divined paper already?", completion = "Well done, <name>, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay." }
WordHunterWoW_QuestEN[1017] = { title = "Mage Summoner", description = "There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.\n\n<name>, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.\n\nDestroy him and bring me his head. Be wary though, the Horde may be watching for you.", objectives = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.", progress = "Is it done? Is Sarilus Foulborne dead?", completion = "Now I can see that repugnant smile wiped from his face forever. You have done very well, <name>. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing." }
WordHunterWoW_QuestEN[1018] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", objectives = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "Greetings, <class>.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here. Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides. Remember this as you work on behalf of the Circle, and you will do well." }
WordHunterWoW_QuestEN[1019] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", objectives = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, <class>? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" }
WordHunterWoW_QuestEN[1020] = { title = "Orendil's Cure", description = "<name>, now that it has been bathed in Elune's blessed light, I believe that the concoction will help the afflicted child. Please, take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south and then east. However, if you'd like to get there more swiftly, speak with Sentinel Avana.", objectives = "Bring Orendil's Cure to Pelturas Whitemoon at Astranaar in Ashenvale.", progress = "I must apologize, for I have no time to speak.  My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great.  This cure gives me hope, when before I had little..." }
WordHunterWoW_QuestEN[1021] = { title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n<name>, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", objectives = "Find Anilia at Xavian in Ashenvale.Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n<name>, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", completion = "Judging by the gaping wound in her side, Anilia is on the verge of death." }
WordHunterWoW_QuestEN[1022] = { title = "The Howling Vale", description = "Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.\n\nTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.", objectives = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.", completion = "The Tome of Mel'Thandris works in strange ways. The events it records, the events it shows... No one truly understands why it does what it does.\n\nNonetheless, it is clear that what Priestess Starsong received--this Scythe of Elune--bears further investigation." }
WordHunterWoW_QuestEN[1023] = { title = "The Lost Gem", description = "As you rummage through Teronis' belongings, you find a journal that is still in good condition.\n\nYou take the journal and leave Teronis' corpse as is.\n\nThe only thing left to do is find the gem Teronis was seeking. Orendil mentioned it being in the area. Perhaps the tendrils have it...?", objectives = "Find the Glowing Gem.", progress = "Ah, welcome back, <name>.", completion = "This is terrible, <name>. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis' body as soon as possible.\n\nYou have Teronis' journal and the gem he was seeking. Do you think you're capable of completing his task? I would rest much better knowing his death was not in vain." }
WordHunterWoW_QuestEN[1024] = { title = "Dryad Delivery", description = "Ah, there you are, <name>. I've pored over the notes Teronis has made and it sounds like your next course of action is to find the other pieces of Dartol's rod.\n\nI would start by heading east along the road to Raynewood Tower.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", objectives = "Speak with Shael'dryn at Raynewood Tower in Ashenvale.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed. What can I help you with?" }
WordHunterWoW_QuestEN[1025] = { title = "An Aggressive Defense", description = "Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills.\n\nAlong the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents.\n\nAid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind.\n\nI believe their camps are south of the road... be careful.", objectives = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.", completion = "You have done well, <name>. Thank you." }
WordHunterWoW_QuestEN[1026] = { title = "Search the Bole", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nTo find the next piece of the rod, you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here near the Felwood border, at the Howling Vale. Once you have it, look for a small glade through the tunnel at the vale. The chest should be hidden around there.", objectives = "Find the Wooden Key and use it to obtain the Iron Shaft portion of Dartol's Rod.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, <name>." }
WordHunterWoW_QuestEN[1027] = { title = "Playing Possum", description = "The last piece of the rod is held by druids of the claw. I asked their leader, Oso Bramblepaw, to give it to me, but he and his guardians nearly killed me! Clearly they too were affected by the Horde's corruption of the Forest Heart.\n\nBut, I have an idea for how you can get into Oso's cave and grab the pommel.\n\nEver since I was a faun, I've been pretty good at playing possum. It works great against bears! I can teach you! Go east to the Shady Nook, and if they try to get you, just use my technique.", objectives = "Obtain the final piece of Dartol's Rod, the Iron Pommel.", progress = "Did you find the final piece of the rod, <name>?", completion = "You found the final piece? Wonderful for you... and for Raene.\n\nI guess we'll have to see about repairing it, won't we?" }
WordHunterWoW_QuestEN[1028] = { title = "Raene's Cleansing", description = "Here is the completed rod, <name>. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.\n\nWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.\n\nHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.\n\nOnce there, place the rod within the shrine... the rest is magic. Hehe.", objectives = "Find the hidden shrine and re-enchant Dartol's Rod.", progress = "You can sense a subtle yet powerful force within the shrine and surrounding trees.\n\nYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...", completion = "After the glow dies, you can see the re-enchanted rod within the shrine's basin." }
WordHunterWoW_QuestEN[1029] = { title = "Return to Raene", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nBe careful... I sense a great deal of power within it for both good and ill. I hope that you and Raene know what you are doing.\n\nGood luck, <name>.", objectives = "Deliver Dartol's Rod to Raene Wolfrunner at Astranaar in Ashenvale.", completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nTeronis would be proud to see his quest is continuing even after his tragic passing." }
WordHunterWoW_QuestEN[1030] = { title = "Dartol's Rod", description = "I'm not completely certain what Teronis had in mind next, but if what he said was true about the rod's power, then it will allow you to take on another form altogether, presumably that of a furbolg.\n\nPerhaps he meant to use its powers to get closer to them, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was uncorrupted.\n\nI would start with one known as Krolg. Seek his hut southeast of Mystral Lake.", objectives = "Use Dartol's Rod to be able to communicate with Krolg at Krolg's Hut in Ashenvale.\n\nProvided item:", completion = "Yes, yes... you are one of my kind, but still whole. Still clean.\n\nI am unsure how you have escaped the atrocities the night elves have visited upon our people, but I am glad to know that I am no longer alone.\n\nCorruption now runs through the veins of our kin, young one, corruption brought down upon us by the prideful night elves. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness." }
WordHunterWoW_QuestEN[1031] = { title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", objectives = "Obtain the Branch of Cenarius.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over..." }
WordHunterWoW_QuestEN[1032] = { title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", objectives = "Obtain 16 Satyr Horns.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind <race>. My sister's spirit is gladdened by your efforts." }
WordHunterWoW_QuestEN[1033] = { title = "Elune's Tear", description = "I'd hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through her. We must find more powerful medicine! Thankfully, Orendil spoke to me of further remedies should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the remains of Iris Lake, destroyed by the eruption of Thunder Peak, northeast of Astranaar. Orendil said the stone will wash away corruption.\n\nPlease, <name>, bring me Elune's Tear and pray it will end my child's sickness!", objectives = "Collect Elune's Tear.", progress = "<name>, did you find Iris Lake?  Do you have the Tear?", completion = "Oh, you found it!  I will place the tear in a stew, and pray that it will cure her.\n\nThank you!  Thank you, <name>!" }
WordHunterWoW_QuestEN[1034] = { title = "The Ruins of Stardust", description = "Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her.\n\nOrendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me.\n\nThe Ruins of Stardust lie to the south, <name>.  May Elune speed your journey.", objectives = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.", progress = "Do you yet have the Stardust, <name>?", completion = "You gathered the dust!  I will create a poultice from these -- it should bring down Relara's fever.\n\nThank you again, <name>.  Without your help, my child would surely perish." }
WordHunterWoW_QuestEN[1035] = { title = "Fallen Sky Lake", description = "Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone.\n\nWe used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came.\n\nTheir leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle.\n\nAnd to do that, I fear that you must slay him.", objectives = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.", progress = "Did you face the Shadethicket Oracle, <name>?  If so, then please hand me the fallen moonstone.  Relara has strength left for only a few more breaths!", completion = "Oh, <name>, you have saved my daughter!  I know the power of the moonstone will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this.  Other than Relara, it is my most dear possession." }
WordHunterWoW_QuestEN[1036] = { title = "Avast Ye, Scallywag", description = "{name}... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty men just like you for a special mission.\n\nIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.", objectives = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.", completion = "Avast ye, scallywag.  I hears that ye be the type for a bit o' the skullduggery.  Well, if yer no friend of Booty Bay, then ye might have a special place with the Bloodsail Buccaneers.\n\nArrrrr..." }
WordHunterWoW_QuestEN[1037] = { title = "Velinde Starsong", description = "Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.\n\nI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.\n\nSurely she will understand the import of such information.", objectives = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.\n\nI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.\n\nSurely she will understand the import of such information.", completion = "Velinde Starsong? That the priestess disappeared some time ago is almost certainly common knowledge. As to further details about the events that surrounded her departure... it would take good reason for me to divulge such information." }
WordHunterWoW_QuestEN[1038] = { title = "Velinde's Effects", description = "The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.\n\nI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.", objectives = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", progress = "What'd you find out?", completion = "It seems that Velinde's disappearance is more troubling than it originally appeared. Even still, I cannot believe that she has come to a bad end. Perhaps it would be beneficial for us to make contact with her.\n\n<name>, since you have shown a vested interest in this matter, I would like to enlist your aid." }
WordHunterWoW_QuestEN[1039] = { title = "The Barrens Port", description = "Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.\n\nFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, <name>, warriors of the Horde patrol the land. You will be safe at the port, though.", objectives = "Speak with Wharfmaster Dizzywig in Ratchet.Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.\n\nFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, <name>, warriors of the Horde patrol the land. You will be safe at the port, though.", completion = "<race>, eh? Must admit, we don't get much of your type out here. Looking for someone, eh? Just give me a moment, I'm sure I have it written in one of my ledgers.\n\nLot of people travel through here, though, so just give me a moment." }
WordHunterWoW_QuestEN[1040] = { title = "Passage to Booty Bay", description = "Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for you.", objectives = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for you.", completion = "Yes? Now, it doesn't look to me like you're the sort with goods that need shipping, so either you're looking for a job with my caravan--and there's no jobs to be had now--or you're probably talking to the wrong goblin.\n\nSo which one is it?" }
WordHunterWoW_QuestEN[1041] = { title = "The Caravan Road", description = "Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times.", objectives = "Speak with Clerk Daltry in Darkshire.Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times.", completion = "With all the strange happenings of the last few years, I keep as good records of strangers as I can. Never know when it might come in handy... though it's usually not pleasant business when it does. Not to suggest anything about this Velinde you're looking for." }
WordHunterWoW_QuestEN[1042] = { title = "The Carevin Family", description = "No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?\n\nThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.", objectives = "Speak with Jonathan Carevin in Darkshire.No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?\n\nThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.", completion = "Dark times these are. Ill news is whispered from every swaying branch, and evil can be found under every rock.\n\nAnd in such times an unknown stranger enters my home and asks of worgen... I'll ask no forgiveness for my suspicions, only answers.\n\nAnd answers, I will have." }
WordHunterWoW_QuestEN[1043] = { title = "The Scythe of Elune", description = "Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.\n\nThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.\n\nGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil.", objectives = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.", completion = "It is an interesting story you tell, <name>. Though the Carevin family's influence is not large enough that we might find the root of these troubles and finish them once and for all, we will do what we can to contain the worgens' numbers in Duskwood.\n\nAlready I have instructed Calor to make this his first priority." }
WordHunterWoW_QuestEN[1044] = { title = "Answered Questions", description = "We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, <name>, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.", objectives = "Return to Thyn'tel Bladeweaver in Darnassus.We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, <name>, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.", completion = "So this is the fate of Velinde, is it? The high priestess will be disappointed to hear of this, they were good friends before her disappearance. Still, the Scythe of Elune was surely granted to her as a boon by our goddess, and it is unsettling to me that it has fallen out of her servants' hands.\n\nAnother matter for another time, however. I owe you my thanks in no small amount for what you have accomplished." }
WordHunterWoW_QuestEN[1045] = { title = "A New Adornment", description = "I'm certain that the long-dead wizard, Dartol, intended to use his rod to subjugate and destroy us just as the night elves and orcs have, but I think now we'll put that thing to an unintended use.\n\nRan Bloodtooth is the king of all of the Ashenvale furbolg. His tribe, the Bloodtooth, are the most powerful and keep themselves secluded in a camp just to the east.\n\nKill them all and bring back his skull. Let us see if we can put it to good use.", objectives = "Obtain Ran Bloodtooth's Skull and Dartol's Rod.", progress = "Have you slain Ran yet, my friend?\n\nEven the Night elves do not truly deserve his wrath. His hatred burns even brighter than my own, but his mind is no longer his own. He is a threat to all the natural creatures of this forest.", completion = "You have done well, my friend.\n\nThe forest is still tainted, but at least we know we have done a small part to return it to its former glory. If you wish to return to me again, I would enjoy the company of my own kind.\n\nBe well. Perhaps our tribes will meet again under less violent times." }
WordHunterWoW_QuestEN[1046] = { title = "True Power of the Rod", description = "Now, take the rod and while using its power, speak with my brother, Ota Wen.\n\nOta is amongst the other furbolg that the orcs have captured and have penned in the giant cage on the north side of Silverwind Refuge. The rod will allow you to convince Ota and the other furbolg to rise up and attack the Horde.\n\nThen you may go wherever your path leads you. Just know that you have found a new friend for that which you have done.", objectives = "Use Dartol's Rod and speak with Ota Wen. Convince him to rise up against his Horde oppressors.", progress = "The Sentinels do what they can here in Ashenvale, but it's thanks to humans like you that we have gained the ground we have.", completion = "So, this is the skull of the fiercest furbolg threat in Ashenvale?\n\nI am more than pleased with your abilities, <name>. The Sentinels cannot thank you enough. I hope we can rely on you again in the future to help our people.\n\nI shall put this skull in a place of reverence for others to see.\n\nTeronis would be proud. Thank you again." }
WordHunterWoW_QuestEN[1047] = { title = "The New Frontier", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", objectives = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", completion = "What makes you think I wish to be pestered by the likes of you, <class>? Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere. By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?" }
WordHunterWoW_QuestEN[1048] = { title = "Into The Scarlet Monastery", description = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, <class>, and lay waste to High Inquisitor Whitemane and her top lieutenants.You will be able to choose one of these rewards:", objectives = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity." }
WordHunterWoW_QuestEN[1049] = { title = "Compendium of the Fallen", description = "The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?\n\nThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.\n\nDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.", objectives = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.", progress = "Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.\n\nOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.\n\nHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...", completion = "The Compendium of the Fallen! I was beginning to wonder if the very book existed!\n\nYou have served the tauren of Thunder Bluff well, <name>. Your dedication shall not be forgotten." }
WordHunterWoW_QuestEN[1050] = { title = "Mythology of the Titans", description = "The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.\n\nBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.\n\nBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.\n\nBring it to me and perhaps together we can unlock the secrets of the past!", objectives = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", progress = "The Monastery was a seminary for Paladins-in-training. Once a stronghold of the Light, it fell into the hands of the crazed zealots of the Scarlet Crusade.\n\nThe Crusade believed their goal a noble one: to purify the land of the undead plague. But insanity tainted their plight and now they stand enemies to all.\n\nBring Mythology of the Titans to me so I can study it and house it here in Ironforge.\n\nThe corrupt halls of the Monastery are no place for such a historical treasure.", completion = "You have rescued the sacred text!\n\nYour journey was long and acquiring the book was undoubtedly no easy task. But  the dwarves of Ironforge stand to benefit from your success.\n\nThank you, <name>, on behalf of the Explorers' League." }
